window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["生活"]=[{"uid":"1e77033d-2c4f-4e60-8d42-3b1529f3c93c","title":"横吹曲辞 折杨柳","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["二月风光半，三边戍不还。","年华妾自惜，杨柳为君攀。","落絮缘衫袖，垂条拂髻鬟。","那堪音信断，流涕望阳关。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月"],"cats":{"抒情":["闺怨"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.415},{"uid":"a0d7cfef-2d17-4f6b-983f-ed65c3dff9a2","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 四","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹赤白，尽是阻军行。","若是（京本作「似」）虹桥栏着路，且须盘泊犒（京本作「靠」）军兵，不久却回程。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"0afe4eae-ded2-4a70-ae06-6144d4e77cf0","title":"杂曲歌辞 壮士行","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阴风振寒郊，猛虎正咆哮。","徐行出烧地，连吼入黄茆。","壮士走马去，镫前弯玉弰。","叱之使人立，一发如铍交。","悍睛忽星坠，飞血溅林梢。","彪炳为我席，膻腥充我庖。","里中欣害除，贺酒纷号呶。","明日长桥上，倾城看斩蛟。"],"theme":"爱情相思","theme2":[],"style":"悲慨","style2":[],"mood":"慷慨","mood2":[],"scene":["酒"],"cats":{"生活":["写桥"]},"theme_conf":0.65},{"uid":"655ae29b-c115-4b27-a0b8-caa7e01d1808","title":"武威同诸公过杨七山人得藤字","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["幕府日多暇，田家岁复登。","相知恨不早，乘兴乃无恒。","穷巷在乔木，深斋垂古藤。","边城唯有醉，此外更何能。"],"theme":"山水田园","theme2":["咏史怀古","民生疾苦"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"生活":["田野"]},"theme_conf":0.399},{"uid":"bea6f283-8f90-49b5-8842-1cb906816548","title":"古从军行","author":"李颀","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["白日登山望烽火，黄昏饮马傍交河。","行人刁斗风沙暗，公主琵琶幽怨多。","野云万里无城郭，雨雪纷纷连大漠。","胡鴈哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲桃入汉家。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["豪放","雄浑"],"mood":"愁怨","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.765},{"uid":"b67cee37-9190-4581-89ec-473df5ef0c6f","title":"到村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碧涧虽多雨，秋沙先少泥。","蛟龙引子过，荷芰逐花低。","老去参戎幕，归来散马蹄。","稻粱须就列，榛草即相迷。","蓄积思江汉，疎顽惑町畦。","稍酬知己分，还入故林栖。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","雨","江"],"cats":{"抒情":["友情"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.707},{"uid":"01d61dfa-6c6e-421d-a5b3-c7db62f9d7fe","title":"题杭州孤山寺","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楼台耸碧岑，一径入湖心。","不雨山长润，无云水自阴。","断桥荒藓涩，空院落花深。","犹忆西窗月，钟声在北林。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["山","楼"],"cats":{"抒情":["孤独"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.56},{"uid":"ba10246a-c026-41e7-87a9-2e6ce2a27559","title":"建都十二韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["苍生未苏息，胡马半乾坤。","议在云台上，谁扶黄屋尊。","建都分魏阙，下韶辟荆门。","恐失东人望，其如西极存。","时危当雪耻，计大岂轻论。","虽倚三阶正，终愁万国飜。","牵裾恨不死，漏网荷殊恩。","永负汉庭哭，遥怜湘水魂。","穷冬客江劒，随事有田园。","风断青蒲节，霜埋翠竹根。","衣冠空穰穰，关辅久昏昏。","愿枉长安日，光辉照北原。"],"theme":"边塞征战","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["冬","园林","雪"],"cats":{"抒情":["伤感"],"四季":["冬天"],"生活":["田野"]},"theme_conf":0.531},{"uid":"f4b72624-5f7c-4885-940b-5c1812023ead","title":"初入秦川路逢寒食","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["洛阳芳树映天津，灞岸垂杨窣地新。","直为经过行处乐，不知虚度两京春。","去年余闰今春早，曙色和风著花草。","可怜寒食与清明，光辉幷在长安道。","自从关路入秦川，争道何人不戏鞭。","公子途中妨蹴踘，佳人马上废秋千。","渭水长桥今欲渡，葱葱渐见新丰树。","远看骊岫入云霄，预想汤池起烟雾。","烟雾氛氲水殿开，暂拂香轮归去来。","今岁清明行已晚，明年寒食更相陪。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"人物":["女子"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.9},{"uid":"cp21c68dc72e21cb","title":"六州歌头","author":"张孝祥","dynasty":"宋","section":"宋词","form":"词","paragraphs":["长怀望断，关塞莽然平。","征尘暗，霜风劲，悄边声。","黯销凝。","追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。","隔水毡乡，落日牛羊下，区脱纵横。","看名王宵猎，骑火一川明。","笳鼓悲鸣。","遣人惊。","念腰间箭，匣中剑，空埃蠹，竟何成。","时易失，心徒壮，岁将零。","渺神京。","干羽方怀远，静烽燧，且休兵。","冠盖使，纷驰骛，若为情。","闻道中原遗老，常南望，羽葆霓旌。","使行人到此，忠愤气填膺。","有泪如倾。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放","冲淡"],"mood":"慷慨","mood2":["悲怆"],"scene":["塞外"],"cats":{"抒情":["伤感"],"生活":["边塞"]},"theme_conf":0.75},{"uid":"6d2e12c0-c1b8-4242-888c-9dba1a8f93ce","title":"和张仆射塞下曲 二","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["林暗草惊风，将军夜引弓。","平明寻白羽，没在石棱中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":1.0},{"uid":"b2898783-b22c-4ded-b6c0-492b879a3b2d","title":"横吹曲辞 出塞","author":"马戴","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金带连环束战袍，马头冲雪度临洮。","卷旗夜劫单于帐，乱斫胡兵缺宝刀。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"cp1acc2f34cdbd10","title":"东风第一枝","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["巧沁兰心，偷黏草甲，东风欲障新暖。","谩凝碧瓦难留，信知暮寒轻浅。","行天入镜，做弄出、轻松纤软。","料故园、不卷重帘，误了乍来双燕。","青未了、柳回白眼。","红欲断、杏开素面。","旧游忆著山阴，厚盟遂妨上苑。","寒炉重暖，便放慢春衫针线。","恐凤靴、挑菜归来，万一灞桥相见。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"3205a2f2-b86f-4f86-9003-dc338f8f839d","title":"和卢赞府游纪国道场","author":"慧净","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["日光通汉室，星彩晦周朝。","法城从此构，香阁本岧峣。","株盘仰承露，刹凤俯摩霄。","落照侵虚牖，长虹拖跨桥。","高才暂骋目，云藻随飘飖。","欲追千里骥，终是谢连镳。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"294f0816-30dd-4941-bb26-bb50378c91b0","title":"濮中言怀","author":"沈千运","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣朝优贤良，草泽无遗匿。","人生各有命，在余胡不淑。","一生但区区，五十无寸禄。","衰退当弃捐，贫贱招毁讟。","栖栖去人世，屯踬日穷迫。","不如守田园，岁晏望丰熟。","壮年失宜尽，老大无筋力。","始觉前计非，将贻后生福。","童儿新学稼，少女未能织。","顾此烦知己，终日求衣食。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["友情"],"生活":["田野"]},"theme_conf":1.0},{"uid":"21173c18-b7d0-4c57-a29b-3cde7a7a0af4","title":"鼓吹曲辞 鼓吹铙歌 铁山碎","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["铁山碎，大漠舒。","二虏劲，连穹庐。","背北海，专坤隅。","岁来侵边，或傅于都。","天子命元帅，奋其雄图。","破定襄，降魁渠。","穷竟窟宅，斥余吾。","百蛮破胆，边氓苏。","威武辉耀，明鬼区。","利泽弥万祀，功不可逾。","官臣拜手，惟帝之谟。"],"theme":"山水田园","theme2":["边塞征战"],"style":"豪放","style2":["幽峭","雄浑"],"mood":"恬淡","mood2":[],"scene":["塞外","山"],"cats":{"生活":["边塞"]},"theme_conf":0.512},{"uid":"cpd9253d8e5dea2b","title":"点绛唇","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["燕雁无心，太湖西畔随云去。","数峰清苦。","商略黄昏雨。","第四桥边，拟共天随住。","今何许。","凭栏怀古。","残柳参差舞。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"清新","style2":["冲淡"],"mood":"恬淡","mood2":[],"scene":["鸟","雨"],"cats":{"抒情":["怀古"],"生活":["写桥"]},"theme_conf":0.582},{"uid":"684e16f6-839b-4600-b680-996ac541ced0","title":"过山农家","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["板桥人渡泉声，茆簷日午鸡鸣。","莫嗔焙茶烟暗，却喜晒谷天晴。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"生活":["乡村","写桥"]},"theme_conf":0.617},{"uid":"a5546090-d778-47ce-abde-d3184e225f64","title":"江村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["清江一曲抱村流，长夏江村事事幽。","自去自来堂上燕，相亲相近水中鸥。","老妻画纸为碁局，稚子敲针作钓钩。","多病所须唯药物，微躯此外更何求。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["夏","江"],"cats":{"四季":["夏天"],"山水":["江河"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.832},{"uid":"451fc40e-4dad-47ec-88e7-bb54fbc6bb60","title":"东平留赠狄司马","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古人无宿诺，兹道以为难。","万里赴知己，一言诚可叹。","马蹄经月窟，劒术指楼兰。","地出北庭尽，城临西海寒。","森然瞻武库，则是弄儒翰。","入幕绾银绶，乘轺兼铁冠。","练兵日精锐，杀敌无遗残。","献捷见天子，论功俘可汗。","激昂丹墀下，顾盼青云端。","谁谓纵横策，翻为权势干。","将军既坎𡒄，使者亦辛酸。","耿介挹三事，羇离从一官。","知君不得意，他日会鹏抟。"],"theme":"寄赠酬答","theme2":["边塞征战"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["友情"],"人生":["梦想"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.86},{"uid":"f699ef22-319a-481b-8575-103300613ab9","title":"仆射来示有三春向晚四者难幷之说诚哉是言辄引起题重为联句疲兵再战勍敌难降下笔之时冁然自哂走呈仆射兼简尚书","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三春今向晚，四者昔难幷。","借问低眉坐，何如携手行。","旧游多过隙，新宴且寻盟。","鹦鹉林须乐，麒麟阁未成。","分阴当爱惜，迟景好逢迎。","林野熏风起，楼台谷雨晴。","墙低山半出，池广水初平。","桥转长虹曲，舟回小鹢轻。","残花犹布绣，密竹自闻笙。","欲过芳菲节，难忘宴慰情。","月轮行似箭，时物始如倾。","见雁随兄去，听莺求友声。","蕙长书带展，菰嫩剪刀生。","坐密衣裳暖，堂虚丝管清。","峰峦侵碧落，草木近朱明。","与点非沂水，陪膺是洛城。","拨醅争绿醑，卧酪待朱樱。","几处能留客，何人唤解酲。","旧仪尊右揆，新命宠春卿。","有喜鹊频语，无机鸥不惊。","青林思小隐，白雪仰芳名。","访旧殊千里，登高赖九城。","酂侯司管钥，疏傅傲簪缨。","纶綍曾同掌，烟霄即上征。","册庭尝接武，书殿忝连衡。","兰室春弥馥，松心晚更贞。","琴招翠羽下，钩掣紫鳞呈。","只愿回乌景，谁能避兕觥。","方知醉兀兀，应是走营营。","凤阁鸾台路，从他年少争。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"天气":["彩虹"],"人生":["战争"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"cp157df1f3a98fb8","title":"夜游宫","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["叶下斜阳照水。","卷轻浪、沈沈千里。","桥上酸风射眸子。","立多时，看黄昏，灯火市。","古屋寒窗底。","听几片、井桐飞坠。","不恋单衾再三起。","有谁知，为萧娘，书一纸。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["闺怨"],"人生":["读书"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"e40d3f8a-7e0c-47df-b0a4-f2e55fded03a","title":"陪包谏议湖墅路中举帆","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧萧凉雨歇，境物望中闲。","风际片帆去，烟中独鸟还。","断桥通远浦，野墅接秋山。","更喜陪清兴，尊前一解颜。"],"theme":"山水田园","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["孤寂","恬淡"],"scene":["舟"],"cats":{"抒情":["孤独"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"cpc063f64461105d","title":"满庭芳","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["风老莺雏，雨肥梅子，午阴嘉树清圆。","地卑山近，衣润费垆烟。","人静乌鸢自乐，小桥外、新绿溅溅。","凭栏久，黄芦苦竹，拟泛九江船。","年年。","如社燕，飘流瀚海，来寄修椽。","且莫思身外，长近尊前。","憔悴江南倦客，不堪听、急管繁弦。","歌筵畔，先安簟枕，容我醉时眠。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["园林","鸟","江南","花","江","雨"],"cats":{"生活":["写桥"]},"theme_conf":1.0},{"uid":"0e2cf65b-d757-4698-97a0-31aedb02f4a3","title":"寒雨朝行视园树","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["柴门杂树向千株，丹橘黄甘此地无。","江上今朝寒雨歇，篱中秀色画屏纡。","桃蹊李径年虽故，栀子红椒艳复殊。","鏁石藤稍元自落，倚天松骨见来枯。","林香出实垂将尽，叶蔕辞枝不重苏。","爱日恩光蒙借贷，清霜杀气得忧虞。","衰颜更觅藜床坐，缓步仍须竹杖扶。","散骑未知云阁处，啼猨僻在楚山隅。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["雨","园林"],"cats":{"天气":["写雨"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"068dc817-95dd-4f0f-8f5e-820afe25e3bb","title":"建中癸亥岁奉天除夜宿武当山北茅平村","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岁除日又暮，山险路仍新。","驱传迷深谷，瞻星记北辰。","古亭聊假寐，中夜忽逢人。","相问皆呜咽，伤心不待春。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","山","除夕"],"cats":{"生活":["乡村"],"节日":["春节"]},"theme_conf":0.699},{"uid":"a44b9d2a-65fb-40d6-ba19-6cea71b89b53","title":"种莴苣","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阴阳一错乱，骄蹇不复理。","枯旱于其中，炎方惨如毁。","植物半蹉跎，嘉生将已矣。","云雷歘奔命，师伯集所使。","指麾赤白日，澒洞青光起。","雨声先已风，散足尽西靡。","山泉落沧江，霹雳犹在耳。","终朝纡飒沓，信宿罢潇洒。","堂下可以畦，呼童对经始。","苣兮蔬之常，随事蓺其子。","破块数席间，荷锄功易止。","两旬不甲坼，空惜埋泥滓。","野苋迷汝来，宗生实于此。","此辈岂无秋，亦蒙寒露委。","飜然出地速，滋蔓户庭毁。","因知邪干正，掩抑至没齿。","贤良虽得禄，守道不封己。","拥寒败芝兰，众多盛荆杞。","中园陷萧艾，老圃永为耻。","登于白玉盘，借以如霞绮。","苋也无所施，胡颜入筐篚。"],"theme":"山水田园","theme2":["节令风俗"],"style":"绮丽","style2":["清新"],"mood":"惆怅","mood2":["孤寂"],"scene":["园林","夏","秋"],"cats":{"四季":["夏天","秋天"],"生活":["田野"]},"theme_conf":0.6},{"uid":"9a4d3eae-fe01-46c7-a28b-8b518614a508","title":"和张仆射塞下曲 四","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["野幕敞琼筵，羌戎贺劳旋。","醉和金甲舞，雷鼓动山川。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","酒"],"cats":{"生活":["边塞"]},"theme_conf":0.76},{"uid":"a8133806-1aeb-44d9-8b5e-6309fe6bd8cb","title":"同吕员外酬田著作幕门军西宿盘山秋夜作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碛路天早秋，边城夜应永。","遥传戎旅作，已报关山冷。","上将顿盘阪，诸军徧泉井。","绸缪阃外书，慷慨幕中请。","能使勋业高，动令氛雾屏。","远途能自致，短步终难骋。","羽翮时一看，穷愁始三省。","人生感然诺，何啻若形影。","白发知苦心，阳春见佳境。","星河连塞络，刁斗兼山静。","忆君霜露时，使我空引领。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["秋","夜","山","塞外"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"天气":["星星"],"生活":["边塞"]},"theme_conf":0.428},{"uid":"1274d774-d716-4705-8497-c3cdd510a7c0","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 早梅桥","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["早梅花，满枝发。","东风报春春未彻，紫萼迎风玉珠裂。","杨柳未黄莺结舌，委素飘香照新月。","桥边一树伤离别，游荡行人莫攀折。","不竞江南艳阳节，任落东风伴春雪。"],"theme":"送别","theme2":["咏史怀古"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","冬","花","雪"],"cats":{"抒情":["离别","怀古"],"四季":["春天"],"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.576},{"uid":"6a5f693e-7c8d-4c20-a1c3-bfec8a474e6f","title":"重别西湖","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["浦边梅叶看凋落，波上双禽去寂寥。","吹管曲传花易失，织文机学羽难飘。","雪欺春早摧芳蕚，隼励秋深拂翠翘。","繁艳彩毛无处所，尽成愁叹别谿桥。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["江南","江"],"cats":{"抒情":["离别","伤感"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"095c38dc-90fd-452f-812f-7dbf7c5662a2","title":"横吹曲辞 出塞","author":"窦威","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["匈奴屡不平，汉将欲纵横。","看云方结阵，却月始连营。","潜军度马邑，扬斾掩龙城。","会勒燕然石，方传车骑名。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":1.0},{"uid":"f540f519-e3c4-41c2-b299-f1d255977705","title":"宿府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["清秋幕府井梧寒，独宿江城蜡炬残。","永夜角声悲自语，中天月色好谁看。","风尘荏苒音书绝，关塞萧条行路难。","已忍伶俜十年事，强移栖息一枝安。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"孤寂","mood2":[],"scene":["月","塞外"],"cats":{"抒情":["孤独"],"天气":["月亮"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"90f7a912-549f-444d-9b12-99c89f224b94","title":"自常州还江阴途中作","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["处处空篱落，江村不忍看。","无人花色惨，多雨鸟声寒。","黄霸初临郡，陶潜未罢官。","乘春务征伐，谁肯问凋残。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"d669feeb-edbb-433a-b46f-9c302e3e7516","title":"哭裴少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["世人谁不死，嗟君非生虑。","扶病适到官，田园在何处？","公才群吏感，葬事他人助。","余亦未识君，深悲哭君去。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["园林"],"cats":{"抒情":["伤感","悼亡"],"生活":["田野"]},"theme_conf":0.99},{"uid":"a5d27c21-7045-4e33-8a1e-f50862de0e25","title":"寄天台叶尊师","author":"王贞白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["师住天台久，长闻过石桥。","晴峰见沧海，深洞彻丹霄。","采药霞衣湿，煎芝古鼎焦。","念予无俗骨，频与鹤书招。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"生活":["写桥"],"植物":["叶子"]},"theme_conf":0.88},{"uid":"8a9d9842-af13-4e4a-9973-63799a2ff132","title":"晚岁登武陵城顾望水陆怅然有作","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["星象承乌翼，蛮陬想犬牙。","俚人祠竹节，仙洞闭桃花。","城基历汉魏，江源自賨巴。","华表廖王墓，菜地黄琼家。","霜轻菊秀晚，石浅水纹斜。","樵音绕故垒，汲路明寒沙。","清风稍改叶，卢橘始含葩。","野桥过驿骑，丛祠发逈笳。","跳鳞避举网，倦鸟寄行楂。","路尘高出树，山火远连霞。","夕曛转赤岸，浮霭起苍葭。","轧轧渡水桨，连连赴林鸦。","呌阍道非远，赐环期自赊。","孤臣本危涕，乔木在天涯。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独","怀古"],"生活":["写桥"],"植物":["桃花"]},"theme_conf":0.385},{"uid":"565d931a-ff49-4f37-b633-524b48c2f4f0","title":"寻陆鸿渐不遇","author":"皎然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["移家虽带郭，野径入桑麻。","近种篱边菊，秋来未著花。","扣门无犬吠，欲去问西家。","报道山中去，归时每日斜。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","山"],"cats":{"四季":["秋天"],"生活":["乡村","田野"],"动物":["写鸟"]},"theme_conf":0.439},{"uid":"0c8565cc-bd2e-4b5a-87e3-00119062da17","title":"农父","author":"张碧","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["运锄耕𣃁侵星起，陇亩丰盈满家喜。","到头禾黍属他人，不知何处抛妻子。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人物":["父亲"],"生活":["田野"]},"theme_conf":0.713},{"uid":"3e4849dc-c411-49fa-8664-20a58b0493fd","title":"题郎士元半日吴村别业兼呈李长官","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["半日吴村带晚霞，闲门高柳乱飞鵶。","横云岭外千重树，流水声中一两家。","愁人昨夜相思苦，闰月今年春意赊。","自叹梅生头似雪，却怜潘令县如花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["江南"],"cats":{"抒情":["离别","思念","伤感"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":0.373},{"uid":"35c4618c-3896-45f8-9b24-51764c90383f","title":"横吹曲辞 折杨柳","author":"刘宪","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沙塞三河道，金闺二月春。","碧烟杨柳色，红粉绮罗人。","露叶怜啼脸，风花思舞巾。","攀持君不见，为听曲中新。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["塞外","春","花","月"],"cats":{"抒情":["思念","闺怨"],"四季":["春天"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.5},{"uid":"cp64b47d95c7e13e","title":"青玉案","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["三年枕上吴中路。","遣黄耳、随君去。","若到松江呼小渡。","莫惊鸥鹭，四桥尽是，老子经行处。","辋川图上看春暮。","常记高人右丞句。","作个归期天已许。","春衫犹是，小蛮针线，曾湿西湖雨。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["江南","江","春"],"cats":{"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"6629f32a-e163-4400-8684-a459c3b6bb52","title":"送崔秀才赴上元兼省叔父","author":"韩翃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寒塘敛暮雪，腊鼓迎春早。","匹马五城人，重裘千里道。","淮山轻露湿，江树狂风扫。","楚县久酝𬪩，扬州百花好。","练湖东望接云阳，女市西游入建康。","行乐远夸红布旆，风流近赌紫香囊。","诗家行辈如君少，极目苦心怀谢朓。","烟开日上板桥南，吴岫青青出林表。"],"theme":"送别","theme2":["节令风俗"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["元宵","山"],"cats":{"天气":["写风"],"人物":["父亲"],"生活":["写桥"],"节日":["元宵节"]},"theme_conf":0.49},{"uid":"c4d9440e-b2d8-4c43-930b-ba0c5dd68548","title":"将晓二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["石城除击柝，铁锁欲开关。","鼓角悲荒塞，星河落曙山。","巴人常小梗，蜀使动无还。","垂老孤帆色，飘飘犯百蛮。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["沉郁","悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["塞外","舟","山"],"cats":{"抒情":["伤感","孤独"],"天气":["星星"],"生活":["边塞"]},"theme_conf":0.683},{"uid":"1c22b677-c55e-4870-ace3-3450f93b17c1","title":"横吹曲辞 出塞","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["十年通大漠，万里出长平。","寒日生戈劒，阴云摇斾旌。","饥乌啼旧垒，疲马恋空城。","辛苦[皋兰]北，胡霜损汉兵。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":0.804},{"uid":"53540760-0c98-4266-b4e2-e6e39b49ca0c","title":"赠郑山人","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白首沧洲客，陶然得此生。","庞公采药去，莱氏与妻行。","乍见还州里，全非隐姓名。","枉帆临海峤，贳酒秣陵城。","伐木吴山晓，持竿越水清。","家人恣贫贱，物外任衰荣。","忽尔辞林壑，高歌至上京。","避喧心已惯，念远梦频成。","石路寒花发，江田腊雪明。","玄𫄸倘有命，何以遂躬耕。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":["豪放","幽峭"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"生活":["田野"]},"theme_conf":0.84},{"uid":"1f4dfb15-6a50-428f-8ce8-121b853cce12","title":"送柳判官赴振武","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["边庭汉仪重，旌甲似云中。","虏地山川壮，单于鼓角雄。","关寒塞榆落，月白胡天风。","君逐嫖姚将，麒麟有战功。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["塞外","月","园林","山"],"cats":{"人生":["战争"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"80a539fd-75f1-4590-83b2-5c7bf5c0c34c","title":"使青夷军入居庸三首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古镇青山口，寒风落日时。","岩峦鸟不过，冰雪马堪迟。","出塞应无策，还家赖有期。","东山足松桂，归去结茅茨。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["山","冬","塞外","雪"],"cats":{"天气":["写雪"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"f35c4d3c-1141-4821-9c39-99a480960d98","title":"留别贾严二阁老两院补阙","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["田园须𫏐往，戎马惜离群。","去远留诗别，愁多任酒醺。","一秋常苦雨，今日始无云。","山路时吹角，那堪处处闻。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["园林","楼"],"cats":{"抒情":["离别","伤感"],"生活":["田野"]},"theme_conf":1.0},{"uid":"204e287b-8194-4c2d-808b-11cc260412ae","title":"渭川田家","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["斜阳照墟落，穷巷牛羊归。","野老念牧童，倚杖候荆扉。","雉雊麦苗秀，蚕眠桑叶稀。","田夫荷锄至，相见语依依。","即此羡闲逸，怅然吟式微。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"人物":["儿童"],"生活":["田野"]},"theme_conf":0.429},{"uid":"8e4f53da-0190-413d-9c18-f8043d90e2be","title":"送幽州陈参军赴任寄呈乡曲父老","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蓟北三千里，关西二十年。","冯唐犹在汉，乐毅不归燕。","人同黄鹤远，乡共白云连。","郭隗池台处，昭王尊酒前。","故人当已老，旧壑几成田。","红颜如昨日，衰鬓似秋天。","西蜀桥应毁，东周石尚全。","灞池水犹绿，榆关月早圆。","塞云初上雁，庭树欲销蝉。","送君之旧国，挥泪独澘然。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["鸟","园林","秋"],"cats":{"抒情":["友情","离别","伤感","孤独"],"四季":["秋天"],"人物":["父亲"],"生活":["写桥"]},"theme_conf":0.434},{"uid":"25651b06-a58e-405f-a539-a86385e96468","title":"横吹曲辞 陇头水","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["陇水何年陇头别，不在山中亦呜咽。","征人塞耳马不行，未到陇头闻水声。","谓是西流入蒲海，还闻北海绕龙城。","陇东陇西多屈曲，野麋饮水长簇簇。","胡兵夜回水傍住，忆著来时磨劒处。","向前无井复无泉，放马回看陇头树。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","夜"],"cats":{"生活":["边塞"]},"theme_conf":0.554},{"uid":"9309205e-1d08-4a7b-99ef-4a05a9ee4370","title":"过故人庄","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故人具鸡黍，邀我至田家。","绿树村边合，青山郭外斜。","开筵面场圃，把酒话桑麻。","待到重阳日，还来就菊花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳","山"],"cats":{"抒情":["友情"],"生活":["乡村","田野"],"节日":["重阳节"]},"theme_conf":0.402},{"uid":"c5b30b4f-a9d1-4c84-8cd9-fdf6a29b7e86","title":"雪谤后书事上皇甫大夫","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["盛德总群英，高标仰国桢。","独安巡狩日，曾掩赵张名。","业就难辞宠，朝回更授兵。","晓川分牧马，夜雪覆连营。","长策威殊俗，嘉谋翊圣明。","画图规阵势，梦笔纪山行。","绶拂池中影，珂摇竹外声。","赐欢征妓乐，陪醉问公卿。","却忆经前事，翻疑得此生。","分深存没感，恩在子孙荣。","览镜愁将老，扪心喜复惊。","岂言沈族重，但觉杀身轻。","有泪沾坟典，无家集弟兄。","东西遭世难，流浪识交情。","阅古宗文举，推才慕正平。","应怜守贫贱，又欲事躬耕。"],"theme":"讽喻刺世","theme2":["山水田园","悼亡挽歌"],"style":"沉郁","style2":["婉约","豪放"],"mood":"欢愉","mood2":["愁怨"],"scene":["雪"],"cats":{"抒情":["伤感","悼亡","感恩"],"天气":["写雪"],"生活":["田野"]},"theme_conf":0.436},{"uid":"cpdb72a46d948baf","title":"天门谣","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["牛渚天门险。","限南北、七雄豪占。","清雾敛。","与闲人登览。","待月上潮平波滟滟。","塞管轻吹新《阿滥》。","风满槛。","历历数、西州更点。"],"theme":"边塞征战","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["江","塞外","月"],"cats":{"山水":["泰山"],"生活":["边塞"]},"theme_conf":0.565},{"uid":"14e71d5c-ff47-4b86-b37f-f79cbfbc4796","title":"季秋江村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乔木村墟古，疎篱野蔓悬。","清琴将暇日，白首望霜天。","登俎黄甘重，支床锦石圆。","远游虽寂寞，难见此山川。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.75},{"uid":"99314a0f-cce0-4006-aaaf-1e0cb2569f89","title":"杂曲歌辞 长相思","author":"苏颋","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见天津桥下东流水，东望龙门北朝市。","杨柳青青宛地垂，桃红李白花参差。","花参差，柳堪结，此时忆君心断绝。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花"],"cats":{"抒情":["爱情","思念"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"4d6d713f-e241-4cc9-b332-733225339044","title":"平胡","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["杂虏忽猖狂，无何敢乱常。","羽书朝继入，烽火夜相望。","将出凶门勇，兵因死地强。","蒙轮皆突骑，按劒尽鹰扬。","鼓角雄山野，龙蛇入战场。","流膏润沙漠，溅血染锋铓。","雾扫清玄塞，云开静朔方。","武功今已立，文德愧前王。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":["恬淡"],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"16668b6e-7a0c-4421-b374-d62a8b9c81eb","title":"真定即事奉赠韦使君二十八韵","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["飘泊怀书客，迟回此路隅。","问津惊弃置，投刺忽踟蹰。","方伯恩弥重，苍生咏已苏。","郡称廉叔度，朝议管夷吾。","乃继三台侧，仍将四岳俱。","江山澄气象，崖谷倚冰壶。","诏宠金门策，官荣叶县凫。","擢才登粉署，飞步蹑云衢。","起草徵调墨，焚香即宴娱。","光华扬盛矣，霄汉在兹乎。","隐轸推公望，逶迤协帝俞。","轩车辞魏阙，旌节副幽都。","始佩仙郎印，俄兼太守符。","尤多蜀郡理，更得颍川谟。","城邑推雄镇，山川列简图。","旧燕当绝漠，全赵对平芜。","旷野何弥漫，长亭复郁纡。","始泉遗俗近，活水战场无。","月换思乡陌，星廻记斗枢。","岁容归万象，和气发鸿罏。","沦落而谁遇，栖遑有是夫。","不才羞拥肿，干禄谢侏儒。","契阔慙行迈，羁离忆友于。","田园同季子，储蓄异陶朱。","方欲呈高义，吹嘘揖大巫。","永怀吐肝胆，犹惮阻荣枯。","解榻情何限，忘言道未殊。","从来贵缝掖，应是念穷途。"],"theme":"应制干谒","theme2":["羁旅思乡"],"style":"雄浑","style2":["清新"],"mood":"相思","mood2":[],"scene":["楼","塞外"],"cats":{"抒情":["离别","思念","思乡"],"生活":["田野"]},"theme_conf":0.95},{"uid":"cp23f78a4e960805","title":"兰陵王","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳阴直。","烟里丝丝弄碧。","隋堤上、曾见几番，拂水飘绵送行色。","登临望故国。","谁识。","京华倦客。","长亭路，年去岁来，应折柔条过千尺。","闲寻旧踪迹。","又酒趁哀弦，灯照离席。","梨花榆火催寒食。","愁一箭风快，半篙波暖，回头迢递便数驿。","望人在天北。","凄恻。","恨堆积。","渐别浦萦回，津堠岑寂。","斜阳冉冉春无极。","念月榭携手，露桥闻笛。","沈思前事，似梦里，泪暗滴。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["清明","酒","春"],"cats":{"抒情":["离别","伤感","怀古"],"四季":["春天"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.427},{"uid":"1c0d2513-d896-4ce1-a06d-8810f696e545","title":"雨过山村","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["雨里鸡鸣一两家，竹溪村路板桥斜。","妇姑相唤浴蚕去，闲看中庭栀子花。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"生活":["乡村","写桥"]},"theme_conf":0.615},{"uid":"b19965c5-9574-43ff-9158-2f61b6a3fde7","title":"酬王季友题半日村别业兼呈李明府","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["村映寒原日已斜，烟生密竹早归鸦。","长溪南路当群岫，半景东隣照数家。","门通小径连芳草，马饮春泉踏浅沙。","欲待主人林上月，还思潘岳县中花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","花"],"cats":{"抒情":["友情","离别"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":0.49},{"uid":"1b0eb975-d6fd-4b70-b6e6-a8ee5bbd6563","title":"同群公题郑少府田家","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑侯应凄惶，五十头尽白。","昔为南昌尉，今作东郡客。","与语多远情，论心知所益。","秋林既清旷，穷巷空淅沥。","蝶舞园更闲，鸡鸣日云夕。","男儿未称意，其道固无适。","劝君且杜门，勿叹人事隔。"],"theme":"寄赠酬答","theme2":["民生疾苦","羁旅思乡","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"生活":["田野"]},"theme_conf":0.85},{"uid":"065c182e-76f5-4777-b84e-e80651f509df","title":"女耕田行","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["乳燕入巢笋成竹，谁家二女种新谷。","无人无牛不及犁，持刀斫地翻作泥。","自言家贫母年老，长兄从军未娶嫂。","去年灾疫牛囤空，截绢买刀都市中。","头巾掩面畏人识，以刀代牛谁与同。","姊妹相携心正苦，不见路人唯见土。","疏通畦陇防乱苗，整顿沟塍待时雨。","日正南冈下饷归，可怜朝雉扰惊飞。","东邻西舍花发尽，共惜余芳泪满衣。"],"theme":"山水田园","theme2":["边塞征战"],"style":"沉郁","style2":["冲淡","清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["花"],"cats":{"抒情":["伤感","孤独"],"生活":["田野"]},"theme_conf":0.418},{"uid":"3bb3897a-7460-40d1-9ec3-b4738e3f20b4","title":"忆春日太液池亭候对","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["宫莺报晓瑞烟开，三岛灵禽拂水回。","桥转彩虹当绮殿，舰浮花鹢近蓬莱。","草承香辇王孙长，桃艳仙颜阿母栽。","簪笔此时方侍从，却思金马笑邹枚。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["彩虹"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"cpbeb305cfba39a6","title":"贺新郎","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["凤尾龙香拨。","自开元、霓裳曲罢，几番风月。","最苦浔阳江头客，画舸亭亭待发。","记出塞、黄云堆雪。","马上离愁三万里，望昭阳、宫殿孤鸿没。","弦解语，恨难说。","辽阳驿使音尘绝。","琐窗寒、轻拢慢拈，泪珠盈睫。","推手含情还却手，一抹梁州哀彻。","千古事、云飞烟灭。","贺老定场无消息，想沈香亭北繁华歇。","弹到此，为呜咽。"],"theme":"羁旅思乡","theme2":["边塞征战","闺情宫怨"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["塞外","雪"],"cats":{"抒情":["思乡","伤感","闺怨"],"生活":["边塞"]},"theme_conf":0.392},{"uid":"f3a62c39-2698-4d68-842f-a9ff595faa85","title":"题缑山王子晋庙","author":"郑畋","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有昔灵王子，吹笙溯泬㵳。","六宫攀不住，三岛去相招。","亡国原陵古，宾天岁月遥。","无蹊窥海曲，有庙访山椒。","石帐龙蛇拱，云栊彩翠销。","露坛装琬琰，真像写松乔。","珠馆青童宴，琳宫阿母朝。","气舆仙女侍，天马吏兵调。","湘妓红丝瑟，秦郎白管箫。","西城要绰约，南岳命娇娆。","句曲觞金洞，天台啸石桥。","晚花珠弄蘂，春茹玉生苗。","二景神光秘，三元宝箓饶。","雾垂鸦翅发，冰束虎章腰。","鹤驭争衔箭，龙妃合献绡。","衣从星渚浣，丹就日宫烧。","物外花尝满，人间叶自凋。","望台悲汉戾，阅水笑梁昭。","古殿香残炧，荒堦柳长条。","几曾期七日，无复降重霄。","嵩岭连天汉，伊澜入海潮。","何由得真诀，使我珮环飘。"],"theme":"山水田园","theme2":["咏物","游仙梦幻"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["山"],"cats":{"抒情":["伤感"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":0.418},{"uid":"c480c5e2-1052-4bdc-9fca-44d38c5a2fda","title":"相和歌辞 从军行二首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["百战沙场碎铁衣，城南已合数重围。","突营射杀呼延将，独领残兵千骑归。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.909},{"uid":"a3ed689f-6083-4041-b4d2-8f294506ee0c","title":"送冷朝阳还上元","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青丝䋏引木兰船，名遂身归拜庆年。","落日澄江乌榜外，秋风疎柳白门前。","桥通小市家林近，山带平湖野寺连。","别后依依寒食里，共君携手在东田。"],"theme":"送别","theme2":["节令风俗"],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵"],"cats":{"天气":["太阳"],"生活":["写桥"],"节日":["元宵节","寒食节"]},"theme_conf":0.524},{"uid":"f1496cf4-4f85-4f9e-9e0e-dd05370641d3","title":"古意","author":"李颀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["男儿事长征，少小幽燕客。","赌胜马蹄下，由来轻七尺。","杀人莫敢前，须如猬毛磔。","黄云陇底白雪飞，未得报恩不能归。","辽东小妇年十五，惯弹琵琶解歌舞。","今为羗笛出塞声，使我三军泪如雨。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["塞外","雪","雨"],"cats":{"抒情":["伤感"],"生活":["边塞"]},"theme_conf":0.632},{"uid":"f646a1ae-7a3e-4cdb-96d4-8c2ab4fb899a","title":"露青竹杖歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["鲜于仲通正当年，章仇兼琼在蜀川。","约束蜀儿采马鞭，蜀儿采鞭不敢眠。","横截斜飞飞鸟边，绳桥夜上层崖颠。","头插白云跨飞泉，采得马鞭长且坚。","浮沤丁子珠联联，灰煮蜡楷光烂然。","章仇兼琼持上天，上天雨露何其偏。","飞龙闲厩马数千，朝饮吴江夕秣燕。","红尘扑辔汗湿鞯，师子麒麟聊比肩。","江面昆明洗刷牵，四蹄踏浪头枿天。","蛟龙稽颡河伯虔，拓羯胡雏脚手鲜。","陈闳韩干丹青妍，欲貌未貌眼欲穿。","金鞍玉勒锦连干，骑入桃花杨柳烟。","十二楼中奏管弦，楼中美人夺神仙。","争爱大家把此鞭，禄山入关关破年。","忽见扬州北邙前，秪有人还千一钱。","亭亭笔直无皴节，磨捋形相一条铁。","市头格是无人别，江海贱臣不拘絏。","垂窗挂影西窗缺，稚子觅衣挑仰穴。","家童拾薪几拗折，玉润犹沾玉垒雪。","碧鲜似染苌弘血，蜀帝城边子规咽。","相如桥上文君绝，往年策马降至尊。","七盘九折横剑门，穆王八骏超昆仑。","安用冉冉孤生根，圣人不贵难得货，金玉珊珊谁买恩。"],"theme":"讽喻刺世","theme2":["山水田园","游仙梦幻","送别"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["雪","楼","鸟"],"cats":{"抒情":["孤独"],"人物":["女子","儿童"],"生活":["写桥"],"植物":["竹子"]},"theme_conf":0.75},{"uid":"b423f06b-4c05-4892-a409-7933ccf2edf8","title":"横吹曲辞 陇头吟","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["陇水潺湲陇树黄，征人陇上尽思乡。","马嘶斜日朔风急，雁过寒云边思长。","残月出林明劒戟，平沙隔水见牛羊。","横行俱足封侯者，谁斩楼兰献未央。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","楼","冬","鸟"],"cats":{"抒情":["思乡"],"四季":["冬天"],"天气":["写风"],"生活":["边塞"]},"theme_conf":0.645},{"uid":"2b9b6071-6dc8-4b04-949c-5350f23e4f9d","title":"和微之春日投简阳明洞天五十韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["青阳行已半，白日坐将徂。","越国强仍大，稽城高且孤。","利饶盐煮海，名胜水澄湖。","牛斗天垂象，台明地展图。","瓌奇填市井，佳丽溢𬮱阇。","句践遗风霸，西施旧俗姝。","船头龙夭矫，桥脚兽睢盱。","乡味珍蟛蚏，时鲜贵鹧鸪。","语言诸夏异，衣服一方殊。","捣练蛾眉婢，鸣榔蛙角奴。","江清敌伊洛，山翠胜荆巫。","华表双栖鹤，联樯几点乌。","烟波分渡口，云树接城隅。","涧远松如画，洲平水似铺。","绿科秧早稻，紫笋折新芦。","暖蹋泥中藕，香寻石上蒲。","雨来萌尽达，雷后蛰全苏。","柳眼黄丝颣，花房绛蜡珠。","林风新竹折，野烧老桑枯。","带亸长枝蕙，钱穿短贯榆。","暄和生野菜，卑湿长街芜。","女浣纱相伴，儿烹鲤一呼。","山魈啼稚子，林狖挂山都。","产业论蚕蚁，孳生计鸭雏。","泉岩雪飘洒，苔壁锦漫糊。","堰限舟航路，堤通车马途。","耶溪岸回合，禹庙径盘纡。","洞穴何因凿，星槎谁与刳。","石凹仙药臼，峰峭佛香炉。","去为投金简，来因挈玉壶。","贵仍招客宿，健未要人扶。","闻望贤丞相，仪形美丈夫。","前驱驻旌斾，偏坐列笙竽。","刺史旟翻隼，尚书履曳凫。","学禅超后有，观妙造虚无。","髻里传僧宝，环中得道枢。","登楼诗八咏，置砚赋三都。","捧拥罗将绮，趋跄紫与朱。","庙谟藏稷卨，兵略贮孙吴。","令下三军整，风高四海趋。","千家得慈母，六郡事严姑。","重士过三哺，轻财抵一铢。","送觥歌宛转，嘲妓笑卢胡。","佐饮时炮鼈，蠲酲数鲙鲈。","醉乡虽咫尺，乐事亦须臾。","若不中贤圣，何由外智愚。","伊予一生志，我尔百年躯。","江上三千里，城中十二衢。","出多无伴侣，归只对妻孥。","白首青山约，抽身去得无。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"欢愉","mood2":["孤寂"],"scene":["江","山","江南","舟","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"天气":["太阳"],"人物":["母亲","儿童"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"0167687e-8325-48bf-8da4-3749c9ce0a74","title":"横吹曲辞 关山月","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","戍客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山","月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.512},{"uid":"8d58a158-1a9b-4085-8ef7-b7b4e6adb66d","title":"塞下曲四首 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蝉鸣空桑林，八月萧关道。","出塞入塞寒，处处黄芦草。","从来幽幷客，皆共尘沙老。","莫学游侠儿，矜夸紫骝好。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":0.649},{"uid":"cp60a401fbbbc431","title":"莺啼序","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒正欺病酒，掩沈香绣户。","燕来晚、飞入西城，似说春事迟暮。","画船载、清明过却，晴烟冉冉吴宫树。","念羁情游荡，随风化为轻絮。","十载西湖，傍柳系马，趁娇尘软雾。","溯红渐、招入仙溪，锦儿偷寄幽素。","倚银屏、春宽梦窄，断红湿、歌纨金缕。","暝堤空，轻把斜阳，总还鸥鹭。","幽兰旋老，杜若还生，水乡尚寄旅。","别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。","长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。","青楼彷佛，临分败壁题诗，泪墨惨澹尘土。","危亭望极，草色天涯，吹鬓侵半苎。","暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。","殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。","伤心千里江南，怨曲重招，断魂在否。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"相思","mood2":["愁怨"],"scene":["江南","鸟","春"],"cats":{"抒情":["离别","思念","伤感","悼亡"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"],"节日":["清明节"],"动物":["写鸟"]},"theme_conf":0.93},{"uid":"7788b533-8d77-41b7-a401-9e1f4cb66182","title":"相和歌辞 常林欢","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["宜城酒熟花覆桥，沙晴绿鸭鸣咬咬。","秾桑绕舍麦如尾，幽轧鸣机双燕巢。","马声特特荆门道，蛮水扬光色如草。","锦荐金炉梦正长，东家呃喔鸡鸣早。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"生活":["写桥"]},"theme_conf":0.695},{"uid":"b3146349-87b7-463f-994b-ab5fea5ca2f3","title":"戍客南归","author":"于𣸣","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北别黄榆塞，南归白云乡。","孤舟下彭蠡，楚月沈沧浪。","为子惜功业，满身刀箭疮。","莫渡汨罗水，回君忠孝肠。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["端午","塞外","舟","月"],"cats":{"抒情":["思乡","孤独"],"生活":["边塞"],"节日":["端午节"]},"theme_conf":0.444},{"uid":"154bc6b6-be47-4e42-a039-e6f6d22fd447","title":"鼓吹曲辞 战城南","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["将军出紫塞，冒顿在乌贪。","笳喧雁门北，阵翼龙城南。","雕弓夜宛转，铁骑晓参潭。","应须驻白日，为待战方酣。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["塞外","夜","鸟"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"d4e3c78d-a404-4910-8e0d-aca1f0a29f2b","title":"相和歌辞 采桑","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["杨柳送行人，青青西入秦。","秦家采桑女，楼上不胜春。","盈盈灞水曲，步步春芳绿。","红脸耀明珠，绛唇含白玉。","回首渭桥东，遥怜树色同。","青丝娇落日，缃绮弄春风。","携笼长叹息，逶迤恋春色。","看花若有情，倚树疑无力。","薄暮思悠悠，使君南陌头。","相逢不相识，归去梦青楼。"],"theme":"山水田园","theme2":["送别"],"style":"绮丽","style2":["婉约"],"mood":"相思","mood2":[],"scene":["花","春","楼"],"cats":{"四季":["春天"],"生活":["写桥"]},"theme_conf":0.488},{"uid":"ea4f954e-f947-4ea6-a7ce-24425dcf7fea","title":"相和歌辞  相逢行","author":"崔颢","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾年初二八，家住洛桥头。","玉户临驰道，朱门近御沟。","使君何假问，夫壻大长秋。","女弟新承宠，诸兄近拜侯。","春生百子殿，花发五城楼。","出入千门里，年年乐未休。"],"theme":"讽喻刺世","theme2":["羁旅思乡","闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","春","楼"],"cats":{"抒情":["思乡","闺怨"],"四季":["春天","秋天"],"生活":["写桥"]},"theme_conf":0.372},{"uid":"9d974ae6-2223-4fa3-bb66-15a079adec68","title":"送孔巢父赴河南军","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江城相送阻烟波，况复新秋一雁过。","闻道全师征北虏，更言诸将会南河。","边心杳杳乡人绝，塞草青青战马多。","共许陈琳工奏记，知君名宦未蹉跎。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","塞外","秋"],"cats":{"四季":["秋天"],"山水":["江河"],"人物":["父亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.403},{"uid":"81144889-f17a-4590-bbeb-5a9fdb7fcf4d","title":"春日江村五首 五","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["群盗哀王粲，中年召贾生。","登楼初有作，前席竟为荣。","宅入先贤传，才高处士名。","异时怀二子，春日复含情。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"06bd32a2-f9f5-4bfe-a55e-fadd67afc789","title":"相和歌辞 饮马长城窟行","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长城窟，长城窟边多马骨。","古来此地无井泉，赖得秦家筑城卒。","征人饮马愁不回，长城变作望乡堆。","蹄迹未干人去近，续后马来泥污尽。","枕弓睡著待水生，不见阴山在前阵。","马蹄足脱装马头，健儿战死谁封侯。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["相思","悲怆"],"scene":[],"cats":{"抒情":["思念","思乡","伤感"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.631},{"uid":"80beb8cc-8338-44d4-8b96-7f9d32133c97","title":"西塞山怀古","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西晋楼船下益州，金陵王气黯然收。","千寻铁锁沈江底，一片降旛出石头。","人世几回伤往事，山形依旧枕江流。","今逢四海为家日，故垒萧萧芦荻秋。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["山","塞外"],"cats":{"抒情":["怀古"],"山水":["江河"],"生活":["边塞"]},"theme_conf":0.672},{"uid":"6393b72d-7d61-4201-9072-e5589b1637ab","title":"杂曲歌辞 行路难","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见长安城北渭桥边，枯木横槎卧古田。","昔日含红复含紫，常时留雾亦留烟。","春景春风花似雪，香车玉轝恒阗咽。","若个游人不竞攀，若个倡家不来折。","倡家宝袜蛟龙帔，公子银鞍千万骑。","黄莺一向花娇春，两两三三将子戏。","千尺长条百尺枝，丹桂青榆相蔽亏。","珊瑚叶上鸳鸯鸟，凤凰巢里雏鹓儿。","巢倾枝折凤归去，条枯叶落狂风吹。","一朝零落无人问，万古摧残君讵知。","人生贵贱无终始，倏忽须臾难久恃。","谁家能驻西山日，谁家能堰东流水。","汉家陵树满秦川，行来行去尽哀怜。","自昔公卿二千石，咸拟荣华一万年。","不见朱唇将白貌，惟闻素棘与黄泉。","金貂有时须换酒，玉麈但摇莫计钱。","寄言坐客神仙署，一生一死交情处。","苍龙阙下君不来，白鹤山前我应去。","云间海上邈难期，赤心会合在何时？","但愿尧年一百万，长作巢由也不辞。"],"theme":"羁旅思乡","theme2":["哲理悟道","送别","山水田园"],"style":"绮丽","style2":["豪放","雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","春","花","雪"],"cats":{"抒情":["友情","思乡","孤独"],"四季":["春天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":0.35},{"uid":"7ee919e0-cdff-4594-bc72-3d5d88503cee","title":"杂曲歌辞 行路难三首 二","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见担雪塞井徒用力，炊砂作饭岂堪吃。","一生肝胆向人尽，相识不如不相识。","冬青树上挂凌宵，岁[晏]花凋树不凋。","凡物各自有根本，种禾终不生豆苗。","行路难，行路难，何处是平道？","中心无事当富贵，今日觉君颜色好。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["冬","塞外","雪"],"cats":{"四季":["冬天"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"d129dc0f-cec9-4073-bb89-cb9312564d9d","title":"轮台歌奉送封大夫出师西征","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["轮台城头夜吹角，轮台城北旄头落。","羽书昨夜过渠黎，单于已在金山西。","戍楼西望烟尘黑，汉兵屯在轮台北。","上将拥旄西出征，平明吹笛大军行。","四边伐鼓雪海涌，三军大呼阴山动。","虏塞兵气连云屯，战场白骨缠草根。","劒河风急雪片阔，沙口石冻马蹄脱。","亚相勤王甘苦辛，誓将报主静边尘。","古来青史谁不见，今见功名胜古人。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["悲慨"],"mood":"慷慨","mood2":["恬淡"],"scene":["楼"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.762},{"uid":"0c1d43ec-220c-4983-a6f9-e4e55631ad44","title":"赋得浮桥","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岸曲非千里，桥斜异七星。","暂低逢辇度，还高值浪惊。","水摇文鹢动，缆转锦花萦。","远近随轮影，轻重应人行。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"生活":["写桥"]},"theme_conf":1.0},{"uid":"e4fdb460-0944-4976-85a9-527bc87f7d7a","title":"横吹曲辞 出塞","author":"王维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["居延城外猎天骄，白草连天野火烧。","暮云空碛时驱马，秋日平原好射雕。","护羌校尉朝乘障，破虏将军夜渡辽。","玉靶角弓珠勒马，汉家将赐霍嫖姚。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":1.0},{"uid":"da3a0129-eb3f-4e72-acf6-7c0d6ca402a9","title":"田家","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["带水摘禾穗，夜捣具晨炊。","县帖取社长，嗔怪见官迟。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["夜"],"cats":{"生活":["田野"]},"theme_conf":0.668},{"uid":"f4ebe616-20f4-4b12-964a-8b1f41f7dbab","title":"佐还山后寄三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["山晚浮云合，归时恐路迷。","涧寒人欲到，村黑鸟应栖。","野客茅茨小，田家树木低。","旧谙疎嬾叔，须汝故相携。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"生活":["田野"]},"theme_conf":0.435},{"uid":"3ec9cb88-517c-4922-a82e-e6cc561ace29","title":"往在","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["往在西京日，胡来满彤宫。","中宵焚九庙，云汉为之红。","解瓦飞十里，𰬸帷纷曾空。","疚心惜木主，一一灰悲风。","合昏排铁骑，清旭散锦𩦺贼臣表逆节，相贺以成功。","是时妃嫔戮，连为粪土丛。","当宁陷玉座，白间剥画虫。","不知二圣处，私泣百岁翁。","车驾既云还，楹桷歘穹崇。","故老复涕泗，祠官树椅桐。","宏壮不如初，已见帝力雄。","前春礼郊庙，祀事亲圣躬。","微躯忝近臣，景从陪群公。","登阶捧玉册，峨冕耿金钟。","侍祠恧先露，掖垣迩濯龙。","天子惟孝孙，五云起九重。","镜匳换粉黛，翠羽犹葱胧。","前者厌羯胡，后来遭犬戎。","俎豆腐膻肉，罘罳行角弓。","安得自西极，申命空山东。","尽躯诣阙下，士庶塞关中。","主将晓逆顺，元元归始终。","一朝自罪己，万里车书通。","锋镝供锄犂，征戍听所从。","冗官各复业，土著还力农。","君臣节俭足，朝野欢呼同。","中兴似国初，继体如太宗。","端拱纳谏诤，和风日冲融。","赤墀樱桃枝，隐映银丝笼。","千春荐陵寝，永永垂无穷。","京都不再火，泾渭开愁容。","归号故松柏，老去苦飘蓬。"],"theme":"边塞征战","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":["春","塞外"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["田野","边塞"]},"theme_conf":0.516},{"uid":"16dea403-c108-4546-89a5-18e8f1d3373c","title":"相和歌辞 短歌行六首 二","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["我欲升天天隔霄，我思渡水水无桥。","我欲上山山路险，我欲汲井井泉遥。","越人翠被今何夕，独立沙边江草碧。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山","江南","江"],"cats":{"抒情":["孤独"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"4b28f85a-4497-40f0-b1c5-ed939c384dc2","title":"酬谢侍御喜王宇及第见贺不遇之作","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寂寞柴门掩，经过柱史荣。","老夫宁有力，半子自成名。","柳映三桥发，花连上道明。","缄书到别墅，郢曲果先成。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":[],"cats":{"抒情":["孤独","感恩"],"生活":["写桥"]},"theme_conf":0.96},{"uid":"8399a509-3f09-4027-a389-f5c4ba9e5dfe","title":"送李翺习之","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["习之势翩翩，东南去遥遥。","赠君双履足，一为上臯桥。","臯桥路逶迤，碧水清风飘。","新秋折藕花，应对吴语娇。","千巷分渌波，四门生早潮。","湖榜轻褭褭，酒旗高寥寥。","小时屐齿痕，有处应未销。","旧忆如雾星，怳见于梦消。","言之烧人心，事去不可招。","独孤宅前曲，箜篌醉中谣。","壮年俱悠悠，逮兹各焦焦。","执手复执手，唯道无枯凋。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["酒","江","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人物":["老师"],"生活":["写桥"]},"theme_conf":0.8},{"uid":"61275a5a-1dce-4a0b-9491-a43c915c06d3","title":"寒食","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒食江村路，风花高下飞。","汀烟轻冉冉，竹日静晖晖。","田父要皆去，邻家闹不违。","地偏相识尽，鸡犬亦忘归。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["清明"],"cats":{"生活":["乡村"],"节日":["寒食节","清明节"]},"theme_conf":0.88},{"uid":"cpfeda664cad7f2d","title":"贺新郎","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绿树听鹈。","更那堪、鹧鸪声住，杜鹃声切。","啼到春归无寻处，苦恨芳菲都歇。","算未抵、人间离别。","马上琵琶关塞黑，更长门、翠辇辞金阙。","看燕燕，送归妾。","将军百战身名裂。","向河梁、回头万里，故人长绝。","易水萧萧西风冷，满座衣冠似雪。","正壮士、悲歌未彻。","啼鸟还知如许恨，料不啼清泪长啼血。","谁共我，醉明月。"],"theme":"送别","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["悲慨","沉郁"],"mood":"愁怨","mood2":[],"scene":["鸟","春","月"],"cats":{"抒情":["友情","离别","伤感","闺怨"],"四季":["春天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.357},{"uid":"195ac36f-552e-4cc2-9e99-6d8c0cc93b72","title":"杂曲歌辞 少年行二首 一","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["官为骏马监，职帅羽林儿。","两绶藏不见，落花何处期？","猎敲白玉镫，怒袖紫金锤。","田窦长留醉，苏辛曲护岐。","豪持出塞节，笑别远山眉。","捷报云台贺，公卿拜寿巵。"],"theme":"边塞征战","theme2":["送别","羁旅思乡"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","酒","山"],"cats":{"抒情":["思乡"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.409},{"uid":"cp969dea94a53490","title":"谢金莲诗酒红梨花・天下乐","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["你岂知他那有志题桥汉司马，怎不教人嗔怒发，是和非你心中自临察。","端的个无礼法，只管里抵触咱，梅香你记着我这一顿打。"],"theme":"闲适隐逸","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["花","酒"],"cats":{"抒情":["感恩"],"生活":["写桥"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.65},{"uid":"6d090832-2f35-4f44-a68a-cc5b67e1798d","title":"村夜","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧萧风色暮，江头人不行。","村舂雨外急，邻火夜深明。","胡羯何多难，渔樵寄此生。","中原有兄弟，万里正含情。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["夜"],"cats":{"生活":["乡村"]},"theme_conf":0.579},{"uid":"26cbab92-a321-44e6-842b-13acc9749fc0","title":"羌村 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["群鸡正乱叫，客至鸡鬬争。","驱鸡上树木，始闻叩柴荆。","父老四五人，问我久远行。","手中各有携，倾榼浊复清。","苦辞酒味薄，黍地无人耕。","兵革既未息，儿童尽东征。","请为父老歌，艰难块深情。","歌罢仰天叹，四座泪纵横。"],"theme":"山水田园","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":["孤寂"],"scene":["酒"],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.379},{"uid":"2d6eff0e-d937-4d1f-9e3b-91241dd3db27","title":"冬夜赠别友人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["愁听千家流水声，相思独向月中行。","侵堦暗草秋霜重，遍郭寒山夜月明。","连年客舍唯多病，数亩田园又废耕。","更送乘轺归上国，应怜贡禹未成名。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["夜","冬"],"cats":{"抒情":["友情","离别","思念","伤感","孤独"],"四季":["秋天","冬天"],"生活":["田野"]},"theme_conf":0.601},{"uid":"34d3b009-d2b6-456e-969f-8b4a0283356b","title":"东南行一百韵寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韦大员外庾三十二补阙杜十四拾遗李二十助教员外窦七校书","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["南去经三楚，东来过五湖。","山头看候馆，水面问征途。","地远穷江界，天低极海隅。","飘零同落叶，浩荡似乘桴。","渐觉乡原异，深知土产殊。","夷音语嘲异常，蛮态笑睢盱。","水市通阛阓，烟村混舳舻。","吏征渔户税，人纳火田租。","亥日饶𫚥蟹，寅年足虎䝙。","成人男作丱，事鬼女为巫。","楼暗攒倡妇，隄长簇贩夫。","夜船论铺赁，春酒断缾酤。","见果皆卢橘，闻禽悉鹧鸪。","山歌猨独叫，野哭鸟相呼。","岭徼云成栈，江郊水当郛。","月移翘柱鹤，风泛飐樯乌。","鼇碍潮无信，蛟惊浪不虞。","鼍鸣江擂鼓，蜃气海浮图。","树裂山魈穴，沙含水弩枢。","喘牛犂紫芋，羸马放青菰。","绣面谁家婢，鵶头几岁奴。","泥中采菱芡，烧后拾樵苏。","鼎腻愁烹鼈，盘腥厌脍鲈。","钟仪徒恋楚，张翰浪思吴。","气序凉还热，光阴旦复晡。","身方逐萍梗，年欲近桑榆。","渭北田园废，江西岁月徂。","忆归恒惨澹，怀旧忽踟蹰。","自念咸秦客，尝为邹鲁儒。","蕴藏经国术，轻弃度关𦈡。","赋力凌鹦鹉，词锋敌辘轳。","战文重掉鞅，射策一弯弧。","崔杜鞭齐下，元韦辔并驱。","名声逼扬马，交分过萧朱。","世务轻摩揣，周行窃觊觎。","风云皆会合，雨露各沾濡。","共遇升平代，偏慙固陋躯。","承明连夜直，建礼拂晨趋。","美服颁王府，珍羞降御厨。","议高通白虎，谏切伏青蒲。","柏殿行陪宴，花楼走看酺。","神旗张鸟兽，天籁动笙芋。","戈劒星芒耀，鱼龙电策驱。","定场排越伎，促坐进吴歈。","缥缈疑仙乐，婵娟胜画图。","歌鬟低翠羽，舞汗堕红珠。","别选闲游伴，潜招小饮徒。","一杯愁已破，三醆气弥麤。","輭美仇家酒，幽闲葛氏姝。","十千方得斗，二八正当垆。","论笑杓胡律，谈怜巩嗫嚅。","李酣犹短窦，庾醉更蔫迂。","鞍马呼教住，骰盘喝遣输。","长驱波卷白，连掷采成卢。","筹幷频逃席，觥严列置盂。","满巵那可灌，颓玉不胜扶。","入视中枢草，归乘内廐驹。","醉曾冲宰相，骄不揖金吾。","日近恩虽重，云高势却孤。","飜身落霄汉，失脚倒泥涂。","博望移门籍，浔阳佐郡符。","时情变寒暑，世利算锱铢。","即日辞双阙，明朝别九衢。","播迁分郡国，次第出京都。","秦岭驰三驿，商山上二邘。","岘阳亭寂莫，夏口路崎岖。","大道全生棘，中丁尽执殳。","江关未撤警，淮寇尚稽诛。","林对东西寺，山分大小姑。","庐峰莲刻削，湓浦带萦纡。","九派吞青草，孤城覆绿芜。","黄昏钟寂寂，清晓角呜呜。","春色辞门柳，秋声到井梧。","残芳悲𫛸鴂，暮节感茱萸。","蘂坼金英菊，花飘雪片芦。","波红日斜没，沙白月平铺。","几见林抽笋，频惊燕引雏。","岁华何倏忽，年少不须臾。","眇默思千古，苍茫想八区。","孔穷缘底事，颜夭有何辜。","龙智犹经醢，龟灵未免刳。","穷通应已定，圣哲不能逾。","况我身谋拙，逢他厄运拘。","漂流随大海，锤锻任洪𬬻。","险阻尝之矣，栖迟命也夫。","沈冥消意气，穷饿耗肌肤。","防瘴和残药，迎寒补旧襦。","书床鸣蟋蟀，琴匣网蜘蛛。","贫室如悬磐，端忧剧守株。","时遭人指点，数被鬼揶揄。","兀兀都疑梦，昏昏半是愚。","女惊朝不起，妻怪夜长吁。","万里抛朋侣，三年隔友于。","自然悲聚散，不是恨荣枯。","去夏微之疟，今春席八殂。","天涯书达否，泉下哭知无。","谩写诗盈卷，空盛酒满壶。","只添新怅望，岂复旧欢娱。","壮志因愁减，衰容与病俱。","相逢应不识，满颔白髭须。"],"theme":"寄赠酬答","theme2":["羁旅思乡","民生疾苦","送别"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["酒","山","江","夏","夜","鸟"],"cats":{"抒情":["思乡","伤感","孤独","悼亡"],"四季":["夏天"],"天气":["月亮"],"人生":["励志","时光","梦想"],"生活":["田野"],"节日":["中秋节","重阳节"]},"theme_conf":0.85},{"uid":"bd57a0b0-28a1-4d53-bc09-51899d2dac38","title":"兵车行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["车辚辚，马萧萧，行人弓箭各在腰。","耶娘妻子走相送，尘埃不见咸阳桥。","牵衣顿足阑道哭，哭声直上干云霄。","道傍过者问行人，行人但云点行频。","或从十五北防河，便至四十西营田。","去时里正与裹头，归来头白还戍边。","边亭流血成海水，武皇开边意未已。","君不闻汉家山东二百州，千村万落生荆杞。","纵有健妇把锄犂，禾生陇亩无东西。","况复秦兵耐苦战，被驱不异犬与鸡。","长者虽有问，役夫敢申恨。","且如今年冬，未休关西卒。","县官急索租，租税从何出？信知生男恶，反是生女好。","生女犹是嫁比邻，生男埋没随百草。","君不见青海头，古来白骨无人收。","新鬼烦冤旧鬼哭，天阴雨湿声啾啾。"],"theme":"边塞征战","theme2":["民生疾苦"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["冬"],"cats":{"四季":["冬天"],"人生":["战争"],"生活":["写桥"]},"theme_conf":0.434},{"uid":"7241e2c5-7d41-4cbd-86d7-9be3e63208f7","title":"送客之上谷","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北客悲秋色，田园忆去来。","披衣朝易水，匹马夕燕台。","风翦荷花碎，霜迎栗罅开。","赏心知不浅，累月故人杯。"],"theme":"送别","theme2":["羁旅思乡"],"style":"清新","style2":["悲慨"],"mood":"悲怆","mood2":["相思"],"scene":["秋"],"cats":{"抒情":["友情","思念","思乡","伤感"],"四季":["秋天"],"生活":["田野"]},"theme_conf":0.465},{"uid":"f28dfaa3-ff90-42e3-923d-63a5635afab8","title":"七夕二首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天衢启云帐，神驭上星桥。","初喜渡河汉，频惊转斗杓。","余霞张锦幛，轻电闪红绡。","非是人间世，还悲后会遥。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":["欢愉"],"scene":["七夕"],"cats":{"抒情":["伤感"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"0b6a4293-c89f-4e4b-9365-be01edb02ccd","title":"诸葛庙","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["久游巴子国，屡入武侯祠。","竹日斜虚寝，溪风满薄帷。","君臣当共济，贤圣亦同时。","翊戴归先主，幷吞更出师。","虫虵穿画壁，巫觋醉蛛丝。","歘忆吟梁父，躬耕也未迟。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"相思","mood2":[],"scene":["酒"],"cats":{"抒情":["思念","怀古"],"生活":["田野"]},"theme_conf":0.584},{"uid":"72fc17eb-8b81-4de1-b38e-eb035f412a2b","title":"横吹曲辞 后出塞五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["男儿生世间，及壮当封侯。","战伐有功业，焉能守旧丘。","召募赴蓟门，军动不可留。","千金买马鞭，百金装刀头。","闾里送我行，亲戚拥道周。","斑白居上列，酒酣进庶羞。","少年别有赠，含笑看吴钩。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.615},{"uid":"04fa7a4c-e624-4083-9668-b05394a5a61d","title":"九日登梓州城","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["伊昔黄花酒，如今白发翁。","追欢筋力异，望远岁时同。","弟妹悲歌里，朝廷醉眼中。","兵戈与关塞，此日意无穷。"],"theme":"边塞征战","theme2":["节令风俗"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":["欢愉"],"scene":["酒","重阳","塞外"],"cats":{"抒情":["伤感"],"天气":["太阳"],"生活":["边塞"],"节日":["重阳节"]},"theme_conf":0.374},{"uid":"cd8c3590-e097-4289-bcda-ad852ed095ab","title":"杂曲歌辞 悲哉行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["促促晨复昏，死生同一源。","贵年不惧老，贱老伤久存。","朗朗哭前歌，绛旌引幽魂。","来为千金子，去卧百草根。","黄土塞生路，悲风送回辕。","金鞍旧良马，四顾不出门。","生结千岁念，荣及百代孙。","黄金买性命，白刃讐一言。","宁知北山上，松柏侵田园。"],"theme":"边塞征战","theme2":["送别"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人物":["老师"],"生活":["田野","边塞"]},"theme_conf":0.516},{"uid":"246ff90e-bd5c-4e81-8637-f1605fa647d9","title":"园官送茶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["清晨蒙菜把，常荷地主恩。","守者愆实数，略有其名存。","苦苣刺如针，马齿叶亦繁。","青青嘉蔬色，埋没在中园。","园吏未足怪，世事固堪论。","呜呼战伐久，荆棘暗长原。","乃知苦苣辈，倾夺蕙草根。","小人塞道路，为态何喧喧。","又如马齿盛，气拥葵荏昏。","点染不易虞，丝麻杂罗纨。","一经器物内，永挂麤刺痕。","志士采紫芝，放歌避戎轩。","畦丁负笼至，感动百虑端。"],"theme":"送别","theme2":["边塞征战"],"style":"清新","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["园林"],"cats":{"人生":["战争"],"生活":["边塞"],"食物":["写茶"]},"theme_conf":0.401},{"uid":"a2aed629-465d-412c-a68d-780068488725","title":"自河南经乱关内阻饥兄弟离散各在一处因望月有感聊书所怀寄上浮梁大兄於潜七兄乌江十五兄兼示符离及下邽弟妹","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["时难年饥世业空，弟兄羇旅各西东。","田园寥落干戈后，骨肉流离道路中。","吊影分为千里鴈，辞根散作九秋蓬。","共看明月应垂泪，一夜乡心五处同。"],"theme":"亲情","theme2":["民生疾苦","亲情","羁旅思乡"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["离别","思乡","伤感"],"山水":["江河"],"天气":["月亮"],"生活":["田野"]},"theme_conf":0.87},{"uid":"651987af-2600-4410-a813-0d0f8ae28b66","title":"成都曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["锦江近西烟水绿，新雨山头荔枝熟。","万里桥边多酒家，游人爱向谁家宿。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":["清新","绮丽"],"mood":"恬淡","mood2":[],"scene":["酒","雨","江","山"],"cats":{"生活":["写桥"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"e3bf5676-319c-460e-b5b2-e53daad7f6d0","title":"秋行官张请督促东渚耗稻向毕清晨遣女奴阿稽竖子阿段往问","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东渚雨今足，伫闻稉稻香。","上天无偏颇，蒲稗各自长。","人情见非类，田家戒其荒。","功夫竞搰搰，除草置岸旁。","谷者命之本，客居安可忘。","青春具所务，勤垦免乱常。","吴牛力容易，竝驱动莫当。","丰苗亦已穊，云水照方塘。","有生固蔓延，静一资隄防。","督领不无人，提携颇在纲。","荆扬风土暖，肃肃候微霜。","尚恐主守疎，用心未甚臧。","清朝遣婢仆，寄语逾崇冈。","西成聚必散，不独陵我仓。","岂要仁里誉，感此乱世忙。","北风吹蒹葭，蟋蟀近中堂。","荏苒百工休，郁纡迟暮伤。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["恬淡"],"scene":["秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["青春"],"生活":["田野"]},"theme_conf":0.688},{"uid":"202bd0c0-4003-4749-a804-f28a5995b752","title":"玩月诗 三","author":"曲龙山仙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["造化天桥碧海东，玉轮还过辗晴虹。","霓襟似拂瀛洲顶，颢气潜消橐籥中。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["月"],"cats":{"天气":["彩虹","月亮"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"e4d4c69a-9803-4863-bb93-8b0be8420bbd","title":"郊居对雨寄赵涓给事包佶郎中","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暑雨青山里，随风到野居。","乱沤浮曲砌，悬溜响前除。","尘镜愁多掩，蓬头嬾更梳。","夜窗凄枕席，阴壁润图书。","萧飒宜新竹，龙钟拾野蔬。","石泉空自咽，药圃不堪锄。","浊水淙深辙，荒兰拥败渠。","繁枝留宿鸟，碎浪出寒鱼。","桑屐时登望，荷衣自卷舒。","应怜在泥滓，无路托高车。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["雨","夏"],"cats":{"抒情":["伤感"],"四季":["夏天"],"天气":["写雨"],"生活":["田野"]},"theme_conf":0.577},{"uid":"55b05ee5-c0de-46ce-8265-ec644b42ec4c","title":"清明日自西午桥至瓜岩村有怀","author":"张继","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["晚霁龙门雨，春生汝穴风。","鸟啼官路静，花发毁垣空。","鸣玉慙时辈，垂丝学老翁。","旧游人不见，惆怅洛城东。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":["清新"],"mood":"愁怨","mood2":["惆怅","恬淡"],"scene":["清明","春"],"cats":{"四季":["春天"],"生活":["乡村","写桥"],"节日":["清明节"]},"theme_conf":0.76},{"uid":"59f7c852-316a-4a45-838a-923df108a993","title":"赠王二十四侍御契四十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["往往虽相见，飘飘媿此身。","不关轻绂冕，俱是避风尘。","一别星桥夜，三移斗柄春。","败亡非赤壁，奔走为黄巾。","子去何潇洒，余藏异隐沦。","书成无过雁，衣故有县鹑。","恐惧行装数，伶俜卧疾频。","晓鸎工迸泪，秋月解伤神。","会面嗟黧黑，含凄话苦辛。","接舆还入楚，王粲不归秦。","锦里残丹灶，花溪得钓纶。","消中祗自惜，晚起索谁亲。","伏柱闻周史，乘槎有汉臣。","鸳鸿不易狎，龙虎未宜驯。","客则挂冠至，交非倾盖新。","由来意气合，直取性情真。","浪迹同生死，无心耻贱贫。","偶然存蔗芋，幸各对松筠。","麤饭依他日，穷愁怪此辰。","女长裁褐稳，男大卷书匀。","漰口江如练，蚕崖雪似银。","名园当翠𪩘，野棹没青苹。","屡喜王侯宅，时邀江海人。","追随不觉晚，欵曲动弥旬。","但使芝兰秀，何烦栋宇邻。","山阳无俗物，郑驿正留宾。","出入并鞍马，光辉参席珍。","重游先主庙，更历少城𬮱。","石镜通幽魄，琴台隐绛唇。","送终惟粪土，结爱独荆榛。","置酒高林下，观碁积水滨。","区区甘累趼，稍稍息劳筋。","网聚粘圆鲫，丝繁煮细莼。","长歌敲柳瘿，小睡凭藤轮。","农月须知课，田家敢忘勤。","浮生难去食，良会惜清晨。","列国兵戈暗，今王德教淳。","要闻除䝟貐，休作画麒麟。","洗眼看轻薄，虚怀任屈伸。","莫令胶漆地，万古重雷陈。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":["沉郁","旷达"],"mood":"愁怨","mood2":[],"scene":["夜","雪"],"cats":{"抒情":["伤感"],"生活":["田野","写桥"]},"theme_conf":0.96},{"uid":"8b6db087-2999-4f42-9877-67c2a4cfde45","title":"喜雨","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["闲居倦时燠，开轩俯平林。","雷声殷遥空，云气布层阴。","川上风雨来，洒然涤烦襟。","田家共欢笑，沟浍亦已深。","团团聚邻曲，斗酒相与斟。","樵歌野田中，渔钓沧江浔。","苍天暨有念，悠悠终我心。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"生活":["田野"]},"theme_conf":0.578},{"uid":"9c08d89e-9c4a-4cb2-a7f7-8affe0e8fe70","title":"送夏侯校书归华阴别墅","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山前白鹤村，竹雪覆柴门。","候客定为黍，务农因燎原。","乳冰悬暗井，莲石照晴轩。","贳酒邻里睦，曝衣场圃喧。","依然望君去，余性亦何昏。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","冬"],"cats":{"抒情":["离别"],"四季":["夏天"],"生活":["乡村"]},"theme_conf":0.483},{"uid":"995153fc-153b-4165-8a84-3cbad12232ef","title":"南海使院对菊怀丁卯别墅","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何处曾移菊，溪桥鹤岭东。","篱疎还有艳，园小亦无丛。","日晚秋烟里，星繁晓露中。","影摇金涧水，香染玉潭风。","罢酒慙陶令，题诗答谢公。","朝来数花发，身在尉佗宫。"],"theme":"送别","theme2":["山水田园"],"style":"豪放","style2":["绮丽","清新"],"mood":"惆怅","mood2":[],"scene":["园林","重阳"],"cats":{"抒情":["离别"],"生活":["写桥"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.402},{"uid":"424be0b8-1f41-4659-9e87-3e9bcbb7cab9","title":"过司空曙村居","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南北与山邻，蓬庵庇一身。","繁霜疑有雪，枯草似无人。","遂性在耕稼，所交唯贱贫。","何言张掾傲，每重德璋亲。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","山"],"cats":{"抒情":["孤独"],"生活":["乡村"]},"theme_conf":0.662},{"uid":"99fc9acc-fbe7-4ecf-a3f3-5b9426ed68eb","title":"舞曲歌辞 屈柘词","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["杨柳萦桥绿，玫瑰拂地红。","绣衫金騕褭，花髻玉珑璁。","宿雨香潜润，春流水暗通。","画楼初梦断，晴日照湘风。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["花","春","雨","楼"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"f1befe2e-2e4d-4220-aa06-5fae1d3a1a04","title":"送王绪剡中","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不见关山去，何时到郯中。","已闻成竹木，更道长儿童。","篱落云常聚，村墟水自通。","朝朝忆玄度，非是对清风。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["塞外","山"],"cats":{"抒情":["思念"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.592},{"uid":"cp749e871e4d03de","title":"淡黄柳","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["空城晓月。","吹入垂杨陌。","马上单衣寒恻恻。","看尽鹅黄嫩绿，都是江南旧相识。","正岑寂。","明朝又寒食。","强携酒、小桥宅，怕梨花落尽成秋色。","燕燕飞来，问春何在，唯有池塘自碧。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":["恬淡"],"scene":["清明","江南","酒","秋","春","月"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"生活":["写桥"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.86},{"uid":"66ebcb4d-63b0-485b-8ba3-bb6f6963454c","title":"塞上曲二首 二","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["汉家旌帜满阴山，不遣胡儿匹马还。","愿得此身长报国，何须生入玉门关。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"抒情":["爱国"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"5f5d6ee5-b0eb-4fe8-b26f-26f4bd9fe093","title":"杂曲歌辞 渭城少年行","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["洛阳二月梨花飞，秦地行人春忆归。","扬鞭走马城南陌，朝逢驿使秦川客。","驿使前日发章台，传道长安春早来。","棠梨宫中燕初至，葡萄馆里花正开。","念此使人归更早，三月便达长安道。","长安道上春可怜，摇风荡日曲河边。","万户楼台临渭水，五陵花柳满秦川。","秦川寒食盛繁华，游子春来喜见花。","鬬鸡下杜尘初合，走马章台日半斜。","章台帝城称贵里，青楼日晚歌钟起。","贵里豪家白马骄，五陵年少不相饶。","双双挟弹来金市，两两鸣鞭上渭桥。","渭城桥头酒新熟，金鞍白马谁家宿。","可怜锦瑟筝琵琶，玉台清酒就君家。","小妇春来不解羞，娇歌一曲杨柳花。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":["欢愉"],"scene":["楼","清明","春","酒"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"人生":["青春"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.579},{"uid":"c48a91ea-6d94-42d1-8466-f5a9f42cc1d6","title":"送兵到蓟北","author":"高适","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["积雪与天迥，屯军连塞愁。","谁知此行迈，不为觅封侯。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["塞外","雪"],"cats":{"抒情":["伤感"],"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.529},{"uid":"66312123-6671-49e5-a4ed-790959f4157e","title":"江村乱后","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江村日暮寻遗老，江水东流横浩浩。","竹里闲窗不见人，门前旧路生青草。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"生活":["乡村"]},"theme_conf":0.785},{"uid":"ef9d3efd-0eb2-413e-a455-2ee05bc16f7d","title":"横吹曲辞 前出塞九首 四","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["送徒既有长，远戍亦有身。","生死向前去，不劳吏怒嗔。","路逢相识人，附书与六亲。","哀哉两决绝，不复同苦辛。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":0.776},{"uid":"ae472a2c-7977-4ed6-a893-7ef7c3136666","title":"柴门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤舟登瀼西，回首望两崖。","东城干旱天，其气如焚柴。","长影没窈窕，余光散唅呀。","大江蟠嵌根，归海成一家。","下冲割坤轴，竦壁攒镆铘。","萧飒洒秋色，氛昏霾日车。","峡门自此始，最窄容浮查。","禹功翊造化，疎凿就攲斜。","巨渠决太古，众水为长蛇。","风烟渺吴蜀，舟楫通盐麻。","我今远游子，飘转混泥沙。","万物附本性，约身不愿奢。","茅栋盖一床，清池有余花。","浊醪与脱粟，在眼无咨嗟。","山荒人民少，地僻日夕佳。","贫病固其常，富贵任生涯。","老于干戈际，宅幸蓬荜遮。","石乱上云气，杉清延月华。","赏妍又分外，理惬夫何夸。","足了垂白年，敢居高士差。","书此豁平昔，回首犹暮霞。"],"theme":"山水田园","theme2":["羁旅思乡","闲适隐逸"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","秋","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"山水":["长江"],"天气":["月亮"],"生活":["乡村"]},"theme_conf":0.35},{"uid":"cpd2765c5b36f5e9","title":"青玉案","author":"无名氏","dynasty":"宋","section":"宋词","form":"词","paragraphs":["年年社日停针线。","怎忍见、双飞燕。","今日江城春已半。","一身犹在，乱山深处，寂寞溪桥畔。","春衫著破谁针线。","点点行行泪痕满。","落日解鞍芳草岸。","花无人戴，酒无人劝，醉也无人管。"],"theme":"羁旅思乡","theme2":["山水田园","闲适隐逸"],"style":"婉约","style2":["绮丽","清新"],"mood":"孤寂","mood2":[],"scene":["酒","春","花"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.93},{"uid":"b323c71f-ed8e-49cd-8baf-42089fa17706","title":"石州城","author":"武元衡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丈夫心爱横行，报国知嫌命轻。","楼兰径百战，更道戍龙城。","锦字窦车骑，胡笳李少卿。","生离两不见，万古难为情。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑","幽峭"],"mood":"慷慨","mood2":[],"scene":["楼"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.828},{"uid":"a9d85d1f-936c-489c-a074-9e2be10e5af6","title":"遣闷奉呈严公二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["白水鱼竿客，清秋鹤发翁。","胡为来幕下，秪合在舟中。","黄卷真如律，青袍也自公。","老妻忧坐[痹]，幼女问头风。","平地专欹倒，分曹失异同。","礼甘衰力就，义忝上官通。","畴昔论诗蚤，光辉仗钺雄。","宽容存性拙，剪拂念途穷。","露裛思藤架，烟霏想桂丛。","信然龟触网，直作鸟窥笼。","西岭纡村北，南江遶舍东。","竹皮寒旧翠，椒实雨新红。","浪簸船应坼，杯干瓮即空。","藩篱生野径，斤斧任樵童。","束缚酬知己，蹉跎効小忠。","周防期稍稍，太简遂悤悤。","晓入朱扉启，昏归画角终。","不成寻别业，未敢息微躬。","乌鹊愁银汉，驽骀怕锦幪。","会希全物色，时放倚梧桐。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":[],"scene":["鸟","舟","雨"],"cats":{"抒情":["友情","伤感"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.374},{"uid":"d7806360-7bc2-41cb-b8bf-f889b1c9362e","title":"塞上梅","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天山路傍一株梅，年年花发黄云下。","昭君已殁汉使回，前后征人惟系马。","日夜风吹满陇头，还随陇水东西流。","此花若近长安路，九衢年少无攀处。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","冬"],"cats":{"生活":["边塞"],"植物":["梅花"]},"theme_conf":0.839},{"uid":"af84c796-64c8-4c7c-9e57-ef9340202749","title":"七夕","author":"张文恭","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凤律惊秋气，龙梭静夜机。","星桥百枝动，云路七香飞。","映月回雕扇，凌霞曳绮衣。","含情向华幄，流态入重闱。","欢余夕漏尽，怨结晓骖归。","谁念分河汉，还忆两心违。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["愁怨","欢愉"],"scene":["七夕"],"cats":{"抒情":["思念"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.95},{"uid":"2264ebda-c26d-44d0-ade0-b4e4f611f5cf","title":"宫词一百首 九十四","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["画作天河刻作牛，玉梭金镊采桥头。","每年宫里穿针夜，𠡠赐诸亲乞巧楼。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","夜","楼"],"cats":{"抒情":["闺怨"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.732},{"uid":"a50fdaca-5397-4000-8c2c-bfcb9ab8e681","title":"杂曲歌辞 从军中行路难二首 一","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见封狐雄虺自成群，冯深负固结妖氛。","玉玺分兵征恶少，金坛受律动将军。","将军拥旄宣庙略，战士横行静夷落。","长驱一息背铜梁，直指三巴逾劒阁。","阁道岧嶤上戍楼，劒门遥裔俯灵丘。","邛关九折无平路，江水双源有急流。","征役无期返，他乡岁华晚。","杳杳丘陵出，苍苍林薄远。","途危紫盖峰，路涩青泥坂。","去去指哀牢，行行入不毛。","绝壁千里险，连山四望高。","中外分区宇，夷夏殊风土。","交趾枕南荒，昆弥临北户。","川源饶毒雾，溪谷多淫雨。","行潦四时流，崩查千岁古。","漂梗飞蓬不自安，扪藤引葛度危峦。","昔时闻道从军乐，今日方知行路难。","苍江绿水东流驶，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻烟波。","三春边地风光少，五月泸中瘴疠多。","朝驱疲斥候，夕息倦谁何。","向月弯繁弱，连星转太阿。","重义轻生怀一顾，东伐西征凡几度。","夜夜朝朝斑鬓新，年年岁岁戎衣故。","灞城隅，滇池水，天涯望转积，地际行无已。","徒觉炎凉节物非，不知关山千万里。","弃置勿重陈，重陈多苦辛。","且悦清笳杨柳曲，讵忆芳园桃李人。","绛节朱旗分白羽，丹心白刃酬明主。","但令一技君王识，谁惮三边征战苦。","行路难，行路难，岐路几千端。","无复归云冯短翰，望日想长安。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新","绮丽"],"mood":"相思","mood2":["恬淡"],"scene":["江","夏","塞外","楼","山","春"],"cats":{"抒情":["思念"],"四季":["春天","夏天"],"天气":["星星"],"人生":["战争"],"生活":["边塞"],"节日":["春节"]},"theme_conf":0.599},{"uid":"f2413b7a-cfda-4d88-8c24-6684aa4bcf8a","title":"七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今兹商用事，余热亦已末。","衰年旅炎方，生意从此活。","亭午减汗流，北邻耐人聒。","晚风爽乌匼，筋力苏摧折。","闭目逾十旬，大江不止渴。","退藏恨雨师，健步闻旱魃。","园蔬抱金玉，无以供采掇。","密云虽聚散，徂暑终衰歇。","前圣眘焚巫，武王亲救暍。","阴阳相主客，时序递回斡。","洒落唯清秋，昏霾一空阔。","萧萧紫塞雁，南向欲行列。","歘思红颜日，霜露冻阶闼。","胡马挟雕弓，鸣弦不虚发。","长鈚逐狡兔，突羽当满月。","惆怅白头吟，萧条游侠窟。","临轩望山阁，缥缈安可越。","高人炼丹砂，未念将朽骨。","少壮迹颇疎，欢乐曾倏忽。","杖藜风尘际，老丑难翦拂。","吾子得神仙，本是池中物。","贱夫美一睡，烦促婴词笔。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["沉郁"],"mood":"欢愉","mood2":["慷慨"],"scene":["楼","月","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","秋天"],"山水":["长江"],"天气":["太阳","月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.448},{"uid":"738fc3d5-b2e3-4f00-8a81-496c103cdd58","title":"同吉中孚梦桃源 二","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夜静春梦长，梦逐仙山客。","园林满芝术，鸡犬傍篱栅。","几处花下人，看予笑头白。"],"theme":"山水田园","theme2":["游仙梦幻"],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","欢愉"],"scene":["春","夜","山","园林"],"cats":{"四季":["春天"],"人生":["梦想"],"生活":["乡村"],"植物":["桃花"]},"theme_conf":0.438},{"uid":"0222bb09-1f03-473b-b3d7-bd41709a2643","title":"朱陈村","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["徐州古丰县，有村曰朱陈。","去县百余里，桑麻青氛氲。","机梭声札札，牛驴走纭纭。","女汲涧中水，男采山上薪。","县远官事少，山深人俗淳。","有财不行商，有丁不入军。","家家守村业，头白不出门。","生为村之民，死为村之尘。","田中老与幼，相见何欣欣。","一村唯两姓，世世为婚姻。","亲疎居有族，少长游有群。","黄鸡与白酒，欢会不隔旬。","生者不远别，嫁娶先近邻。","死者不远葬，坟墓多绕村。","既安生与死，不苦形与神。","所以多寿考，往往见玄孙。","我生礼义乡，少小孤且贫。","徒学辨是非，祗自取辛勤。","世法贵名教，士人重冠婚。","以此自桎梏，信为大谬人。","十岁解读书，十五能属文。","二十举秀才，三十为谏臣。","下有妻子累，上有君亲恩。","承家与事国，望此不肖身。","忆昨旅游初，迨今十五春。","孤舟三适楚，羸马四经秦。","昼行有饥色，夜寝无安魂。","东西不暂住，来往若浮云。","离乱失故乡，骨肉多散分。","江南与江北，各有平生亲。","平生终日别，逝者隔年闻。","朝忧卧至暮，夕哭坐达晨。","悲火烧心曲，愁霜侵鬓根。","一生苦如此，长羡村中民。"],"theme":"山水田园","theme2":["羁旅思乡","悼亡挽歌"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["江南"],"cats":{"抒情":["离别","思乡","伤感","悼亡"],"人物":["老师"],"人生":["读书"],"生活":["乡村","田野"]},"theme_conf":0.301},{"uid":"f10c2ed6-1350-49fb-83e1-c2b6bcea8a02","title":"早梅","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一树寒梅白玉条，迥临村路傍溪桥。","应缘近水花先发，疑是经春雪未销。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬"],"cats":{"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.514},{"uid":"d21445d0-930f-43ac-b31b-de28e5ec6e6b","title":"杂曲歌辞 杨柳枝 三","author":"和凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鹊桥初就咽银河，今夜仙郎自性和。","不是昔年攀桂树，岂能月里索姮娥。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["月","七夕","夜"],"cats":{"生活":["写桥"],"节日":["七夕节"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"762e0a43-b8ed-4a11-bb82-28958998d354","title":"横吹曲辞 出塞 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["白花垣上望京师，黄河水流无尽时。","穷秋旷野行人绝，马首东来知是谁。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","江"],"cats":{"山水":["黄河"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"252c40ba-d76c-4893-925b-41883a6f254c","title":"横吹曲辞 出塞","author":"陈子昂","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["忽闻天上将，关塞重横行。","始返楼兰国，还向朔方城。","黄金装战马，白羽集神兵。","星月开天阵，山川列地营。","晚风吹画角，春色耀飞旌。","宁知班定远，独是一书生。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["塞外"],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.843},{"uid":"23ef9a8b-4c38-48e4-a143-a54a9d411abc","title":"送从舅成都县丞广归蜀","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["襃谷通岷岭，青冥此路深。","晚程椒瘴热，野饭荔枝阴。","古郡三刀夜，春桥万里心。","唯应对杨柳，暂醉卓家琴。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["春","夜","酒"],"cats":{"四季":["春天"],"生活":["写桥"],"食物":["荔枝"]},"theme_conf":0.466},{"uid":"f7fd325f-acb2-479e-9c0d-e104a1c519df","title":"锄药咏","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["莳药穿林复在𪩘，浓香秀色深能浅。","云气垂来裛露偏，松阴占处知春晚。","拂曙残莺百啭催，萦泉带石几花开。","不随飞鸟缘枝去，如笑幽人出谷来。","对之不觉忘疎嬾，废卷荷锄嫌日短。","岂无萱草树堦墀，惜尔幽芳世所遗。","但使芝兰出萧艾，不辞手足皆胼胝。","宁学陶潜空嗜酒，颓龄舍此事东菑。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春","鸟","酒"],"cats":{"四季":["春天"],"生活":["田野"]},"theme_conf":0.385},{"uid":"acd96031-2a20-4c02-bed0-033329160c8d","title":"横吹曲辞 前出塞九首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["戚戚去故里，悠悠赴交河。","公家有程期，亡命婴祸罗。","君已富土境，开边一何多？","弃绝父母恩，吞声行负戈。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":0.614},{"uid":"ca4cc6b3-a324-48c0-89c0-bb36c09c4930","title":"下终南山过斛斯山人宿置酒","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暮从碧山下，山月随人归。","却顾所来径，苍苍横翠微。","相携及田家，童稚开荆扉。","绿竹入幽径，青萝拂行衣。","欢言得所憩，美酒聊共挥。","长歌吟松风，曲尽河星稀。","我醉君复乐，陶然共忘机。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["酒","山"],"cats":{"生活":["田野"],"食物":["写酒"]},"theme_conf":0.388},{"uid":"c8928378-7719-4940-a9b9-848d78b21d5b","title":"春日江村五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["种竹交加翠，栽桃烂熳红。","经心石镜月，到面雪山风。","赤管随王命，银章付老翁。","岂知牙齿落，名玷荐贤中。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["春","江","雪"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"cde212e6-2e8d-4c74-aa0f-d8e8cb9835a4","title":"题裴二十一新园","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东郭访先生，西郊寻隐路。","久为江南客，自有云阳树。","已得闲园心，不知公府步。","开门白日晚，倚杖青山暮。","果熟任霜封，篱疎从水度。","穷年无牵缀，往事惜沦悮。","唯见耦耕人，朝朝自来去。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","江南"],"cats":{"生活":["田野"]},"theme_conf":0.547},{"uid":"992319d5-c110-4285-9302-cb6d8144bd85","title":"田家春望","author":"高适","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["出门何所见，春色满平芜。","可叹无知己，高阳一酒徒。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["友情"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.598},{"uid":"7782bee4-6ffc-4909-b441-71ab6cd74692","title":"南泾渔父","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["予方任疎慵，地僻即所好。","江流背村落，偶往心已嫪。","田家相去远，岑寂且纵傲。","出户手先筇，见人头未帽。","南泾有渔父，往往携稚造。","问其所以渔，对我真蹈道。","我初簎鱼鼈，童丱至于耄。","窟穴与生成，自然通壶奥。","孜孜戒吾属，天物不可暴。","大小参去留，候其孳养报。","终朝获鱼利，鱼亦未常耗。","同覆天地中，违仁辜覆焘。","余观为政者，此意谅难到。","民皆死搜求，莫肯兴愍悼。","今年川泽旱，前岁山源潦。","牒诉已盈庭，闻之类禽噪。","譬如死鸡鹜，岂不容乳抱。","孟子讥宋人，非其揠苗躁。","吾嘉渔父旨，雅叶贤哲操。","倘遇采诗官，斯文诚敢告。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["旷达"],"mood":"孤寂","mood2":["悲怆"],"scene":[],"cats":{"山水":["江河"],"人物":["父亲"],"生活":["田野"]},"theme_conf":0.472},{"uid":"ab185b82-5200-4a6d-a327-a21749e60981","title":"越溪村居","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["年来桡客寄禅扉，多话贫居在翠微。","黄雀数声催柳变，清溪一路踏花归。","空林野寺经过少，落日深山伴侣稀。","负米到家春未尽，风萝闲扫钓鱼矶。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江南","春"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":0.495},{"uid":"ecfeec5e-3205-401e-bc5d-e9b58efb9031","title":"桃源行送友","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["武陵川径入幽遐，中有鸡犬秦人家，家傍流水多桃花。","桃花两边种来久，流水一通何时有。","垂条落蘂暗春风，夹岸芳菲至山口。","岁岁年年能寂寥，林下青苔日为厚。","时有仙鸟来衔花，曾无世人此携手。","可怜不知若为名，君往从之多所更。","古驿荒桥平路尽，崩湍怪石小溪行。","相见维舟登览处，红堤绿岸宛然成。","多君此去从仙隐，令人晚节悔营营。"],"theme":"送别","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["春","花"],"cats":{"抒情":["友情"],"四季":["春天"],"生活":["写桥"],"植物":["桃花"]},"theme_conf":0.408},{"uid":"a5301061-dc9b-4a5b-b5ec-55cb5c2feb65","title":"晋公魏国夫人柳氏挽歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鱼轩海上遥，鸾影月中销。","双剑来时合，孤桐去日凋。","夕阳迷陇隧，秋雨咽笳箫。","画翣无留影，铭旌已度桥。"],"theme":"悼亡挽歌","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","月","雨"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"],"生活":["写桥"],"植物":["柳树"]},"theme_conf":0.99},{"uid":"d77f340f-1a04-4c5b-9704-2536e4249c6b","title":"野望","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西山白雪三奇戍，南浦清江万里桥。","海内风尘诸弟隔，天涯涕泪一身遥。","唯将迟暮供多病，未有涓埃荅圣朝。","跨马出郊时极目，不堪人事日萧条。"],"theme":"咏怀抒感","theme2":["边塞征战","送别","闲适隐逸"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","山","江"],"cats":{"抒情":["离别","伤感"],"生活":["写桥"]},"theme_conf":0.84},{"uid":"0145ae39-2773-42f7-9287-ea653ce947a7","title":"过故斛斯校书庄二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["燕入非旁舍，鸥归祗故池。","断桥无复板，卧柳自生枝。","遂有山阳作，多惭鲍叔知。","素交零落尽，白首泪双垂。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["伤感","怀古"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.617},{"uid":"3f44618a-ec8e-40e0-bbfd-7cefa27e61d2","title":"杂曲歌辞 凉州词","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["昨夜蕃兵报国讐，沙州都护破凉州。","黄河九曲今归汉，塞外纵横战血流。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["江","塞外","夜"],"cats":{"抒情":["爱国"],"山水":["黄河"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"2f1dce3e-e0f6-4da4-b110-e8686d1c1119","title":"村南逢病叟","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["双膝过颐顶在肩，四邻知姓不知年。","卧驱鸟雀惜禾黍，犹恐诸孙无社钱。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"生活":["乡村"]},"theme_conf":1.0},{"uid":"784b5bc3-05d5-425d-8935-49c42bf2cccc","title":"寄宿田家","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["田家老翁住东陂，说道平生隐在兹。","鬓白未曾记日月，山青每到识春时。","门前种柳深成巷，野谷流泉添入池。","牛壮日耕十亩地，人闲常扫一茅茨。","客来满酌清尊酒，感兴平吟才子诗。","岩际窟中藏鼹鼠，潭边竹里隐鸬鹚。","村墟日落行人少，醉后无心怯路岐。","今夜只应还寄宿，明朝拂曙与君辞。"],"theme":"山水田园","theme2":["送别"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","山"],"cats":{"生活":["田野"]},"theme_conf":0.373},{"uid":"ee1af307-1e4b-4b18-a2d9-1194784cae0a","title":"寄张仲甫","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["悲风生旧浦，云岭隔东田。","伏腊同鸡黍，柴门闭雪天。","孤村明夜火，稚子候归船。","静者心相忆，离居畏度年。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂","恬淡"],"scene":["雪","夜","舟"],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.94},{"uid":"c8284ada-18a4-46ad-8a47-c2b0c02204ff","title":"过柳州","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["地尽江南戍，山分桂北林。","火云三月合，石路九疑深。","暗谷随风过，危桥共鸟寻。","羁魂愁似绝，不复待猨吟。"],"theme":"羁旅思乡","theme2":["山水田园","边塞征战","羁旅思乡"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["月","江南","江","山"],"cats":{"抒情":["思乡","伤感"],"生活":["写桥"],"植物":["柳树"]},"theme_conf":0.93},{"uid":"526d4ecc-e123-4b9d-a213-958bb947593d","title":"凉州词二首 一","author":"王之涣","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄河远上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春光不度玉门关。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["江","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":0.508},{"uid":"43d23382-d543-4aba-8a11-ed524328785d","title":"横吹曲辞 紫骝马","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骝马照金鞍，转战入皐兰。","塞门风稍急，长城水正寒。","雪暗鸣珂重，山长喷玉难。","不辞横绝漠，流血几时干。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":1.0},{"uid":"9deee86d-3d16-40f1-aff9-f8805c75d827","title":"送王正字山寺读书","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["欲究先儒教，还过支遁居。","山堦闲听法，竹迳独看书。","向日荷新卷，迎秋柳半疎。","风流有佳句，不似带经锄。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["读书"],"生活":["田野"]},"theme_conf":0.418},{"uid":"cp8d127e60c3623a","title":"生查子","author":"王观","dynasty":"宋","section":"宋词","form":"词","paragraphs":["关山魂梦长，塞雁音书少。","两鬓可怜青，一夜相思老。","归傍碧纱窗，说与人人道。","真个别离难，不似相逢好。"],"theme":"爱情相思","theme2":["羁旅思乡","边塞征战","爱情相思"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["塞外"],"cats":{"抒情":["爱情","离别","思念","思乡"],"生活":["边塞"]},"theme_conf":0.82},{"uid":"b8500c5b-349d-41e5-b495-7b8ef514f191","title":"玉台观","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["中天积翠玉台遥，上帝高居绛节朝。","遂有冯夷来击鼓，始知嬴女善吹箫。","江光隐见鼋鼍窟，石势参差乌鹊桥。","更肯红颜生羽翼，便应黄发老渔樵。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","七夕"],"cats":{"生活":["写桥"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"6d3b137e-8d62-4d8d-be0f-88c9589f8ae6","title":"野老","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["野老篱前江岸回，柴门不正逐江开。","渔人网集澄潭下，贾客船随返照来。","长路关心悲劒阁，片云何意傍琴台。","王师未报收东郡，城阙秋生画角哀。"],"theme":"咏怀抒感","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["楼","秋","江","舟"],"cats":{"抒情":["伤感"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.7},{"uid":"79462191-3bcb-4599-b51b-40bcf4d3065d","title":"杂曲歌辞 结客少年场行","author":"虞羽客","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽幷侠少年，金络控连钱。","窃符方救赵，击筑正怀燕。","轻生辞凤阙，挥袂上祁连。","陆离横宝劒，出没惊徂旃。","蒙轮恒顾敌，超乘忽争先。","摧枯逾百战，拓地远三千。","骨都魂已散，楼兰首复传。","龙城含晓雾，瀚海隔遥天。","歌吹金微返，振旅玉门旋。","烽火今已息，非复照甘泉。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["婉约","清新"],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"人生":["青春","战争"],"生活":["边塞"]},"theme_conf":0.565},{"uid":"fde17d21-b335-43ef-8a18-c476b60f4b57","title":"茅堂检校收稻二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["稻米炊能白，秋葵煮复新。","谁云滑易饱，老藉软俱匀。","种幸房州熟，苗同伊阙春。","无劳映渠盌，自有色如银。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","春"],"cats":{"四季":["春天","秋天"],"生活":["田野"]},"theme_conf":1.0},{"uid":"d572cc60-44fc-40c3-9c2f-08e966153fdd","title":"横吹曲辞 前出塞九首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["出门日已远，不受徒旅欺。","骨肉恩岂断，男儿死无时。","走马脱辔头，手中挑青丝。","捷下万仞冈，俯身试搴旗。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":0.601},{"uid":"ee380cd0-fea2-4baa-92b7-c82c834265e6","title":"相和歌辞  豫章行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["胡风吹代马，北拥鲁阳关。","吴兵照海雪，西讨何时还？","半渡上辽津，黄云惨无颜。","老母与子别，呼天野草间。","白马绕旌旗，悲鸣相追攀。","白杨秋月苦，早落豫章山。","本为休明人，斩虏素不闲。","岂惜战鬬死，为君埽凶顽。","精感石没羽，岂忘惮险艰。","楼船若鲸飞，波荡落星湾。","此曲不可奏，三军鬓成斑。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"悲怆","mood2":[],"scene":["雪","秋","月","楼","舟"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["母亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.582},{"uid":"ae4776cb-0cb8-4a59-bad7-7a8aefac04bb","title":"郊村独游","author":"徐夤","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["岁闰堪怜历候迟，出门惟与野云期。","惊鱼掷上绿荷芰，栖鸟啄余红荔枝。","末路可能长薄命，修途应合有良时。","市头相者休相戏，蹙膝先生半自知。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"生活":["乡村"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"cp70325eab0d962a","title":"临江仙","author":"陈与义","dynasty":"宋","section":"宋词","form":"词","paragraphs":["忆昔午桥桥上饮，坐中多是豪英。","长沟流月去无声。","杏花疏影里，吹笛到天明。","二十馀年如一梦，此身虽在堪惊。","闲登小阁看新晴。","古今多少事，渔唱起三更。"],"theme":"游仙梦幻","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["江","夜","月"],"cats":{"抒情":["思念"],"生活":["写桥"]},"theme_conf":0.571},{"uid":"a853ea87-07a2-401d-85ab-ff6ad9767bdc","title":"山路见梅感而有作","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["莫言山路僻，还被好风催。","行客凄凉过，村篱冷落开。","晚溪寒水照，晴日数蜂来。","重忆江南酒，何因把一杯。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["山","酒","江南"],"cats":{"抒情":["思念","伤感"],"生活":["乡村"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"40e33874-18b2-4ad8-942e-41240bc9d97c","title":"秋兴八首 七","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昆明池水汉时功，武帝旌旗在眼中。","织女机丝虚月夜，石鲸鳞甲动秋风。","波漂菰米沈云黑，露冷莲房坠粉红。","关塞极天唯鸟道，江湖满地一渔翁。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"生活":["边塞"],"节日":["七夕节"]},"theme_conf":0.7},{"uid":"35b59fb5-75cd-4bf0-ac6e-86b0dd9cb22a","title":"焦篱店醉题","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛下渠头百卉新，满筵歌笑独伤春。","何须更弄邵翁伯，即我此身如此人。"],"theme":"咏物","theme2":["山水田园","闲适隐逸"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["酒","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"生活":["乡村"],"食物":["写酒"]},"theme_conf":0.43},{"uid":"ee2a3000-9127-43fa-8618-89a1937322cb","title":"和张仆射塞下曲 三","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["月黑鴈飞高，单于夜遁逃。","欲将轻骑逐，大雪满弓刀。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","塞外"],"cats":{"生活":["边塞"]},"theme_conf":0.867},{"uid":"0a3c8ec7-42d7-48b9-90df-b961b50d2a28","title":"逢王泌自东京至","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["逢君自乡至，雪涕问田园。","几处生乔木，谁家在旧村。","山峰横二室，水色映千门。","愁见游从处，如今花正繁。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["山","雪"],"cats":{"抒情":["思乡","伤感"],"生活":["田野"]},"theme_conf":0.554},{"uid":"66711c88-d15e-4440-a51c-03447a294dee","title":"秋中雨田园即事","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["漠漠重云暗，萧萧密雨垂。","为霖淹古道，积日满荒陂。","五稼何时获，孤村几户炊。","乱流发通圃，腐叶著秋枝。","暮爨新樵湿，晨渔旧浦移。","空余去年菊，花发在东篱。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["雨","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写雨"],"生活":["乡村","田野"]},"theme_conf":0.762},{"uid":"4f87da9b-d715-4bc5-8ab8-319d5e0427a4","title":"江行无题一百首 十八","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["柳拂斜开路，篱边数户村。","可能还有意，不掩向江门。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"ce491725-b96b-46a7-b83c-463d2094ef3f","title":"和张仆射塞下曲 一","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["鹫翎金仆姑，燕尾绣蝥弧。","独立扬新令，千营共一呼。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["欢愉"],"scene":["塞外"],"cats":{"抒情":["孤独"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"eba84f73-7c00-4307-ba41-09a68002d058","title":"曲江三章章五句 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["自断此生休问天，杜曲幸有桑麻田。","故将移住南山边，短衣匹马随李广，看射猛虎终残年。"],"theme":"山水田园","theme2":["边塞征战"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"生活":["田野"]},"theme_conf":0.594},{"uid":"601d90fb-3589-44f1-9a25-9e16af2102c3","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["把烛成桥夜，回舟坐客时。","天高云去尽，江迥月来迟。","衰谢多扶病，招邀屡有期。","异方乘此兴，乐罢不无悲。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["幽峭","沉郁"],"mood":"欢愉","mood2":["悲怆"],"scene":["江","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"山水":["江河"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"1809b35f-90e9-48f1-9844-c467caabddd7","title":"琴曲歌辞 胡笳十八拍 第十八拍","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["归来故乡见亲族，田园半芜春草绿。","明烛重然煨烬灰，寒泉更洗沈泥玉。","载持巾栉礼仪好，一弄丝桐生死足。","出入关山十二年，哀情尽在胡笳曲。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","塞外","园林","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.412},{"uid":"cp416a83451dd8fb","title":"扬州慢","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["淮左名都，竹西佳处，解鞍少驻初程。","过春风十里，尽荠麦青青。","自胡马窥江去后，废池乔木，犹厌言兵。","渐黄昏，清角吹寒，都在空城。","杜郎俊赏，算而今，重到须惊。","纵豆蔻词工，青楼梦好，难赋深情。","二十四桥仍在，波心荡、冷月无声。","念桥边红药，年年知为谁生。"],"theme":"边塞征战","theme2":["山水田园"],"style":"幽峭","style2":["清新","悲慨"],"mood":"孤寂","mood2":["相思"],"scene":["春","楼","月"],"cats":{"四季":["春天"],"生活":["写桥"]},"theme_conf":0.618},{"uid":"d9bb3556-f0d9-4989-afdd-0163fb826a01","title":"相和歌辞 从军行","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋来风瑟瑟，群马胡行疾。","严城昼不开，伏兵暗相失。","天子庙堂拜，将军玉门出。","纷纷伊洛间，戎马数千匹。","军门压黄河，兵气冲白日。","平生怀伏劒，忼慨既投笔。","南登汉月孤，北走燕云密。","近取韩彭计，早知孙吴术。","丈夫清万里，谁能埽一室。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":["江","秋","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"1e5d503c-12ee-4e2c-a645-80e5e892316b","title":"赠薛戴","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晓雾忽为霜，寒蝉还罢响。","行人在长道，日暮多归想。","射策本何功，名登绛帐中。","遂矜丘室重，不料阮途穷。","交结慙时辈，龙钟似老翁。","机非鄙夫正，懒是平生性。","欹枕鸿雁高，闭关花药盛。","厨烟当雨绝，阶竹连窗暝。","欲赋苦饥行，无如消渴病。","旧业历胡尘，荒原少四邻。","田园空有处，兄弟未成人。","毛义心长苦，袁安家转贫。","今呈胸臆事，当为泪沾巾。"],"theme":"寄赠酬答","theme2":["民生疾苦"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["老师"],"生活":["田野"]},"theme_conf":0.96},{"uid":"bd9d6696-ea76-4268-a241-99cd7cd1820f","title":"送房元直赴北京","author":"严维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["犹道楼兰十万师，书生匹马去何之。","临歧未断归家目，望月空吟出塞诗。","常欲激昂论上策，不应憔悴老明时。","遥知到日逢寒食，彩笔长裾会晋祠。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","塞外","楼","月"],"cats":{"生活":["边塞"],"节日":["寒食节","清明节"]},"theme_conf":0.45},{"uid":"bcdf6f13-4cb9-418f-9279-c690522e0a27","title":"横吹曲辞 出塞","author":"王之涣","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄砂直上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春风不度玉门关。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["塞外"],"cats":{"抒情":["孤独"],"生活":["边塞"]},"theme_conf":0.667},{"uid":"ef36b0a2-6327-47a2-b777-ccf669af3ebb","title":"大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["老向巴人里，今辞楚塞隅。","入舟飜不乐，解缆独长吁。","窄转深啼狖，虚随乱浴凫。","石苔凌几杖，空翠扑肌肤。","叠壁排霜劒，奔泉溅水珠。","杳冥藤上下，浓澹树荣枯。","神女峰娟妙，昭君宅有无。","曲留明怨惜，梦尽失欢娱。","摆阖盘涡沸，欹斜激浪输。","风雷缠地脉，冰雪耀天衢。","鹿角真走险，狼头如跋胡。","恶滩宁变色，高卧负微躯。","书史全倾挠，装囊半压濡。","生涯临臬兀，死地脱斯须。","不有平川决，焉知众壑趋。","乾坤霾涨海，雨露洗春芜。","欧鸟牵丝飏，骊龙濯锦纡。","落霞沈绿绮，残月坏金枢。","泥笋苞初荻，沙茸出小蒲。","雁儿争水马，燕子逐樯乌。","绝岛容烟雾，环洲纳晓晡。","前闻辨陶牧，转眄拂宜都。","县郭南畿好，津亭北望孤。","劳心依憩息，朗咏划昭苏。","意遣乐还笑，衰迷贤与愚。","飘萧将素发，汩没听洪𬬻。","丘壑曾忘返，文章敢自诬。","此生遭圣代，谁分哭穷途。","卧疾淹为客，蒙恩早厕儒。","廷争酬造化，朴直乞江湖。","滟滪险相迫，沧浪深可逾。","浮名寻已已，嬾计却区区。","喜近天皇寺，先披古画图。","应经帝子渚，同泣舜苍梧。","朝士兼戎服，君王按湛卢。","旄头初俶扰，鹑首丽泥涂。","甲卒身虽贵，书生道固殊。","出尘皆野鹤，历块匪辕驹。","伊吕终难降，韩彭不易呼。","五云高太甲，六月旷抟扶。","回首黎元病，争权将帅诛。","山林托疲苶，未必免崎岖。"],"theme":"羁旅思乡","theme2":["羁旅思乡","边塞征战"],"style":"绮丽","style2":["沉郁","清新"],"mood":"欢愉","mood2":["悲怆","孤寂"],"scene":["江","鸟","春","舟","山"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"山水":["江河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.8},{"uid":"59fb3f01-65b2-416a-aefb-c13e502bfba1","title":"塞下曲四首 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["饮马渡秋水，水寒风似刀。","平沙日未没，黯黯见临洮。","昔日长城战，咸言意气高。","黄尘足今古，白骨乱蓬蒿。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"慷慨","mood2":["悲怆"],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"b6985205-7423-47bf-ad4d-19e2ee4eaed0","title":"夜闻觱篥","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["夜闻觱篥沧江上，衰年侧耳情所向。","邻舟一听多感伤，塞曲三更歘悲壮。","积雪飞霜此夜寒，孤灯急管复风湍。","君知天地干戈满，不见江湖行路难。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"孤寂","mood2":["悲怆","慷慨"],"scene":["夜"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"9d10fdb5-9d0a-4c80-9e21-27f82b929c9f","title":"相和歌辞 江南曲","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["长乐花枝雨点消，江城日暮好相邀。","春楼不闭葳蕤锁，绿水回通宛转桥。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江南","江"],"cats":{"山水":["江河"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"c269dec4-e6e7-40b3-b1c5-b371d0450eb0","title":"怀素上人草书歌","author":"窦冀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["狂僧挥翰狂且逸，独任天机摧格律。","龙虎惭因点画生，雷霆却避锋铓疾。","鱼牋娟素岂不贵，只嫌局促儿童戏。","粉壁长廊数十间，兴来小豁胸襟气。","长幼集，贤豪至，枕糟藉曲犹半醉。","忽然绝叫三五声，满壁纵横千万字。","吴兴张老尔莫颠，叶县公孙我何谓。","如熊如罴不足比，如虺如蛇不足拟。","涵物为动鬼神泣，狂风入林花乱起。","殊形怪状不易说，就中惊燥尤枯绝。","边风杀气同惨烈，崩槎卧木争摧折。","塞草遥飞大漠霜，胡天乱下阴山雪。","偏看能事转新奇，郡守王公同赋诗。","枯藤劲铁媿三舍，骤雨寒猨惊一时。","此生绝艺人莫测，假此常为护持力。","连城之璧不可量，五百年知草圣当。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"孤寂","mood2":["悲怆"],"scene":["雪","塞外"],"cats":{"抒情":["孤独"],"天气":["写风","写雨"],"人物":["儿童"],"生活":["边塞"]},"theme_conf":0.773},{"uid":"b541e528-83cc-4c89-9990-94fda479abdb","title":"留别郑三韦九兼洛下诸公","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["忆昨相逢论久要，顾君哂我轻常调。","羁旅虽同白社游，诗书已作青云料。","蹇质蹉跎竟不成，年过四十尚躬耕。","长歌达者桮中物，大笑前人身后名。","幸逢明盛多招隐，高山大泽征求尽。","此时亦得辞渔樵，青袍裹身荷圣朝。","犂牛钓竿不复见，县人邑吏来相邀。","远路鸣蝉秋兴发，华堂美酒离忧销。","不知何日更携手，应念兹晨去折腰。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["秋","酒"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"人生":["读书"],"生活":["田野"]},"theme_conf":0.432},{"uid":"cp8d4d1ee0e7ab9c","title":"应天长","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["条风布暖，霏雾弄晴，池塘遍满春色。","正是夜堂无月，沈沈暗寒食。","梁间燕，前社客。","似笑我、闭门愁寂。","乱花过，隔院芸香，满地狼藉。","长记那回时，邂逅相逢，郊外驻油壁。","又见汉宫传烛，飞烟五候宅。","青青草，迷路陌。","强带酒，细寻前迹。","市桥远，柳下人家，犹自相识。"],"theme":"节令风俗","theme2":["羁旅思乡","咏史怀古"],"style":"婉约","style2":["清新","冲淡"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["清明","园林","花","春","酒","夜"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["春天"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.68},{"uid":"3fa3ea71-5f33-42c7-8b83-2b96734e20cd","title":"戏赠韩判官绅卿","author":"李端","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["少寻道士居嵩岭，晚事高僧住沃洲。","齿发未知何处老，身名且被外人愁。","欲随山水居茅洞，已有田园在虎丘。","独怪子猷缘掌马，雪时不肯更乘舟。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":["孤寂"],"scene":["山","雪","舟"],"cats":{"抒情":["伤感","孤独"],"生活":["田野"]},"theme_conf":0.9},{"uid":"fc228c0d-4d2a-45a3-a137-a3ca03b5d7f0","title":"与从弟瑾同下第后出关言别 四","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["谁怜苦志已三冬，却欲躬耕学老农。","流水白云寻不尽，期君何处得相逢。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"抒情":["离别"],"四季":["冬天"],"生活":["田野"]},"theme_conf":0.476},{"uid":"d98f9148-c34c-47fb-9ec5-256813983782","title":"横吹曲辞 前出塞九首 五","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢迢万余里，领我赴三军。","军中异苦乐，主将宁尽闻。","隔河见胡骑，倏忽数百群。","我始为奴仆，几时树功勋。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":1.0},{"uid":"9bb05363-395d-48f6-b28a-55d3e414d6cf","title":"杂曲歌辞 发白马","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["将军发白马，旌节渡黄河。","箫鼓聒川岳，沧溟涌洪波。","武安有振瓦，易水无寒歌。","铁骑若雪山，饮流涸滹沱。","扬兵猎月窟，转战畧朝那。","倚剑登燕然，边峰列嵯峨。","萧条万里外，耕作五原多。","一扫清大漠，包虎戢金戈。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑","清新"],"mood":"慷慨","mood2":[],"scene":["山","江","雪","塞外","月"],"cats":{"山水":["黄河"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.777},{"uid":"fad6b3e0-61b6-4182-a4f5-2076f8cb940d","title":"题故将军庄","author":"李端","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["曾将数骑过桑干，遥对单于饬马鞍。","塞北征儿谙用剑，关西宿将许登坛。","田园芜没归耕晚，弓箭开离出猎难。","唯有老身如刻画，犹期圣主解衣看。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","园林"],"cats":{"生活":["田野","边塞"]},"theme_conf":0.675},{"uid":"cpead5ea21c5d00e","title":"六州歌头","author":"韩元吉","dynasty":"宋","section":"宋词","form":"词","paragraphs":["东风著意。","先上小桃枝。","红粉腻。","娇如醉。","倚朱扉。","记年时。","隐映新妆，面临水岸。","春将半。","云日暖。","斜桥转。","夹城西。","草软莎平跋马，垂杨渡、玉勒争嘶。","认蛾眉凝笑，脸薄拂燕支。","绣户曾窥。","恨依依。","共携手处。","香如雾。","红随步。","怨春迟。","消瘦损。","凭谁问。","只花知。","泪空垂。","旧日堂前燕，和烟雨，又双飞。","人自老。","春长好。","梦佳期。","前度刘郎，几许风流地，花也应悲。","但茫茫暮霭，目断武陵溪。","往事难追。"],"theme":"咏物","theme2":["爱情相思","山水田园","咏史怀古"],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.75},{"uid":"912f6639-a774-4d02-8c17-07f6bc3b1d63","title":"送大理张卿","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春色依依惜解携，月卿今夜泊隋堤。","白沙洲上江篱长，绿树村边谢豹啼。","迁客比来无倚仗，故人相去隔云泥。","越禽唯有南枝分，目送孤鸿飞向西。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","春","月","夜"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"生活":["乡村"]},"theme_conf":0.783},{"uid":"8fca99c7-a467-43a6-8893-4f2151ec902a","title":"赋得浦外虹送人","author":"陈润","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["日影化为虹，弯弯出浦东。","一条微雨后，五色片云中。","轮势随天度，桥形跨海通。","还将饮水处，持送使车雄。"],"theme":"送别","theme2":["咏物"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雨"],"cats":{"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.641},{"uid":"1fd7fb7a-8fd1-45bc-9dcb-803c52590d34","title":"横吹曲辞 折杨柳","author":"余延寿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["大道连国门，东西种杨柳。","葳蕤君不见，褭娜垂来久。","缘枝栖暝禽，雄去雌独吟。","余花怨春尽，微月起秋阴。","坐望窗中蝶，起攀枝上叶。","好风吹长条，妸娜何如妾。","妾见柳园新，高楼四五春。","莫吹胡塞曲，愁杀陇头人。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","塞外","秋","月","楼"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天","秋天"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.644},{"uid":"06798167-53e9-4e1b-b84f-b150edd78eac","title":"夏日梅溪馆寄庞舍人","author":"张祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["东阳宾礼重，高馆望行期。","埽簟因松叶，𥮾瓜使竹枝。","卷帘闻鸟近，翻枕梦人迟。","坐听津桥说，今营太守碑。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.567},{"uid":"e72db286-3b6a-425b-ad02-75248ea5a790","title":"度南涧","author":"蔡襄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["隠隠飞桥隔野烟，石矶西畔问渔船。","桃花尽日随流水，洞在清溪何处边。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","江"],"cats":{"生活":["写桥"]},"theme_conf":1.0},{"uid":"6f0897e1-ef12-4042-8e56-8cb1134cf9c3","title":"初秋夜坐","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["斜廊连绮阁，初月照宵帏。","塞冷鸿飞疾，园秋蝉噪迟。","露结林疎叶，寒轻菊吐滋。","愁心逢此节，长叹独含悲。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["幽峭","悲慨"],"mood":"孤寂","mood2":["愁怨","悲怆"],"scene":["秋","夜"],"cats":{"抒情":["伤感","孤独"],"四季":["秋天"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"8944162e-0986-4d0b-b9f9-ce0b899c0298","title":"相和歌辞 饮马长城窟行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["驰马渡河干，流深马渡难。","前逢锦车使，都护在楼兰。","轻骑犹衔勒，疑兵尚解鞍。","温池下绝涧，栈道接危峦。","拓地勋未赏，亡城律讵宽。","有月关犹暗，经春陇尚寒。","云昏无复影，冰合不闻湍。","怀君不可遇，聊持报一餐。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["春","楼","月"],"cats":{"四季":["春天"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.821},{"uid":"d3f24d39-65c7-4348-973b-f8b7db595abc","title":"江楼晚眺景物鲜奇吟玩成篇寄水部张员外","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["澹烟疎雨间斜阳，江色鲜明海气凉。","蜃散云收破楼阁，虹残水照断桥梁。","风翻白浪花千片，雁点青天字一行。","好著丹青图画取，题诗寄与水曹郎。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":["冲淡"],"mood":"相思","mood2":["恬淡"],"scene":["楼","江"],"cats":{"山水":["江河","西湖"],"生活":["写桥"]},"theme_conf":0.86},{"uid":"cae8a893-7ae6-4824-b4c5-eada730b075f","title":"苏武庙","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苏武魂销汉使前，古祠高树两茫然。","云边雁断胡天月，陇上羊归塞草烟。","廻日楼台非甲帐，去时冠劒是丁年。","茂陵不见封侯印，空向秋波哭逝川。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["惆怅","欢愉"],"scene":["楼","塞外","江南","秋","月"],"cats":{"抒情":["怀古"],"四季":["秋天"],"生活":["边塞"]},"theme_conf":0.461},{"uid":"5cd3431c-26c9-4049-90d6-f5049ca88c3e","title":"暝投灵智寺渡谿不得却取沿江路往","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["双岩泻一川，回马断桥前。","古庙阴风地，寒钟暮雨天。","沙虚留虎迹，水滑带龙涎。","却下临江路，潮深无渡船。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河","西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"c8bae0f0-12c6-4d6c-a35d-7077217cfdea","title":"南邻","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["锦里先生乌角巾，园收芋粟不全贫。","惯看宾客儿童喜，得食阶除鸟雀驯。","秋水才深四五尺，野航恰受两三人。","白沙翠竹江村暮，相对柴门月色新。"],"theme":"寄赠酬答","theme2":["山水田园","送别"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["月","夜"],"cats":{"天气":["月亮"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.72},{"uid":"303d9236-55b2-4dea-8967-74d66f440450","title":"相和歌辞 采菱行","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["白马湖平秋日光，紫菱如锦彩鸾翔。","荡舟游女满中央，采菱不顾马上郎。","争多逐胜纷相向，时转兰桡破轻浪。","长鬟弱袂动参差，钗影钏文浮荡漾。","笑语哇咬顾晚晖，蓼花绿岸扣舷归。","归来共到市桥步，野蔓系船萍满衣。","家家竹楼临广陌，下有连樯多估客。","携觞荐芰夜经过，醉踏大堤相应歌。","屈平祠下沅江水，月照寒波白烟起。","一曲南音此地闻，长安北望三千里。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["舟","酒","江"],"cats":{"抒情":["思乡"],"生活":["写桥"]},"theme_conf":0.421},{"uid":"de6b7e3d-03cd-4daa-bdc2-7fb820fda441","title":"出塞二首 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["塞外","山","月"],"cats":{"天气":["月亮"],"生活":["边塞"]},"theme_conf":0.776},{"uid":"6b4fc113-fbd5-44ef-9815-8a084b6f7a0b","title":"陈使君山庄","author":"牟融","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["新卜幽居地自偏，士林争羡使君贤。","数椽潇洒临溪屋，十亩膏腴附郭田。","流水断桥芳草路，淡烟疎雨落花天。","秋成准拟重来此，沈醉何妨一榻眠。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":["旷达"],"mood":"恬淡","mood2":[],"scene":["山","花","秋","雨"],"cats":{"四季":["秋天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.444},{"uid":"2d69a74c-1dad-46c4-a6d8-78d56d12145d","title":"东郊纳凉忆左威卫李录事收昆季太原崔参军三首 二","author":"楼颕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纳凉每选地，近得青门东。","林与缭垣接，池将沁水通。","枝交帝女树，桥映美人虹。","想是忘机者，悠悠在兴中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["恬淡"],"scene":[],"cats":{"抒情":["思念"],"山水":["庐山"],"人物":["女子"],"生活":["写桥"]},"theme_conf":0.695},{"uid":"4be77185-992e-4614-9746-de2e73c8a3c3","title":"关山月","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","[戍]客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山","月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.512},{"uid":"cp3132bc43c19b92","title":"摸鱼儿","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["怎知他、春归何处，相逢且尽尊酒。","少年袅袅天涯恨，长结西湖烟柳。","休回首。","但细雨断桥，憔悴人归后。","东风似旧。","问前度桃花，刘郎能记，花复认郎否。","君且住，草草留君翦韭。","前宵更恁时候。","深杯欲共歌声滑，翻湿春衫半袖。","空眉皱。","看白发尊前，已似人人有。","临分把手。","叹一笑论文，清狂顾曲，此会几时又。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["旷达","豪放"],"mood":"愁怨","mood2":[],"scene":["春","雨","酒","夜","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"山水":["西湖"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"5dd824cf-e4bc-4a99-a85a-48e2688ebbb2","title":"横吹曲辞 入塞曲 一","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["单于烽火动，都护去天涯。","别赐黄金甲，亲临白玉墀。","塞垣须静谧，师旅审安危。","定远条支宠，如今胜古时。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"恬淡","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.708},{"uid":"d9afbbdc-a953-44c7-93c6-dd133a03a2cd","title":"送辽阳使还军","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["征人歌且行，北上辽阳城。","二月戎马息，悠悠边草生。","青山出塞断，代地入云平。","昔者匈奴战，多闻杀汉兵。","平生报国愤，日夜角弓鸣。","勉君万里去，勿使虏尘惊。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","月","夜","山"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.666},{"uid":"38438036-586a-47f6-a4c0-d75bc30801c0","title":"相和歌辞 从军行二首 一","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["涂山烽候惊，弭节度龙城。","冀马楼兰将，燕犀上谷兵。","劒寒花不落，弓晓月逾明。","凛凛严霜节，冰壮黄河绝。","蔽日卷征蓬，浮天散飞雪。","全兵值月满，精骑乘胶折。","结发早驱驰，辛苦事旌麾。","马冻重关冷，轮摧九折危。","独有西山将，年年属数奇。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新"],"mood":"孤寂","mood2":["慷慨"],"scene":["雪","冬","江"],"cats":{"抒情":["孤独"],"山水":["黄河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.776},{"uid":"0ed53ef4-30ca-41ac-a629-d778e5cc2bfa","title":"相和歌辞 从军行","author":"李颀","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["白日登山望烽火，昏黄饮马傍交河。","行人刁斗风砂暗，公主琵琶幽怨多。","野营万里无城郭，雨雪纷纷连大漠。","胡雁哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲萄入汉家。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["豪放","雄浑"],"mood":"愁怨","mood2":[],"scene":["冬"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.748},{"uid":"c3c25268-b08b-4126-8e77-141cf5bbeaad","title":"茂陵村行赠何兆","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春天黄鸟啭，野迳白云闲。","解带依芳草，支颐想故山。","人行九州路，树老五陵间。","谁道临邛远，相如自忆还。"],"theme":"寄赠酬答","theme2":["山水田园","咏史怀古"],"style":"婉约","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","山"],"cats":{"抒情":["思念","怀古"],"四季":["春天"],"生活":["乡村"]},"theme_conf":0.64},{"uid":"57239e87-5c37-4c28-b253-a7bc96649ea4","title":"横吹曲辞 出塞","author":"张易之","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["侠客重恩光，骢马饰金装。","瞥闻传羽檄，驰突救边荒。","转战磨筓地，横行戴斗乡。","将军占太白，小妇怨流黄。","騕褭青丝骑，娉婷红粉妆。","一春莺度曲，八月雁成行。","谁堪坐秋思，罗袖拂空床。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["塞外","春","鸟"],"cats":{"四季":["春天"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.728},{"uid":"3e58f1b4-21c8-4f73-a641-cc0366ab1efd","title":"寄上兵部韩侍郎奉呈李户部卢刑部杜三侍郎","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["道路五千里，门阑三十年。","当时携手人，今日无半全。","咏题官舍内，赋韵僧房前。","公登略彴桥，况榜龙{舟卬}船。","远寺吐朱阁，春潮浮绿烟。","鹓鸿翔邓林，沙鸨飞吴田。","诸子纷出祖，中宵久留连。","坐客三千人，皆称主人贤。","国士分如此，家臣亦依然。","身在薜萝中，头刺文案边。","故吏已重叠，门生从联翩。","得罪为何名，无阶问皇天。","出门多岐路，命驾无由缘。","伏承诸侍郎，顾念犹迍邅。","圣代逢三宥，营魂空九迁。"],"theme":"应制干谒","theme2":["应制干谒","哲理悟道"],"style":"冲淡","style2":[],"mood":"惆怅","mood2":[],"scene":["舟","端午"],"cats":{"人物":["老师"],"人生":["战争"],"生活":["写桥"],"节日":["端午节"]},"theme_conf":0.92},{"uid":"872fd5bd-c6d8-4aef-bc03-85ac1550b561","title":"羌村 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["峥嵘赤云西，日脚下平地。","柴门鸟雀噪，归客千里至。","妻孥怪我在，惊定还拭泪。","世乱遭飘荡，生还偶然遂。","邻人满墙头，感叹亦歔欷。","夜阑更秉烛，相对如梦寐。"],"theme":"山水田园","theme2":["边塞征战"],"style":"幽峭","style2":["雄浑","婉约"],"mood":"愁怨","mood2":[],"scene":["夜"],"cats":{"抒情":["伤感"],"生活":["乡村"]},"theme_conf":0.47},{"uid":"888fd3d3-d777-401d-8b4a-e94d3ab3607f","title":"横吹曲辞 入塞曲 二","author":"沈彬","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苦战沙间卧箭痕，戍楼闲上望星文。","生希国泽分偏将，死夺河源荅圣君。","鸢覰败兵眠白草，马惊边鬼哭阴云。","功多地远无人纪，汉阁笙歌日又曛。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["塞外","楼"],"cats":{"山水":["黄河"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.877},{"uid":"cp3e738af0f919e6","title":"甘州・八声甘州","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["记玉关、踏雪事清游。","寒气脆貂裘。","傍枯林古道，长河饮马，此意悠悠。","短梦依然江表，老泪洒西州。","一字无题处，落叶都愁。","载取白云归去，问谁留楚佩，弄影中洲。","折芦花赠远，零落一身秋。","向寻常野桥流水，待招来、不是旧沙鸥。","空怀感，有斜阳处，却怕登楼。"],"theme":"山水田园","theme2":["羁旅思乡","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江","雪"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"生活":["写桥"]},"theme_conf":0.358},{"uid":"fabc073e-fb05-46e9-92c1-398d7c47c759","title":"阳城驿","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["商有阳城驿，名同阳道州。","阳公没已久，感我泪交流。","昔公孝父母，行与曾闵俦。","既孤善兄弟，兄弟和且柔。","一夕不相见，若怀三岁忧。","遂誓不婚娶，没齿同衾裯。","妹夫死他县，遗骨无人收。","公令季弟往，公与仲弟留。","相别竟不得，三人同远游。","共负他乡骨，归来藏故丘。","栖迟居夏邑，邑人无苟媮。","里中竞长短，来问劣与优。","官刑一朝耻，公短终身羞。","公亦不遗布，人自不盗牛。","问公何能尔，忠信先自修。","发言当道理，不顾党与讐。","声香渐翕习，冠盖若云浮。","少者从公学，老者从公游。","往来相告报，县尹与公侯。","名落公卿口，涌如波荐舟。","天子得闻之，书下再三求。","书中愿一见，不异旱地虬。","何以持为聘，束帛藉琳球。","何以持为御，驷马驾安辀。","公方伯夷操，事殷不事周。","我实唐士庶，食唐之田畴。","我闻天子忆，安敢专自由。","来为谏大夫，朝夕侍冕旒。","希夷惇薄俗，密勿献良筹。","神医不言术，人瘼曾暗瘳。","月请谏官俸，诸弟相对谋。","皆曰亲戚外，酒散目前愁。","公云不有尔，安得此嘉猷。","施余尽酤酒，客来相献酬。","日旰不谋食，春深仍弊裘。","人心良戚戚，我乐独由由。","贞元岁云暮，朝有曲如钩。","风波势奔蹙，日月光绸缪。","齿牙属为猾，禾黍暗生蟊。","岂无司言者，肉食吞其喉。","岂无司搏者，利柄扼其鞲。","鼻复势气塞，不得辩薰莸。","公虽未显谏，惴惴如患瘤。","飞章八九上，皆若珠暗投。","炎炎日将炽，积燎无人抽。","公乃帅其属，决谏同报仇。","延英殿门外，叩合仍叩头。","且曰事不止，臣谏誓不休。","上知不可遏，命以美语酬。","降官司成署，俾之为赘疣。","奸心不快活，击刺砺戈矛。","终为道州去，天道竟悠悠。","遂令不言者，反以言为訧。","喉舌坐成木，鹰鹯化为鸠。","避权如避虎，冠豸如冠猴。","平生附我者，诗人称好逑。","私来一执手，恐若坠诸沟。","送我不出户，决我不回眸。","唯有太学生，各具粮与糇。","咸言公去矣，我亦去荒陬。","公与诸生别，步步驻行驺。","有生不可诀，行行过闽瓯。","为师得如此，得为贤者不。","道州闻公来，鼓舞歌且讴。","昔公居夏邑，狎人如狎鸥。","况自为刺史，岂复援鼓桴。","滋章一时罢，教化天下遒。","炎瘴不得老，英华忽已秋。","有鸟哭杨震，无儿悲邓攸。","唯余门弟子，列树松与楸。","今来过此驿，若吊汨罗洲。","祠曹讳羊祜，此驿何不侔。","我愿避公讳，名为避贤邮。","此名有深意，蔽贤天所尤。","吾闻玄元教，日月冥九幽。","幽阴蔽翳者，永为幽翳囚。"],"theme":"咏史怀古","theme2":["送别","边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["孤寂","愁怨"],"scene":["夏","月"],"cats":{"抒情":["伤感","孤独","怀古"],"四季":["夏天"],"生活":["边塞"],"节日":["端午节"]},"theme_conf":0.96},{"uid":"436ddce1-56b4-4d4b-a0e0-2101cf9cebb3","title":"鼓吹曲辞 凯歌六首 二","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["官军西出过楼兰，营幕傍临月窟寒。","蒲海晓霜凝劒尾，葱山夜雪扑旌竿。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雪","楼","月","夜","山"],"cats":{"生活":["边塞"]},"theme_conf":1.0},{"uid":"cpc4da66c71f7c81","title":"三姝媚","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["湖山经醉惯。","溃春衫、啼痕酒痕无限。","又客长安，叹断襟零袂，尘谁浣。","紫曲门荒，沿败井、风摇青蔓。","对语东邻，犹是曾巢，谢堂双燕。","春梦人间须断。","但怪得、当年梦缘能短。","绣屋秦筝，傍海棠偏爱，夜深开宴。","舞歇歌沈，花未减、红颜先变。","伫久河桥欲去，斜阳泪满。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":["绮丽","幽峭"],"mood":"愁怨","mood2":[],"scene":["酒","春","花"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"d8e0db16-f56c-4180-bc8f-9724551bd8fc","title":"横吹曲辞 前出塞九首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["磨刀呜咽水，水赤刃伤手。","欲轻肠断声，心绪乱已久。","丈夫誓许国，愤惋复何有？","功名图麒麟，战骨当速朽。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"b795db08-a132-4d2c-9925-654193077602","title":"喜弟淑再至为长歌","author":"李渤","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["前年别时秋九月，白露吹霜金吹烈。","离鸿一别影初分，泪袖双挥心哽咽。","别来几度得音书，南岳知□□□□。","庐山峨峨倚天碧，捧排空崖千万尺。","社牓长题高士名，食堂每记云山迹。","我本开云此山住，偶为名利相萦误。","自负心机四十年，羞闻社客山中篇。","忧时魂梦忆归路，觉来疑在林中眠。","昨日亭前乌鹊喜，果得今朝尔来此。","吾吟行路五十篇，尽说江南数千里。","自怜兄弟今五人，共萦儒素家尚贫。","虽然廪饩各不一，就中总免拘常伦。","长兄年少曾落托，拔劒沙场随卫霍。","口里虽谭周孔文，怀中不舍孙吴略。","次兄一生能苦节，夏聚流萤冬映雪。","非论疾恶志如霜，更觉临泉心似铁。","第三之兄更奇异，昂昂独负青云志。","下看金玉不如泥，肯道王侯身可贵。","却愁清逸不干时，高踪大器无人知。","倘逢感激许然诺，必能万古留清规。","念尔年来方二十，夙夜孜孜能独立。","卷中笔落星汉摇，洞里丹灵鬼神泣。","嗟余流浪心最狂，十年学劒逢时康。","心中不解事拘束，世间谈笑多相妨。","广海青山殊未足，逢著高楼还醉宿。","朝走安公枥上驹，暮伦陶令篱边菊。","近来诗思殊无况，苦被时流不相放。","云腾浪走势未衰，鹤膝蜂腰岂能障。","送尔为文殊不识，贵从一一传胷臆。","若到湖南见紫霄，会须待我同攀陟。"],"theme":"亲情","theme2":["山水田园","边塞征战"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["山","江南","秋","冬","雪","夜"],"cats":{"抒情":["离别","伤感","孤独"],"四季":["秋天","冬天"],"山水":["庐山"],"人生":["励志","梦想","战争"],"生活":["边塞"]},"theme_conf":0.95},{"uid":"32f69392-6fb2-499a-9e8b-55081b5d48e3","title":"七夕","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["今日云𫐌渡鹊桥，应非脉脉与迢迢。","家人竞喜开妆镜，月下穿针拜九霄。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.98},{"uid":"ac1f760e-ae13-4cfd-81c8-23078f643e80","title":"题玉山村叟屋壁","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谷口好泉石，居人能陆沈。","牛羊下山小，烟火隔云深。","一迳入溪色，数家连竹阴。","藏虹辞晚雨，惊隼落残禽。","涉趣皆流目，将归羡在林。","却思黄绶事，辜负紫芝心。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"生活":["乡村"]},"theme_conf":1.0},{"uid":"29818c31-5982-4c9f-8f9a-a227a04ca579","title":"酬信州刘侍郎兄","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["刘兄本知命，屈伸不介怀。","南州管灵山，可惜旷土栖。","樵隐同一径，竹树薄西斋。","鸟陵嶂合杳，月配波徘徊。","薄宦修礼数，长景谢谭谐。","愿为南州民，输税事鉏犁。","胡为走不止，风雨惊邅回。"],"theme":"寄赠酬答","theme2":["民生疾苦","山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雨","月"],"cats":{"生活":["田野"]},"theme_conf":0.92},{"uid":"cfb724d3-b6ef-4c81-a5c7-ef90595445ad","title":"相和歌辞 陇西行","author":"耿[𣲗]","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雪下阳关路，人稀陇戍头。","封狐犹未翦，边将岂无羞。","白草三冬色，黄云万里愁。","因思李都尉，毕竟不封侯。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["冬","雪"],"cats":{"抒情":["伤感"],"四季":["冬天"],"生活":["边塞"]},"theme_conf":0.737},{"uid":"1877173b-b4bb-467b-93da-a390559efe41","title":"留花门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北门天骄子，饱肉气勇决。","高秋马肥健，挟矢射汉月。","自古以为患，诗人厌薄伐。","修德使其来，羁縻固不绝。","胡为倾国至，出入暗金阙。","中原有驱除，隐忍用此物。","公主歌黄鹄，君王指白日。","连云屯左辅，百里见积雪。","长戟鸟休飞，哀笳曙幽咽。","田家最恐惧，麦倒桑枝折。","沙苑临清渭，泉香草丰洁。","渡河不用船，千骑常撇烈。","胡尘逾太行，杂种抵京室。","花门既须留，原野转萧瑟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["花"],"cats":{"抒情":["爱国"],"天气":["写雪"],"生活":["田野"]},"theme_conf":0.443},{"uid":"cp535eb913df2263","title":"洞仙歌","author":"晁补之","dynasty":"宋","section":"宋词","form":"词","paragraphs":["青烟幂处，碧海飞金镜。","永夜闲阶卧桂影。","露凉时、零乱多少寒，神京远，惟有蓝桥路近。","水晶帘不下，云母屏开，冷浸佳人淡脂粉。","待都将许多明，付与金尊，投晓共、流霞倾尽。","更携取、胡床上南楼，看玉做人间，素秋千倾。"],"theme":"游仙梦幻","theme2":["边塞征战"],"style":"冲淡","style2":["绮丽","清新"],"mood":"恬淡","mood2":[],"scene":["夜","秋","楼"],"cats":{"四季":["秋天"],"人物":["女子"],"生活":["写桥"]},"theme_conf":0.547},{"uid":"18734c96-6ba5-4e4d-9150-fa5d31b646d9","title":"晚次新丰北野老家书事呈赠韩质明府","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["机鸣舂响日暾暾，鸡犬相和汉古村。","数派清泉黄菊盛，一林寒露紫棃繁。","衰翁正席矜新社，稚子齐襟读古论。","共说年来但无事，不知何者是君恩。"],"theme":"山水田园","theme2":["山水田园","羁旅思乡"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.68},{"uid":"f3e3dab9-6df9-4bc1-b428-ace90e3a922c","title":"杂曲歌辞 结客少年场行","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长安重游侠，洛阳富才雄。","玉劒浮云骑，金鞍明月弓。","鬬鸡过渭北，走马向关东。","孙宾遥见待，郭解暗相通。","不受千金爵，谁论万里功。","将军下天上，虏骑入云中。","烽火夜似月，兵气晓成虹。","横行徇知己，负羽远从戎。","龙旌昏朔雾，鸟阵卷寒风。","追奔瀚海咽，战罢阴山空。","归来谢天子，何如马上翁。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽","冲淡"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["友情"],"天气":["月亮"],"人生":["青春","战争"],"生活":["边塞"]},"theme_conf":0.711},{"uid":"a8ffe7a3-5f14-43c9-b22e-28eea904da02","title":"天门街西观荣王聘妃","author":"张光朝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙媛来朱邸，名山出紫微。","三周初展义，百两遂言归。","郑国通梁苑，天津接帝畿。","桥成乌鹊助，盖转凤皇飞。","霜仗迎秋色，星缸满夜辉。","从兹磐石固，应为得贤妃。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["泰山"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"3cda5a92-ffa2-4af0-9217-97ce36113705","title":"枫桥夜泊","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["月落乌啼霜满天，江枫渔父对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"生活":["写桥"]},"theme_conf":0.468},{"uid":"6beb5cc2-ae49-4e23-952a-1cb92fa11512","title":"望蓟门","author":"祖咏","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["燕台一望客心惊，箫鼓喧喧汉将营。","万里寒光生积雪，三边曙色动危旌。","沙场烽火连胡月，海畔云山拥蓟城。","少小虽非投笔吏，论功还欲请长缨。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.842},{"uid":"5fe01760-2d47-4df6-b61d-518cf952af9d","title":"相和歌辞 公无渡河","author":"王叡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["浊波洋洋兮凝晓雾，公无渡河兮公苦渡。","风号水激兮呼不闻，提壶看入兮中流去。","浪摆衣裳兮随步没，沈尸深入兮蛟螭窟。","蛟螭尽醉兮君血干，推出黄沙兮泛君骨。","当时君死妾何适？遂就波澜合魂魄。","愿持精卫衔石心，穷取河源塞泉脉。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["酒","塞外"],"cats":{"山水":["江河","黄河"],"生活":["边塞"]},"theme_conf":0.431},{"uid":"94fe7344-b244-4341-8887-e717c373c9a2","title":"杂曲歌辞 少年行三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["莫笑田家老瓦盆，自从盛酒长儿孙。","倾银注瓦惊人眼，共醉终同卧竹根。"],"theme":"山水田园","theme2":["羁旅思乡","闲适隐逸"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"],"生活":["田野"]},"theme_conf":0.394},{"uid":"be5ce2f9-2aaf-40b1-8f05-1a5817447ed3","title":"横吹曲辞 后出塞五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝进东门营，暮上河阳桥。","落日照大旗，马鸣风萧萧。","平沙列万幕，部伍各见招。","中天悬明月，令严夜寂寥。","悲笳数声动，壮士惨不骄。","借问大将谁，恐是霍嫖姚。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂","慷慨"],"scene":["塞外","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"生活":["边塞","写桥"]},"theme_conf":1.0},{"uid":"e8711802-5f93-4354-8422-a634ba2213e4","title":"代村中老人答","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["京洛风尘后，村乡烟火稀。","少年曾失所，衰暮欲何依。","夜静临江哭，天寒踏雪归。","时清应不见，言罢泪盈衣。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["恬淡","愁怨"],"scene":["雪","夜","江"],"cats":{"抒情":["伤感"],"生活":["乡村"]},"theme_conf":0.406},{"uid":"5aee80a3-db54-4787-9e2a-491e108b8f1d","title":"发秦州","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我衰更嬾拙，生事不自谋。","无食问乐土，无衣思南州。","汉源十月交，天气凉如秋。","草木未黄落，况闻山水幽。","栗亭名更佳，下有良田畴。","充肠多薯蓣，崖蜜亦易求。","密竹复冬笋，清池可方舟。","虽伤旅寓远，庶遂平生游。","此邦俯要冲，实恐人事稠。","应接非本性，登临未销忧。","谿谷无异石，塞田始微收。","岂复慰老夫，惘然难久留。","日色隐孤戍，乌啼满城头。","中宵驱车去，饮马寒塘流。","磊落星月高，苍茫云雾浮。","大哉乾坤内，吾道长悠悠。"],"theme":"山水田园","theme2":["边塞征战"],"style":"雄浑","style2":["沉郁"],"mood":"孤寂","mood2":["惆怅"],"scene":["夜","冬","塞外","月","秋","舟"],"cats":{"抒情":["孤独"],"四季":["秋天","冬天"],"生活":["边塞"]},"theme_conf":0.407},{"uid":"2d99b5dd-863a-4b50-ad3d-fe5c9ea8a8d9","title":"送元处士游天台","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青冥路口绝人行，独与僧期上赤城。","树列烟岚春更好，溪藏冰雪夜偏明。","空山雉雊禾苗短，野馆风来竹气清。","若过石桥看瀑布，不妨高处便题名。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","冬","楼","雪","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["瀑布"],"天气":["写雪"],"生活":["写桥"]},"theme_conf":0.458},{"uid":"362e9ec3-e452-4f59-b5f4-10757da34b28","title":"杂曲歌辞 妾薄命","author":"刘元淑","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["自从离别守空闺，遥闻征战起云梯。","夜夜愁君辽海外，年年弃妾渭桥西。","阳春白日照空暖，紫燕衔花向庭满。","彩鸾琴里怨声多，飞鹊镜前妆梳断。","谁家夫壻不从征，应是渔阳别有情。","莫道红颜燕地少，家家还似洛阳城。","且逐新人殊未归，还令秋至夜霜飞。","北斗星前横度鴈，南楼月下捣寒衣。","夜深闻鴈肠欲绝，独坐缝衣灯又灭。","暗啼罗帐空自怜，梦度阳关向谁说。","每怜容貌宛如神，如何薄命不胜人。","愿君朝夕燕山至，好作明年杨柳春。"],"theme":"闺情宫怨","theme2":["送别","边塞征战"],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","秋","鸟","春"],"cats":{"抒情":["离别","伤感","孤独","闺怨"],"四季":["春天","秋天"],"天气":["星星"],"人生":["战争"],"生活":["边塞","写桥"]},"theme_conf":0.354},{"uid":"cp8daaa9d387a076","title":"瑶花慢","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["朱钿宝。","天上飞琼，比人间春别。","江南江北，曾未见，谩拟梨云梅雪。","淮山春晚，问谁识、芳心高洁。","消几番、花落花开，老了玉关豪杰。","金壶翦送琼枝，看一骑红尘，香度瑶阙。","韶华正好，应自喜、初识长安蜂蝶。","杜郎老矣，想旧事、花须能说。","记少年，一梦扬州，二十四桥明月。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","雪","月"],"cats":{"天气":["月亮"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"ea82076e-44f8-4d9c-8844-a2325b642224","title":"题鹤林寺","author":"薛据","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["道门隐形胜，向背临法桥。","松覆山殿冷，花藏溪路遥。","珊珊宝幡挂，燄燄明灯烧。","迟日半空谷，春风连上潮。","少凭水木兴，暂忝身心调。","愿谢携手客，兹山禅侣饶。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["鸟","春","山","江"],"cats":{"四季":["春天"],"人生":["哲理"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":0.533},{"uid":"6eae5ecc-fda0-4ced-ac00-b93e573e381c","title":"观村人牧山田","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["六府且未盈，三农争务作。","贫民乏井税，塉土皆垦凿。","禾黍入寒云，茫茫半山郭。","秋来积霖雨，霜降方铚获。","中田聚黎甿，反景空村落。","顾惭不耕者，微禄同卫鹤。","庶追周任言，敢负谢生诺。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","山","秋"],"cats":{"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.635},{"uid":"11e193d2-f374-43c1-b475-94751f6569b8","title":"田园雨后赠邻人","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["安排常任性，偃卧晚开户。","樵客荷蓑归，向来春山雨。","残云虹未落，返景霞初吐。","时鸟鸣村墟，新泉遶林圃。","尧年尚恬泊，邻里成太古。","室迩人遂遥，相思怨芳杜。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["雨","园林"],"cats":{"抒情":["思念"],"天气":["写雨"],"生活":["田野"]},"theme_conf":0.447},{"uid":"cp9b56c892fca6f8","title":"夜游宫","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["人去西楼雁杳。","叙别梦、扬州一觉。","云澹星疏楚山晓。","听啼乌，立河桥，话未了。","雨外蛩声早。","细织就、霜丝多少。","说与萧娘未知道。","向长安，对秋灯，几人老。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","秋"],"cats":{"四季":["秋天"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"661bab14-62cd-4385-a173-f47e53e6e649","title":"茅堂检校收稻二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["香稻三秋末，平田百顷间。","喜无多屋宇，幸不碍云山。","御裌侵寒气，尝新破旅颜。","红鲜终日有，玉粒未吾悭。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","花","山"],"cats":{"四季":["秋天"],"生活":["田野"]},"theme_conf":0.718},{"uid":"77ae50af-e0a1-44f5-9d40-b319a0549ea5","title":"咏虹","author":"董思恭","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春暮萍生早，日落雨飞余。","横彩分长汉，倒色媚清渠。","梁前朝影出，桥上晚光舒。","愿逐旌旗转，飘飘侍直庐。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春","雨"],"cats":{"四季":["春天"],"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.701},{"uid":"e19062de-ff75-4ab3-b6cc-453f45c32102","title":"赠田家翁","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["老人迎客处，篱落稻畦间。","蚕屋朝寒闭，田家昼雨闲。","门闾新薙草，蹊径旧谙山。","自道谁相及，邀予试徃还。"],"theme":"山水田园","theme2":["民生疾苦","送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","山"],"cats":{"生活":["田野"]},"theme_conf":0.341},{"uid":"250f7cf0-6e19-4bfc-bcc3-96c0c2c67622","title":"寄薛三郎中","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["人生无贤愚，飘飖若埃尘。","自非得神仙，谁免危其身。","与子俱白头，役役常苦辛。","虽为尚书郎，不及村野人。","忆昔村野人，其乐难具陈。","蔼蔼桑麻交，公侯为等伦。","天未厌戎马，我辈本常贫。","子尚客荆州，我亦滞江滨。","峡中一卧病，疟疠终冬春。","春复加肺气，此病盖有因。","早岁与苏郑，痛饮情相亲。","二公化为土，嗜酒不失真。","余今委修短，岂得恨命屯。","闻子心甚壮，所遇信席珍。","上马不用扶，每扶必怒嗔。","赋诗宾客间，挥洒动八垠。","乃知盖代手，才力老益神。","青草洞庭湖，东浮沧海漘。","君山可避暑，况足采白苹。","子岂无扁舟，往复江汉津。","我未下瞿塘，空念禹功勤。","听说松门峡，吐药揽衣巾。","高秋却束带，鼓枻视青旻。","凤池日澄碧，济济多士新。","余病不能起，健者勿逡巡。","上有明哲君，下有行化臣。"],"theme":"寄赠酬答","theme2":["送别","羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["慷慨","相思"],"scene":["江"],"cats":{"抒情":["思念","思乡"],"生活":["乡村"]},"theme_conf":0.95},{"uid":"cp897e2c6cf08579","title":"瑞鹤仙","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晴丝牵绪乱。","对沧江斜日，花飞人远。","垂杨暗吴苑。","正旗亭烟冷，河桥风暖。","兰情蕙盼。","惹相思、春根酒畔。","又争知、吟骨萦销，渐把旧衫重翦。","凄断。","流红千浪，缺月孤楼，总难留燕。","歌尘凝扇。","待凭信，拌分钿。","试挑灯欲写，还依不忍，笺幅偷和泪卷。","寄残云、剩雨蓬莱，也应梦见。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":["愁怨"],"scene":["鸟","楼"],"cats":{"抒情":["思念","伤感"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":0.503},{"uid":"e9a7af99-eb7c-4977-bb08-833c8f32f7f9","title":"早春西湖闲游怅然兴怀忆与微之同赏因思在越官重事殷镜湖之游或恐未暇偶成十八韵寄微之","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["上马复呼宾，湖边景气新。","管弦三数事，骑从十余人。","立换登山屐，行携漉酒巾。","逢花看当妓，遇草坐为茵。","西日笼黄柳，东风荡白苹。","小桥装鴈齿，轻浪甃鱼鳞。","画舫牵徐转，银船酌慢巡。","野情遗世累，醉态任天真。","彼此年将老，平生分最亲。","高天从所愿，远地得为邻。","云树分三驿，烟波限一津。","飜嗟寸步隔，却厌尺书频。","浙右称雄镇，山阴委重臣。","贵垂长紫绶，荣驾大朱轮。","出动刀枪队，归生道路尘。","鴈惊弓易散，鸥怕鼓难驯。","百吏瞻相面，千夫捧拥身。","自然闲兴少，应负镜湖春。"],"theme":"寄赠酬答","theme2":["送别"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":["相思","恬淡"],"scene":["江南","春","江","酒"],"cats":{"抒情":["思念"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"fa2d3278-87d8-4be7-a9be-eaa04c23cd6a","title":"送太仆寺李丞赴都到桃林塞","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远过桃林塞，休年自昔闻。","曲河随暮草，重阜接闲云。","造父为周御，詹嘉守晋军。","应多怀古思，落叶又纷纷。"],"theme":"送别","theme2":["送别"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外"],"cats":{"抒情":["怀古"],"生活":["边塞"],"植物":["桃花"]},"theme_conf":0.85},{"uid":"ea6c5a06-ed63-49f3-82aa-bb7bbded3ee5","title":"鼓吹曲辞 有所思","author":"刘氏云","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朝亦有所思，暮亦有所思。","登楼望君处，蔼蔼浮云飞。","浮云遮却阳关道，向晚谁知妾怀抱。","玉井苍苔春院深，桐花落地无人扫。"],"theme":"边塞征战","theme2":["送别","闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["春","楼","园林"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["写云"],"生活":["边塞"]},"theme_conf":0.38},{"uid":"09788f19-1e11-4394-a543-0edf2cfdcae9","title":"相和歌辞 燕歌行","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汉家烟尘在东北，汉将辞家破残贼。","男儿本自重横行，天子非常赐颜色。","𪭢金伐鼓下榆关，旌旗逶迤碣石间。","校尉羽书飞瀚海，单于猎火照狼山。","山川萧条极边土，胡骑凭凌杂风雨。","战士军前半死生，美人帐下犹歌舞。","大漠穷秋塞草衰，孤城落日鬬兵稀。","身当恩遇常轻敌，力尽关山未解围。","铁衣远戍辛勤久，玉箸应啼别离后。","少妇城南欲断肠，征人蓟北空回首。","边风飘飘那可度，绝域苍茫更何有。","杀气三日作阵云，寒声一夜传刁斗。","相看白刃血纷纷，死节从来岂顾勋。","君不见沙场征战苦，至今犹忆李将军。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨","相思"],"scene":["塞外"],"cats":{"抒情":["离别","思念","伤感","孤独"],"人物":["女子"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.755},{"uid":"0f1e20b5-a8e4-45cd-a1e2-45710eec46fb","title":"横吹曲辞 骢马曲","author":"纪唐天","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["连钱出塞蹋沙蓬，岂比当时御史骢。","逐北自谙深碛路，连嘶谁念静边功。","登山每与青云合，弄影应知碧草同。","今日虏平将换妾，不如罗袖舞春风。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","春","山"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.63},{"uid":"7d4ab8fc-aa99-46f4-8571-54af4d4666bf","title":"咏风","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧条起关塞，摇飏下蓬瀛。","拂林花乱彩，响谷鸟分声。","披云罗影散，泛水织文生。","劳歌大风曲，威加四海清。"],"theme":"咏物","theme2":["边塞征战"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"天气":["写风"],"生活":["边塞"]},"theme_conf":0.475},{"uid":"256d10b8-dba7-466f-8bf9-ba87b8deac72","title":"刈稻了咏怀","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["稻获空云水，川平对石门。","寒风疎落木，旭日散鸡豚。","野哭初闻战，樵歌稍出村。","无家问消息，作客信乾坤。"],"theme":"山水田园","theme2":["咏物"],"style":"幽峭","style2":["沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":[],"cats":{"天气":["太阳"],"生活":["田野"]},"theme_conf":0.531},{"uid":"eaf1094e-b116-4d91-819b-df1a80e1c991","title":"月蚀诗","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["新天子即位五年，岁次庚寅。","斗柄插子，律调黄钟。","森森万木夜僵立，寒气赑屭顽无风。","烂银盘从海底出，出来照我草屋东。","天色绀滑凝不流，冰光交贯寒朣胧。","初疑白莲花，浮出龙王宫。","八月十五夜，比并不可双。","此时怪事发，有物吞食来。","轮如壮士斧斫坏，桂似雪山风拉摧。","百炼镜，照见胆。","平地埋寒灰，火龙珠。","飞出脑，却入蚌蛤胎。","摧环破璧眼看尽，当天一搭如煤炲。","磨踪灭迹须臾间，便似万古不可开。","不料至神物，有此大狼狈。","星如撒沙出，争头事光大。","奴婢炷暗灯，揜菼如玳瑁。","今夜吐燄长如虹，孔隙千道射户外。","玉川子，涕泗下。","中庭独自行，念此日月者。","太阴太阳精，皇天要识物。","日月乃化生，走天汲汲劳四体。","与天作眼行光明，此眼不自保。","天公行道何由行，吾见阴阳家有说。","望日蚀月月光灭，朔月掩日日光缺。","两眼不相攻，此说吾不容。","又孔子师老子云，五色令人目盲。","吾恐天似人，好色即丧明。","幸且非春时，万物不娇荣。","青山破瓦色，绿水冰峥嵘。","花枯无女艳，鸟死沈歌声。","顽冬何所好，偏使一目盲。","传闻古老说，蚀月虾蟇精。","径圆千里入汝腹，汝此痴骸阿谁生。","可从海窟来，便解缘青冥。","恐是眶睫间，揜塞所化成。","黄帝有二目，帝舜重瞳明。","二帝悬四目，四海生光辉。","吾不遇二帝，滉漭不可知。","何故瞳子上，坐受虫豸欺。","长嗟白兔捣灵药，恰似有意防奸非。","药成满臼不中度，委任白兔夫何为。","忆昔尧为天，十日烧九州。","金烁水银流，玉煼丹砂焦。","六合烘为窑，尧心增百忧。","帝见尧心忧，勃然发怒决洪流。","立拟沃杀九日妖，天高日走沃不及。","但见万国赤子𧥄𧥄生鱼头，此时九御导九日。","争持节幡麾幢旒，驾车六九五十四头蛟螭虬。","掣电九火辀，汝若蚀开齱齵轮。","御辔执索相爬钩，推荡轰訇入汝喉。","红鳞燄鸟烧口快，翎鬣倒侧声醆邹。","撑肠拄肚礧傀如山丘，自可饱死更不偷。","不独填饥坑，亦解尧心忧。","恨汝时当食，藏头𢬍脑不肯食。","不当食，张唇哆觜食不休。","食天之眼养逆命，安得上帝请汝刘。","呜呼！人养虎，被虎啮。","天媚蟇，被蟇瞎。","乃知恩非类，一一自作孽。","吾见患眼人，必索良工诀。","想天不异人，爱眼固应一。","安得常娥氏，来习扁鹊术。","手操舂喉戈，去此睛上物。","其初犹朦胧，既久如抹漆。","但恐功业成，便此不吐出。","玉川子又涕泗下，心祷再拜额榻砂土中。","地上虮虱臣仝告愬帝天皇，臣心有铁一寸。","可刳妖蟇痴肠，上天不为臣立梯磴。","臣血肉身，无由飞上天。","扬天光，封词付与小心风。","𩙥排阊阖入紫宫，密迩玉几前擘坼。","奏上臣仝顽愚胸，敢死横干天。","代天谋其长，东方苍龙角。","插戟尾捭风，当心开明堂。","统领三百六十鳞虫，坐理东方宫。","月蚀不救援，安用东方龙。","南方火鸟赤泼血，项长尾短飞跋躠。","头戴井冠高逵枿，月蚀鸟宫十三度。","鸟为居停主人不觉察，贪向何人家。","行赤口毒舌，毒虫头上吃却月。","不啄杀，虚眨鬼眼明䆕䆷。","鸟罪不可雪，西方攫虎立踦踦。","斧为牙，凿为齿。","偷牺牲，食封豕。","大蟇一脔，固当软美。","见似不见，是何道理。","爪牙根天不念天，天若准拟错准拟。","北方寒龟被虵缚，藏头入壳如入狱。","虵筋束紧束破壳，寒龟夏鼈一种味。","且当以其肉充臛，死壳没信处。","唯堪支床脚不堪钻灼与天卜，岁星主福德。","官爵奉董秦，忍使黔娄生。","覆尸无衣巾，天失眼不吊。","岁星胡其仁，荧惑矍铄翁。","执法大不中，月明无罪过。","不纠蚀月虫，年年十月朝太微。","支卢谪罚何灾凶，土星与土性相背。","反养福德生祸害，到人头上死破败。","今夜月蚀安可会，太白真将军。","怒激锋铓生，恒州阵斩郦定进。","项骨脃甚春蔓菁，天唯两眼失一眼。","将军何处行天兵，辰星任廷尉。","天律自主持，人命在盆底。","固应乐见天盲时，天若不肯信。","试唤臯陶鬼一问，一如今日。","三台文昌宫，作上天纪纲。","环天二十八宿，磊磊尚书郎。","整顿排班行，劒握他人将。","一四太阳侧，一四天市傍。","操斧代大匠，两手不怕伤。","弧矢引满反射人，天狼呀啄明煌煌。","痴牛与𫘤女，不肯勤农桑。","徒劳含淫思，旦夕遥相望。","蚩尤簸旗弄旬朔，始搥天鼓鸣珰琅。","枉矢能蛇行，眊目森森张。","天狗下舐地，血流何滂滂。","谲险万万党，架搆何可当。","眯目衅成就，害我光明王。","请留北斗一星相北极，指麾万国悬中央。","此外尽扫除，堆积如山冈。","赎我父母光，当时常星没。","殒雨如迸浆，似天会事发。","叱喝诛奸强，何故中道废。","自遗今日殃，善善又恶恶。","郭公所以亡，愿天神圣心。","无信他人忠，玉川子词讫。","风色紧格格，近月黑暗边。","有似动劒戟，须臾痴蟇精。","两吻自决坼，初露半个璧。","渐吐满轮魄，众星尽原赦。","一蟇独诛磔，腹肚忽脱落。","依旧挂穹碧，光彩未苏来。","惨澹一片白，奈何万里光。","受此吞吐厄，再得见天眼。","感荷天地力，或问玉川子。","孔子修春秋，二百四十年。","月蚀尽不收，今子咄咄词。","颇合孔意不，玉川子笑荅。","或请听逗留，孔子父母鲁。","讳鲁不讳周，书外书大恶。","故月蚀不见收，予命唐天。","口食唐土，唐礼过三。","唐乐过五，小犹不说。","大不可数，灾沴无有小大瘉。","安得引衰周，研核其可否。","日分昼，月分夜。","辨寒暑，一主刑。","二主德，政乃举。","孰为人面上，一目偏可去。","愿天完两目，照下万方土。","万古更不瞽，万万古。","更不瞽，照万古。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["幽峭","豪放"],"mood":"相思","mood2":["欢愉","愁怨"],"scene":["月","夏","冬"],"cats":{"抒情":["思念","伤感"],"四季":["夏天","冬天"],"天气":["月亮","星星"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.423},{"uid":"cpee91838ef68a70","title":"玉楼春","author":"刘克庄","dynasty":"宋","section":"宋词","form":"词","paragraphs":["年年跃马长安市。","客舍似家家似寄。","青钱换酒日无何，红烛呼庐宵不寐。","易挑锦妇机中字。","难得玉人心下事。","男儿西北有神州，莫滴水西桥畔泪。"],"theme":"羁旅思乡","theme2":["送别"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","春","楼"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.535},{"uid":"f69bfe05-49ed-4c28-9f39-6aaae0e2aa74","title":"除草","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["草有害于人，曾何生阻修。","其毒甚蜂虿，其多弥道周。","清晨步前林，江色未散忧。","芒刺在我眼，焉能待高秋。","霜露一沾凝，蕙叶亦难留。","荷锄先童穉，日入仍讨求。","转致水中央，岂无双钓舟。","顽根易滋蔓，敢使依旧丘。","自兹藩篱旷，更觉松竹幽。","芟夷不可阙，疾恶信如雠。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","舟"],"cats":{"四季":["秋天"],"生活":["田野"]},"theme_conf":0.762},{"uid":"5cee205e-5c59-46e5-b060-9b0916c64a3f","title":"忆昔二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔先皇巡朔方，千乘万骑入咸阳。","阴山骄子汗血马，长驱东胡胡走藏。","邺城反复不足怪，关中小儿坏纪纲，张后不乐上为忙。","至今今上犹拨乱，劳身焦思补四方。","我昔近侍叨奉引，出兵整肃不可当。","为留猛士守未央，致使岐雍防西羌。","犬戎直来坐御床，百官跣足随天王愿见北地傅介子，老儒不用尚书郎。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"e7abc715-139b-4987-b57d-c7dacdd8fe6b","title":"相和歌辞 陌上桑","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["美女渭桥东，春还事蚕作。","五马如飞龙，青丝结金络。","不知谁家子，调笑来相谑。","妾本秦罗敷，玉颜艳名都。","绿条映素手，采桑向城隅。","使君且不顾，况复论秋胡。","寒螀爱碧草，鸣凤栖青梧。","托心自有处，但怪傍人愚。","徒令白日暮，高驾空踟蹰。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"欢愉","mood2":["孤寂"],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"生活":["写桥"]},"theme_conf":0.41},{"uid":"19afaf8e-aaa5-4a06-9e92-5fc4cdecb40c","title":"相和歌辞 公无渡河","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["黄河怒浪连天来，大响谹谹如殷雷。","龙伯驱风不敢上，百川喷雪高崔嵬。","二十五弦何太哀？请公勿渡立裴回。","下有狂蛟锯为尾，裂帆截櫂磨霜齿。","神锥凿石塞神潭，白马𫎺𧽼赤尘起。","公乎跃马扬玉鞭，灭没高蹄日千里。"],"theme":"咏物","theme2":["边塞征战"],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["江","塞外","雪","山","舟"],"cats":{"山水":["江河","黄河"],"生活":["边塞"]},"theme_conf":0.533},{"uid":"de9b3a1a-925d-445a-9e23-d03b0f64d388","title":"横吹曲辞 出塞曲 二","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉帐将军意，慇懃把酒论。","功高宁在我，阵没与招魂。","塞色干戈束，军容喜气屯。","男儿今始是，敢出玉关门。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.867},{"uid":"a9b677e8-2657-4d20-9572-1a7479846124","title":"送女子","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["青娥宛宛聚为裳，乌鹊桥成别恨长。","惆怅梧桐非旧影，不悲鸿鴈暂随阳。"],"theme":"送别","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"惆怅","mood2":["悲怆","愁怨"],"scene":["七夕"],"cats":{"抒情":["伤感"],"人物":["女子"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"8558df16-4368-4416-9be3-fcc3350284f6","title":"南溪春耕","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["荷蓑趣南迳，戴胜鸣条枚。","溪雨有余润，土膏宁厌开。","沟塍落花尽，耒耜度云回。","谁道耦耕倦，仍兼胜赏催。","日长农有暇，悔不带经来。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"生活":["田野"]},"theme_conf":1.0},{"uid":"39a18f10-005c-4200-ba56-70b7e35adea4","title":"题叶道士山房","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["水边垂柳赤栏桥，洞里仙人碧玉箫。","近得麻姑音信否，浔阳江上不通潮。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","山"],"cats":{"生活":["写桥"],"植物":["叶子"]},"theme_conf":0.52},{"uid":"cf854c36-62d7-4c54-ad3f-258cfedbb14a","title":"题郑十八著作虔","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["台州地阔海冥冥，云水长和岛屿青。","乱后故人双别泪，春深逐客一浮萍。","酒酣嬾舞谁相拽，诗罢能吟不复听。","第五桥东流恨水，皇陂岸北结愁亭。","贾生对𫛳伤王傅，苏武看羊陷贼庭。","可念此翁怀直道，也沾新国用轻刑。","祢衡实恐遭江夏，方朔虚传是岁星。","穷巷悄然车马绝，案头干死读书萤。"],"theme":"送别","theme2":["咏物"],"style":"沉郁","style2":["豪放","婉约"],"mood":"愁怨","mood2":[],"scene":["楼","夏","春","酒"],"cats":{"抒情":["友情","伤感"],"四季":["春天","夏天"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.53},{"uid":"da42362f-b22f-4ca6-a18e-69284623c195","title":"横吹曲辞 关山月","author":"长孙佐辅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凄凄还切切，戍客多离别。","何处最伤心？关山见秋月。","关月竟如何？由来远近过。","始经玄兔塞，终绕白狼河。","忽忆秦楼妇，流光应共有。","已得竝蛾眉，还知揽纤手。","去岁照同行，比翼复连形。","今宵照独立，顾影自茕茕。","余晖渐西落，夜夜看如昨。","借问映旌旗，何如鉴帷幕。","拂晓朔风悲，蓬惊雁不飞。","几时征戍罢，还向月中归。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["塞外","月","山"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"天气":["写风","月亮"],"生活":["边塞"]},"theme_conf":0.403},{"uid":"cp99f30691ef4ed8","title":"汉宫春","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春已归来，看美人头上，袅袅春幡。","无端风雨，未肯收尽馀寒。","年时燕子，料今宵、梦到西园。","浑未办、黄柑荐酒，更传青韭堆盘。","却笑东风从此，便薰梅染柳，更没些闲。","闲时又来镜里，转变朱颜。","清愁不断，问何人、会解连环。","生怕见、花开花落，朝来塞雁先还。"],"theme":"节令风俗","theme2":["闲适隐逸","边塞征战"],"style":"清新","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人物":["女子"],"生活":["边塞"]},"theme_conf":0.85},{"uid":"057c887c-9525-4a2e-b553-23d5afab9275","title":"病马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乘尔亦已久，天寒关塞深。","尘中老尽力，岁晚病伤心。","毛骨岂殊众，驯良犹至今。","物微意不浅，感动一沈吟。"],"theme":"咏物","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"],"动物":["写马"]},"theme_conf":0.621},{"uid":"c9dd1e11-5396-498a-a228-9afeb720dc41","title":"春日江村五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢递来三蜀，蹉跎有六年。","客身逢故旧，发兴自林泉。","过懒从衣结，频游任履穿。","藩篱无限景，恣意买江天。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"17c5283a-e49e-45e5-afa6-49c2084d50ee","title":"游烂柯山四首 二","author":"李幼卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["巨石何崔嵬，横桥架山顶。","傍通日月过，仰望虹霓迥。","圣者开津梁，谁能度兹岭。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["彩虹"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"4a648ac2-fe66-438d-b082-2da34f651fe6","title":"晚到盩厔耆老家","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["老翁曾旧识，相引出柴门。","苦话别时事，因寻溪上村。","数年何处客，近日几家存。","冒雨看禾黍，逢人忆子孙。","乱藤穿井口，流水到篱根。","惆怅不堪住，空山月又昏。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["相思"],"scene":["雨","月","山"],"cats":{"抒情":["思念"],"生活":["乡村"]},"theme_conf":0.615},{"uid":"2d0385e7-0c72-423f-a538-f66acc9d4c46","title":"横吹曲辞 出塞 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["塞外","山","月"],"cats":{"天气":["月亮"],"生活":["边塞"]},"theme_conf":0.776},{"uid":"013587ae-016b-4a6c-be0c-806ac0bc7a12","title":"村雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雨声传两夜，寒事飒高秋。","挈带看朱绂，开箱覩黑裘。","世情只益睡，盗贼敢忘忧。","松菊新沾洗，茅齐慰远游。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["雨"],"cats":{"天气":["写雨"],"生活":["乡村"]},"theme_conf":0.711},{"uid":"59e2fe4b-c925-4b3e-851d-e1c355c43b98","title":"关山月","author":"鲍氏君徽","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高高秋月明，北照辽阳城。","塞迥光初满，风多晕更生。","征人望乡思，战马闻鼙惊。","朔风悲边草，胡沙暗虏营。","霜凝匣中劒，风惫原上旌。","早晚谒金阙，不闻刁斗声。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["相思"],"scene":["塞外","月","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写风","月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.595},{"uid":"efb2f4fe-cbfc-424a-9980-7015cd556941","title":"宋中遇陈二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常忝鲍叔义，所期王佐才。","如何守苦节，独此无良媒。","离别十年外，飘飖千里来。","安知罢官后，惟见柴门开。","穷巷隐东郭，高堂咏南陔。","篱根长花草，井上生莓苔。","伊昔望霄汉，于今倦蒿莱。","男儿命未达，且尽手中桮。"],"theme":"送别","theme2":["山水田园"],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["离别","孤独"],"生活":["乡村"]},"theme_conf":0.434},{"uid":"86952cb3-b622-4398-a56a-01dd39f6c6ec","title":"帝京篇十首 五","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["芳辰追逸趣，禁苑信多奇。","桥形通汉上，峰势接云危。","烟霞交隐映，花鸟自参差。","何如肆辙迹？万里赏瑶池。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["花","山"],"cats":{"生活":["写桥"]},"theme_conf":1.0},{"uid":"3b847cf5-16b1-449d-a436-e5995c6433c4","title":"桃源行","author":"王维","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["渔舟逐水爱山春，两岸桃花夹去津。","坐看红树不知远，行尽青溪不见人。","山口潜行始隈隩，山开旷望旋平陆。","遥看一处攒云树，近入千家散花竹。","樵客初传汉姓名，居人未改秦衣服。","居人共住武陵源，还从物外起田园。","月明松下房栊静，日出云中鸡犬喧。","惊闻俗客争来集，竞引还家问都邑。","平明闾巷埽花开，薄暮渔樵乘水入。","初因避地去人间，及至成仙遂不还。","峡里谁知有人事，世中遥望空云山。","不疑灵境难闻见，尘心未尽思乡县。","出洞无论隔山水，辞家终拟长游衍。","自谓经过旧不迷，安知峰壑今来变。","当时只记入山深，青溪几曲到云林。","春来遍是桃花水，不辨仙源何处寻。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","孤寂"],"scene":["山"],"cats":{"抒情":["思念","思乡"],"生活":["田野"],"植物":["桃花"]},"theme_conf":0.687},{"uid":"d8ff176a-ba69-4277-a54e-9e515bc19304","title":"相和歌辞 雁门太守行","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["黑云压城城欲摧，甲光向月金鳞开。","角声满天秋色里，塞上燕支凝夜紫。","半卷红旗临易水，霜重鼓寒声不起。","报君黄金台上意，提携玉龙为君死。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟","秋"],"cats":{"四季":["秋天"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.658},{"uid":"6c71ef5d-2b99-4ece-b3db-deefc25bc346","title":"途中立春寄杨郇伯","author":"窦常","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["浪迹终年客，惊心此地春。","风前独去马，泽畔耦耕人。","老大交情重，悲凉外物亲。","子云今在宅，应见柳条新。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.88},{"uid":"cp168ce1c08d4007","title":"凤凰台上忆吹箫","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["香冷金猊，被翻红浪，起来人未梳头。","任宝奁闲掩，日上帘钩。","生怕闲愁暗恨，多少事、欲说还休。","今年瘦，非干病酒，不是悲秋。","明朝，这回去也，千万遍阳关，也即难留。","念武陵春晚，云锁重楼。","记取楼前绿水，应念我、终日凝眸。","凝眸处，从今更数，几段新愁。"],"theme":"送别","theme2":["边塞征战"],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":["相思"],"scene":["楼"],"cats":{"抒情":["思念","伤感"],"生活":["边塞"]},"theme_conf":0.7},{"uid":"5f444f7d-1c9a-42c5-a2dd-1dda1aac432a","title":"望送魏征葬","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阊阖总金鞍，上林移玉辇。","野郊怆新别，河桥非旧饯。","惨日映峰沈，愁云随盖转。","哀笳时断续，悲旌乍舒卷。","望望情何极，浪浪泪空泫。","无复昔时人，芳春共谁遣。"],"theme":"送别","theme2":[],"style":"悲慨","style2":["沉郁","绮丽"],"mood":"悲怆","mood2":["愁怨","相思"],"scene":["春","山"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"8bc003c1-d2d3-4708-b014-7048cda8846b","title":"暝投云智寺渡溪不得却取沿江路往","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["双嵓泻一川，回马断桥前。","古庙阴风地，寒钟暮雨天。","沙虚留虎迹，水滑带龙涎。","却下临江路，潮深无渡船。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河","西湖"],"生活":["写桥"]},"theme_conf":0.632},{"uid":"cp953a252ee8aa8a","title":"菩萨蛮","author":"陈克","dynasty":"宋","section":"宋词","form":"词","paragraphs":["赤阑桥尽香街直。","笼街细柳娇无力。","金碧上青空。","花晴帘影红。","黄衫飞白马。","日日青楼下。","醉眼不逢人。","午香吹暗尘。"],"theme":"咏怀抒感","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","楼"],"cats":{"生活":["写桥"]},"theme_conf":0.62},{"uid":"22063a2e-01e8-4550-ade4-56e43fe96672","title":"春日江村五首 四","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["扶病垂朱绂，归休步紫苔。","郊扉存晚计，幕府媿群材。","燕外晴丝卷，鸥边水叶开。","隣家送鱼鼈，问我数能来。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":0.709},{"uid":"c1b6399b-c2e2-4a61-8d15-b3362da6d6b0","title":"题灵台县东山村主人","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["处处征胡人渐稀，山村寥落暮烟微。","门临莽苍经年闭，身逐嫖姚几日归。","贫妻白发输残税，余寇黄河未解围。","天子如今能用武，祗应岁晚息兵机。"],"theme":"山水田园","theme2":["边塞征战"],"style":"雄浑","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["山","江"],"cats":{"山水":["黄河"],"生活":["乡村"]},"theme_conf":0.356},{"uid":"cd66d8b3-abe6-4316-ab34-b88a4bb8bb83","title":"杂曲歌辞 北风行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["烛龙栖寒门，光曜犹旦开。","日月照之何不及此，惟有北风怒号天上来。","燕山雪花大如席，片片吹落轩辕台。","幽州思妇十二月，停歌罢笑双蛾摧。","倚门望行人，念君长城苦寒良可哀。","别时提劒救边去，遗此虎文金髀钗。","中有一双白羽箭，蜘蛛结网生尘埃。","箭空在，人今战死不复回。","不忍见此物，焚之已成灰。","黄河捧土尚可塞，北风雨雪恨难裁。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["雪","冬","雨"],"cats":{"抒情":["闺怨"],"山水":["黄河"],"天气":["写风"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.317},{"uid":"8fc37ad3-7f3b-466e-aad1-e00a080fdf1d","title":"睢阳酬别畅大判官","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾友遇知己，策名逢圣朝。","高才擅白雪，逸翰怀青霄。","承诏选嘉宾，慨然即驰轺。","清昼下公馆，尺书忽相邀。","留欢惜别离，毕景驻行镳。","言及沙漠事，益令胡马骄。","丈夫拔东蕃，声冠霍嫖姚。","兜鍪冲矢石，铁甲生风飙。","诸将出冷陉，连营济石桥。","酋豪尽俘馘，子弟输征徭。","边庭绝刁斗，战地成渔樵。","榆关夜不扃，塞口长萧萧。","降胡满蓟门，一一能射雕。","军中多宴乐，马上何轻趫。","戎狄本无厌，羇縻非一朝。","饥附诚足用，饱飞安可招。","李牧制儋蓝，遗风岂寂寥。","君还谢幕府，慎勿轻刍荛。"],"theme":"送别","theme2":["边塞征战"],"style":"豪放","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["塞外"],"cats":{"抒情":["友情","离别"],"人生":["战争"],"生活":["边塞","写桥"]},"theme_conf":0.421},{"uid":"c9362aba-fb50-481b-a4cd-08ddd65cdd2a","title":"梦李白二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["死别已吞声，生别常恻恻。","江南瘴疠地，逐客无消息。","故人入我梦，明我长相忆。","恐非平生魂，路远不可测。","魂来枫叶青，魂返关塞黑。","君今在罗网，何以有羽翼。","落月满屋梁，犹疑照颜色。","水深波浪阔，无使蛟龙得。"],"theme":"寄赠酬答","theme2":["游仙梦幻","羁旅思乡","边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江南","塞外","月"],"cats":{"抒情":["友情","思念","思乡"],"人生":["梦想"],"生活":["边塞"]},"theme_conf":0.75},{"uid":"954bc2e7-212b-4af0-afc2-f9230822a784","title":"送孙泼赴云中","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["黄骢少年舞双戟，目视旁人皆辟易。","百战能夸陇上儿，一身复作云中客。","寒风动地气苍茫，横吹先悲出塞长。","敲石军中传夜火，斧冰河畔汲朝浆。","前锋直指阴山外，虏骑纷纷胆应碎。","匈奴破尽人看归，金印酬功如斗大。"],"theme":"送别","theme2":["边塞征战"],"style":"雄浑","style2":["悲慨","幽峭"],"mood":"悲怆","mood2":[],"scene":["塞外","夜"],"cats":{"抒情":["伤感"],"天气":["写云"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.479},{"uid":"f2df70bb-0958-4bc6-bef3-593eae26d678","title":"田家秋日送友","author":"于良史","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["苍茫日初宴，遥野云初收。","残雨北山里，夕阳东渡头。","舟依渔溓合，水入田家流。","何意君迷驾，山林应有秋。"],"theme":"山水田园","theme2":["送别"],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["太阳"],"生活":["田野"]},"theme_conf":0.412},{"uid":"cpace79dfe6e198c","title":"踏莎行","author":"欧阳修","dynasty":"宋","section":"宋词","form":"词","paragraphs":["候馆梅残，溪桥柳细。","草熏风暖摇征辔。","离愁渐远渐无穷，迢迢不断如春水。","寸寸柔肠，盈盈粉泪。","楼高莫近危阑倚。","平芜尽处是春山，行人更在春山外。"],"theme":"山水田园","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","山","楼"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.6},{"uid":"e4a02904-d561-4be5-9d9a-296456744bcf","title":"石桥","author":"信安王祎","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别有经行所，迥跨重峦侧。","粤因求瘼余，倏想寻真域。","放情恣披拂，杖策聊□□。","□□□□□，□□□□色。","乱幡雾中见，雁塔云间识。","薄烟幂远郊，遥峰没归翼。","仙桥危石架，幽洞乘□□。","□□□□□，□□□易测。","二教无先后，一相平而直。","冀兹捐俗心，永怀依妙力。"],"theme":"送别","theme2":[],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"生活":["写桥"]},"theme_conf":1.0},{"uid":"cp66426d06db2e64","title":"夜合花","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳暝河桥，莺晴台苑，短策频惹春香。","当时夜泊，温柔便入深乡。","词韵窄，酒杯长。","翦蜡花、壶箭催忙。","共追游处，凌波翠陌，连棹横塘。","十年一梦凄凉。","似西湖燕去，吴馆巢荒。","重来万感，依前唤酒银罂。","溪雨急，岸花狂。","趁残鸦、飞过苍茫。","故人楼上，凭谁指与，芳草斜阳。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":["雄浑","豪放"],"mood":"愁怨","mood2":[],"scene":["花","酒","夜","鸟","江南","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.558},{"uid":"c8210485-a1f4-4c76-a1f6-2f5e57d39d29","title":"和张仆射塞下曲","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["月黑雁飞高，单于夜遁逃。","欲将轻骑逐，大雪满弓刀。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","塞外"],"cats":{"生活":["边塞"]},"theme_conf":0.867},{"uid":"2065dc7a-5ac9-406f-b7cd-285c5b5293df","title":"晚渡渭桥寄示京邑游好","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我行背城阙，驱马独悠悠。","寥落百年事，裴回万里忧。","途遥日向夕，时晚鬓将秋。","滔滔俯东逝，耿耿泣西浮。","长虹掩钓浦，落雁下星洲。","草变黄山曲，花飞清渭流。","迸水惊愁鹭，腾沙起狎鸥。","一赴清泥道，空思玄灞游。"],"theme":"山水田园","theme2":["送别"],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["伤感","孤独"],"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.501},{"uid":"cpa94a5ad72e936a","title":"唐多令","author":"刘过","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芦叶满汀洲。","塞沙带浅流。","二十年、重过南楼。","柳下系舟犹未稳，能几日、又中秋。","黄鹤断矶头。","故人今不在。","旧江山，浑是新愁。","欲买桂花同载酒，终不似、少年游。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"雄浑","style2":[],"mood":"愁怨","mood2":[],"scene":["江","中秋"],"cats":{"抒情":["伤感","怀古"],"生活":["边塞"],"节日":["中秋节"]},"theme_conf":0.64},{"uid":"01d2faf1-f9c9-4fc3-bc7b-9b1e72d59f2d","title":"七夕二首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["河鼓灵旗动，嫦娥破镜斜。","满空天是幕，徐转斗为车。","机罢犹安石，桥成不碍槎。","谁知观津女，竟夕望云涯。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"1f28ab03-8388-4a2f-8c4f-3ce47789e221","title":"桃花谿","author":"张旭","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["隐隐飞桥隔野烟，石矶西畔问渔船。","桃花尽日随流水，洞在清谿何处边。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["花"],"cats":{"生活":["写桥"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"cp870b6030df582d","title":"高阳台","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["接叶巢莺，平波卷絮，断桥斜日归船。","能几番游，看花又是明年。","东风且伴蔷薇住，到蔷薇、春已堪怜。","更凄然。","万绿西泠，一抹荒烟。","当年燕子知何处，但苔深韦曲，草暗斜川。","见说新愁，如今也到鸥边。","无心再续笙歌梦，掩重门、浅醉闲眠。","莫开帘。","怕见飞花，怕听啼鹃。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["春","鸟"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.82},{"uid":"c0f731fe-706b-4e7e-a27c-db14c06686e9","title":"相和歌辞 江南曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江南人家多橘树，吴姬舟上织白纻。","土地卑湿饶虫蛇，连木为牌入江住。","江村亥日长为市，落帆渡桥来浦里。","青莎覆城竹为屋，无井家家饮潮水。","长江午日酤春酒，高高酒旗悬江口。","倡楼两岸悬水栅，夜唱竹枝留北客。","江南风土欢乐多，悠悠处处尽经过。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江","江南"],"cats":{"抒情":["思乡"],"山水":["江河","长江"],"生活":["写桥"]},"theme_conf":0.604},{"uid":"cp334c6d9b3adb62","title":"月下笛","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["万里孤云，清游渐远，故人何处。","寒窗梦里，犹记经行旧时路。","连昌约略无多柳，第一是、难听夜雨。","谩惊回凄悄，相看烛影，拥衾谁语。","张绪。","归何暮。","半零落，依依断桥鸥鹭。","天涯倦旅。","此时心事良苦。","只愁重洒西州泪，问杜曲、人家在否。","恐翠袖、正天寒，犹倚梅花那树。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","伤感","怀古"],"山水":["西湖"],"天气":["月亮"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.416},{"uid":"cpbe9192b90bad20","title":"尉迟杯","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["隋堤路。","渐日晚、密霭生深树。","阴阴淡月笼沙，还宿河桥深处。","无情画舸，都不管、烟波隔南浦。","等行人、醉拥重衾，载将离恨归去。","因念旧客京华，长偎傍、疏林小槛欢聚。","冶叶倡条俱相识，仍惯见、珠歌翠舞。","如今向、渔村水驿，夜如岁、焚香独自语。","有何人、念我无，梦魂凝想鸳侣。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"绮丽","style2":["冲淡"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["酒"],"cats":{"抒情":["离别","思乡","孤独"],"生活":["写桥"],"食物":["写酒"]},"theme_conf":0.361},{"uid":"601b5495-9683-460a-9ef7-f27c3965cef1","title":"江上田家","author":"包何","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["近海川原薄，人家本自稀。","黍苗期腊酒，霜叶是寒衣。","市井谁相识，渔樵夜始归。","不须骑马问，恐畏狎鸥飞。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["江","酒","夜"],"cats":{"生活":["田野"]},"theme_conf":0.579},{"uid":"3d2b033b-eceb-4425-a345-7116bcdb2f5a","title":"春日江村五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["农务村村急，春流岸岸深。","乾坤万里眼，时序百年心。","茅屋还堪赋，桃源自可寻。","艰难贱生理，飘泊到如今。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"b3e2191a-e121-4ddc-a90c-f39467dabf75","title":"郊庙歌辞 享章怀太子庙乐章 武舞作","author":"不详","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绿林炽炎历，黄虞格有苗。","沙尘惊塞外，帷幄命嫖姚。","七德干戈止，三边云雾消。","宝祚长无极，歌舞盛今朝。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","夏"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"a3aec75e-d67c-4a40-920a-c3ccbac03993","title":"秋日夔府咏怀奉寄郑监李宾客一百韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绝塞乌蛮北，孤城白帝边。","飘零仍百里，消渴已三年。","雄劒鸣开匣，群书满系船。","乱离心不展，衰谢日萧然。","筋力妻孥问，菁华岁月迁。","登临多物色，陶冶赖诗篇。","峡束沧江起，岩排石树圆。","拂云霾楚气，朝海蹴吴天。","煮井为盐速，烧畬度地偏。","有时惊叠嶂，何处觅平川。","㶉𫛶双双舞，猕猿垒垒悬。","碧萝长似带，锦石小如钱。","春草何曾歇，寒花亦可怜。","猎人吹戍火，野店引山泉。","唤起搔头急，扶行几屐穿。","两京犹薄产，四海绝随肩。","幕府初交辟，郎官幸备员。","瓜时犹旅寓，萍泛苦夤缘。","药饵虚狼藉，秋风洒静便。","开襟驱瘴疠，明目扫云烟。","高宴诸侯礼，佳人上客前。","哀筝伤老大，华屋艳神仙。","南内开元曲，常时弟子传。","法歌声变转，满座涕潺湲。","吊影夔州僻，回肠杜曲煎。","即今龙厩水，莫带犬戎膻。","耿贾扶王室，萧曹拱御筵。","乘威灭蜂虿，戮力効鹰鹯。","旧物森犹在，凶徒恶未悛。","国须行战伐，人忆止戈鋋。","奴仆何知礼，恩荣错与权。","胡星一彗孛，黔首逐拘挛。","哀痛丝纶切，烦苛法令蠲。","业成陈始王，兆喜出于畋。","宫禁经纶密，台阶翊戴全。","熊罴载吕望，鸿雁美周宣。","侧听中兴主，长吟不世贤。","音徽一柱数，道里下牢千。","郑李光时论，文章并我先。","阴何尚清省，沈宋歘联翩。","律比昆仑竹，音知燥湿弦。","风流俱善价，惬当久忘筌。","置驿常如此，登龙盖有焉。","虽云隔礼数，不敢坠周旋。","高视收人表，虚心味道玄。","马来皆汗血，鹤唳必青田。","羽翼商山起，蓬莱汉阁连。","管宁纱帽净，江令锦袍鲜。","东郡时题壁，南湖日扣舷。","远游凌绝境，佳句染华牋。","每欲孤飞去，徒为百虑牵。","生涯已寥落，国步乃迍邅。","衾枕成芜没，池塘作弃捐。","别离忧怛怛，伏腊涕涟涟。","露菊班丰镐，秋蔬影涧瀍。","共谁论昔事，几处有新阡。","富贵空回首，喧争嬾著鞭。","兵戈尘漠漠，江汉月娟娟。","局促看秋燕，萧疎听晚蝉。","雕虫蒙记忆，烹鲤问沈绵。","卜羡君平杖，偷存子敬毡。","囊虚把钗钏，米尽坼花钿。","甘子阴凉叶，茅斋八九椽。","阵图沙北岸，市暨瀼西巅。","羁绊心常折，栖迟病即痊。","紫收岷岭芋，白种陆池莲。","色好梨胜颊，穰多栗过拳。","勅厨唯一味，求饱或三鳣。","儿去看鱼笱，人来坐马鞯。","缚柴门窄窄，通竹溜涓涓。","堑抵公畦棱，村依野庙壖。","缺篱将棘拒，倒石赖藤缠。","借问频朝谒，何如稳醉眠。","谁云行不逮，自觉坐能坚。","雾雨银章涩，馨香粉署妍。","紫鸾无近远，黄雀任翩翾。","困学违从众，明公各勉旃。","声华夹宸极，早晚到星躔。","恳谏留匡鼎，诸儒引服虔。","不逢输鲠直，会是正陶甄。","宵旰忧虞轸，黎元疾苦骈。","云台终日画，青简为谁编。","行路难何有，招寻兴已专。","由来具飞檝，𫏐拟控鸣弦。","身许双峰寺，门求七祖禅。","落帆追宿昔，衣褐向真诠。","安石名高晋，昭王客赴燕。","途中非阮籍，查上似张骞。","披拂云宁在，淹留景不延。","风期终破浪，水怪莫飞涎。","他日辞神女，伤春怯杜鹃。","淡交随聚散，泽国绕回旋。","本自依迦叶，何曾藉偓佺。","𬬻峰生转盻，橘井尚高褰。","东走穷归鹤，南征尽跕鸢。","晚闻多妙教，卒践塞前愆。","顾凯丹青列，头陀琬琰镌。","众香深黯黯，几地肃芊芊。","勇猛为心极，清羸任体孱。","金蓖空刮眼，镜象未离铨。"],"theme":"寄赠酬答","theme2":["山水田园","边塞征战","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"欢愉","mood2":["恬淡","孤寂"],"scene":["秋","山","鸟","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["女子"],"人生":["励志","战争"],"生活":["乡村","边塞"]},"theme_conf":0.95},{"uid":"874a0ca3-62ca-4c9f-976b-895b035ac3d6","title":"边城落日","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["紫塞流沙北，黄图灞水东。","一朝辞俎豆，万里逐沙蓬。","候月恒持满，寻源屡凿空。","野昏边气合，烽迥戍烟通。","膂力风尘倦，疆场岁月穷。","河流控积石，山路远崆峒。","壮志凌苍兕，精诚贯白虹。","君恩如可报，龙剑有雌雄。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["冲淡"],"mood":"慷慨","mood2":[],"scene":["塞外","月"],"cats":{"天气":["太阳"],"人生":["励志","梦想"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"cpfefb3d1fd306d5","title":"惜黄花慢","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["送客吴皋。","正试霜夜冷，枫落长桥。","望天不尽，背城渐杳，离亭黯黯，恨水迢迢。","翠香零落红衣老，暮愁锁、残柳眉梢。","念瘦腰。","沈郎旧日，曾系兰桡。","仙人凤咽琼箫。","怅断魂送远，九辨难招。","醉鬟留盼，小窗翦烛，歌云载恨，飞上银霄。","素秋不解随船去，败红趁、一叶寒涛。","梦翠翘。","怨鸿料过南谯。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","花"],"cats":{"抒情":["伤感"],"四季":["秋天"],"生活":["写桥"],"植物":["菊花"]},"theme_conf":0.497},{"uid":"080a9610-9c99-4c53-88ad-b299396e09cc","title":"寄刘方平大谷田家","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故山闻独往，樵路忆相从。","冰结泉声绝，霜清野翠浓。","篱边颍阳道，竹外少姨峰。","日夕田家务，寒烟隔几重。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"生活":["田野"]},"theme_conf":0.557},{"uid":"d4bba55e-36f1-47d1-96af-eb87264434f6","title":"贺收复秦原诸州诗","author":"白敏中","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一诏皇城四海颁，丑戎无数束身还。","戍楼吹笛人休战，牧野嘶风马自闲。","河水九盘收数曲，天山千里锁诸关。","西边北塞今无事，为报东南夷与蛮。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","楼","山"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.631},{"uid":"b84b8b0b-9447-467f-819f-0ddf0f00a03a","title":"相和歌辞 饮马长城窟行","author":"王翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长安少年无远图，一生惟羡执金吾。","骐𬴊前殿拜天子，走马为君西击胡。","胡沙猎猎吹人面，汉虏相逢不相见。","遥闻鼙鼓动地来，传道单于夜犹战。","此时顾恩宁顾身，为君一行摧万人。","壮士挥戈回白日，单于溅血染朱轮。","回来饮马长城窟，长安道傍多白骨。","问之耆老何代人，云是秦王筑城卒。","黄昏塞北无人烟，鬼哭啾啾声沸天。","无罪见诛功不赏，孤魂流落此城边。","当昔秦王按劒起，诸侯膝行不敢视。","富国彊兵二十年，筑怨兴徭九千里。","秦王筑城何太愚，天实亡秦非北胡。","一朝祸起萧墙内，渭水咸阳不复都。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆"],"scene":["夜","塞外"],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.803},{"uid":"cp266b10b82b6e56","title":"木兰花・玉楼春","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["秋千院落重帘暮。","彩笔闲来题绣户。","墙头丹杏雨馀花，门外绿杨风后絮。","朝云信断知何处。","应作襄王春梦去。","紫骝认得旧游踪，嘶过画桥东畔路。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花","楼"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.565},{"uid":"5c676620-1448-4ee7-815d-35512077d8ad","title":"郑典设自施州归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾怜荥阳秀，冒暑初有适。","名贤慎所出，不肯妄行役。","旅兹殊俗远，竟以屡空迫。","南谒裴施州，气合无险僻。","攀援悬根木，登顿入天石。","青山自一川，城郭洗忧戚。","听子话此邦，令我心悦怿。","其俗则纯朴，不知有主客。","温温诸侯门，礼亦如古昔。","敕厨倍常羞，杯盘颇狼藉。","时虽属丧乱，事贵赏匹敌。","中宵惬良会，裴郑非远戚。","群书一万卷，博涉供务隙。","他日辱银钩，森疎见矛戟。","倒屣喜旋归，画地求所历。","乃闻风土质，又重田畴辟。","刺史似寇恂，列郡宜竞惜。","北风吹瘴疠，羸老思散策。","渚拂蒹葭塞，峤穿萝茑幂。","此身仗儿仆，高兴潜有激。","孟冬方首路，强饭取崖壁。","叹尔疲驽骀，汗沟血不赤。","终然备外饰，驾驭何所益。","我有平肩舆，前途犹准的。","翩翩入鸟道，庶脱蹉跌厄。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":["幽峭","冲淡"],"mood":"欢愉","mood2":[],"scene":["塞外","冬","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","冬天"],"人生":["读书"],"生活":["边塞"]},"theme_conf":0.593},{"uid":"83648d7d-4cd5-4a8d-9df7-b3c8eb7bb1cc","title":"绝句漫兴九首 六","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["嬾慢无堪不出村，呼儿日在掩柴门。","苍苔浊酒林中静，碧水春风野外昏。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["酒","春"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":0.593},{"uid":"cp6df3966a4d64dc","title":"卜算子","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["驿外断桥边，寂寞开无主。","已是黄昏独自愁，更著风和雨。","无意苦争春，一任群芳妒。","零落成泥碾作尘，只有香如故。"],"theme":"羁旅思乡","theme2":[],"style":"旷达","style2":["婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","花","春","雨"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"939d5ee1-0a6a-4a4d-abc8-1566418ae232","title":"七夕见与诸孙题乞巧文","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["外孙争乞巧，内子共题文。","隐暎花匳对，参差绮席分。","鹊桥临片月，河鼓掩轻云。","羡此婴儿辈，欢呼彻曙闻。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.95},{"uid":"10ef9dd5-f761-4463-9d90-fa9a426ac89c","title":"横吹曲辞 关山月","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["秋月朗朗关山上，山中行人马蹄响。","关山秋来雨雪多，行人见月唱边歌。","海边漠漠天气白，胡儿夜度黄龙碛。","军中探骑暮出城，伏兵暗处低旌戟。","溪水连地霜草平，野𫘞寻水碛中鸣。","陇头风急雁不下，沙场苦战多流星。","可怜万国关山道，年年战骨多秋草。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","月","山"],"cats":{"四季":["秋天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.559},{"uid":"db40b5ca-03a8-4d1f-a4e4-cde477bee05e","title":"横吹曲辞 雨雪曲","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["边声四合殷河流，雨雪飞来徧陇头。","铁岭探人迷鸟道，阴山飞将湿貂裘。","斜飘旌斾过戎帐，半杂风沙入戍楼。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雪","雨"],"cats":{"天气":["写雨","写雪"],"生活":["边塞"]},"theme_conf":0.661},{"uid":"8aa36cc8-fec9-455c-91b7-23fc83cdddb1","title":"和张尹忆东篱菊","author":"李端","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["传书报刘尹，何事忆陶家。","若为篱边菊，山中有此花。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念"],"生活":["乡村"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.82},{"uid":"cp79ac7bfce7f15c","title":"满庭芳","author":"秦观","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晓色云开，春随人意，骤雨才过还晴。","古台芳榭，飞燕蹴红英。","舞困榆钱自落，秋千外、绿水桥平。","东风里，朱门映柳，低底按小秦筝。","多情。","行乐处，珠钿翠盖，玉辔红缨。","渐酒空金，花困蓬瀛。","豆蔻梢头旧恨，十年梦，屈指堪惊。","凭阑久，疏烟淡日，寂寞下芜城。"],"theme":"讽喻刺世","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["花","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"1dbf0b9d-bdb3-4ee1-9bbf-005087cefe54","title":"相和歌辞 决绝[词]三首 三","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["夜夜相抱眠，幽怀尚沈结。","那堪一年事，长遣一宵说。","但感久相思，何暇暂相悦。","虹桥薄夜成，龙驾侵晨列。","生憎野鹊往迟回，死恨天鸡识时节。","曙色渐曈昽，华星次明灭。","一去又一年，一年何时彻。","有此迢遰期，不如生死别。"],"theme":"爱情相思","theme2":["闲适隐逸","送别"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["爱情","思念"],"生活":["写桥"]},"theme_conf":0.357},{"uid":"5a30cdb0-aab8-4c0d-9ef3-78f7216ceb66","title":"酬袁太祝长卿小湖村山居书怀见寄","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["背江居隙地，辞职作遗人。","耕凿资余力，樵渔逐四邻。","麦秋桑叶大，梅雨稻田新。","篱落栽山果，池塘养海鳞。","放歌聊自足，幽思忽相亲。","余亦归休者，依君老此身。"],"theme":"山水田园","theme2":["送别"],"style":"豪放","style2":["旷达"],"mood":"恬淡","mood2":[],"scene":["山","江"],"cats":{"生活":["乡村"]},"theme_conf":0.607},{"uid":"0445f296-5816-4ab9-a617-7d8ed29088ea","title":"凉州词二首 一","author":"王翰","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["葡萄美酒夜光杯，欲饮琵琶马上催。","醉卧沙场君莫笑，古来征战几人回。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.626},{"uid":"45110b81-0f02-4c85-b72a-f2210d10c12f","title":"八哀诗 赠太子师汝阳郡王琎","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汝阳让帝子，眉宇真天人。","虬须似太宗，色映塞外春。","往者开元中，主恩视遇频。","出入独非时，礼异见群臣。","爱其谨洁极，倍此骨肉亲。","从容听朝后，或在风雪晨。","忽思格猛兽，苑囿腾清尘。","羽旗动若一，万马肃𬳽𬳽。","诏王来射雁，拜命已挺身。","箭出飞鞚内，上又回翠麟。","飜然紫塞翮，下拂明月轮。","胡人虽获多，天笑不为新。","王每中一物，手自与金银。","袖中谏猎书，扣马久上陈。","竟无衔橛虞，圣聪矧多仁。","官免供给费，水有在藻鳞。","匪唯帝老大，皆是王忠勤。","晚年务置醴，门引申白宾。","道大容无能，永怀侍芳茵。","好学尚贞烈，义形必沾巾。","挥翰绮绣扬，篇什若有神。","川广不可溯，墓久狐兔邻。","宛彼汉中郡，文雅见天伦。","何以开我悲，泛舟俱远津。","温温昔风味，少壮已书绅。","旧游易磨灭，衰谢增酸辛。"],"theme":"悼亡挽歌","theme2":["送别","边塞征战"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["月","塞外","雪"],"cats":{"抒情":["伤感","悼亡"],"天气":["月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.99},{"uid":"cpf018dd823a543a","title":"安公子","author":"袁去华","dynasty":"宋","section":"宋词","form":"词","paragraphs":["弱柳丝千缕。","嫩黄匀遍鸦啼处。","寒入罗衣春尚浅，过一番风雨。","问燕子来时，绿水桥边路。","曾画楼、见个人人否。","料静掩云窗，尘满哀弦危柱。","庾信愁如许。","为谁都著眉端聚。","独立东风弹泪眼，寄烟波东去。","念永昼春闲，人倦如何度。","闲傍枕、百啭黄鹂语。","唤觉来厌厌，残照依然花坞。"],"theme":"爱情相思","theme2":["闺情宫怨","送别"],"style":"婉约","style2":["沉郁"],"mood":"恬淡","mood2":["愁怨"],"scene":["春","雨","鸟"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.86},{"uid":"d9a9bf4b-fba8-424b-b81c-309bcdade7aa","title":"奉和裴令公新成午桥庄绿野堂即事","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["旧径开桃李，新池凿凤皇。","只添丞相阁，不改午桥庄。","远处尘埃少，闲中日月长。","青山为外屏，绿野是前堂。","引水多随势，栽松不趂行。","年华玩风景，春事看农桑。","花妬谢家妓，兰偷荀令香。","游丝飘酒席，瀑布溅琴床。","巢许终身稳，萧曹到老忙。","千年落公便，进退处中央。"],"theme":"应制干谒","theme2":["闲适隐逸","山水田园"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花","酒","月"],"cats":{"四季":["春天"],"山水":["瀑布"],"生活":["写桥"]},"theme_conf":0.97},{"uid":"cp8faa60807b632f","title":"临江仙","author":"陈与义","dynasty":"宋","section":"宋词","form":"词","paragraphs":["高咏楚词酬午日，天涯节序匆匆。","榴花不似舞裙红。","无人知此意，歌罢满帘风。","万事一身伤老矣，戌葵凝笑墙东。","酒杯深浅去年同。","试浇桥下水，今夕到湘中。"],"theme":"送别","theme2":["游仙梦幻","羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["酒","江","花"],"cats":{"抒情":["思乡","孤独"],"生活":["写桥"]},"theme_conf":0.366},{"uid":"786e30bf-b8a8-4067-a51c-1a5b522ed71d","title":"执契静三边","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["执契静三边，持衡临万姓。","玉彩辉关烛，金华流日镜。","无为宇宙清，有美璇玑正。","皎佩星连景，飘衣云结庆。","戢武耀七德，升文辉九功。","烟波澄旧碧，尘火息前红。","霜野韬莲劒，关城罢月弓。","钱缀榆天合，新城柳塞空。","花销葱岭雪，縠尽流沙雾。","秋驾转兢怀，春冰弥轸虑。","书绝龙庭羽，烽休凤穴戍。","衣宵寝二难，食旰餐三惧。","翦暴兴先废，除凶存昔亡。","圆盖归天壤，方舆入地荒。","孔海池京邑，双河沼帝乡。","循躬思励己，抚俗媿时康。","元首伫盐梅，股肱惟辅弼。","羽贤崆岭四，翼圣襄城七。","浇俗庶反淳，替文聊就质。","已知隆至道，共欢区宇一。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":["清新","绮丽"],"mood":"恬淡","mood2":["欢愉"],"scene":["冬","秋","园林","塞外","雪"],"cats":{"四季":["秋天"],"生活":["边塞"]},"theme_conf":0.767},{"uid":"a15343da-3f7e-4d97-8df0-6d9a5b567a40","title":"秋思二首 一","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["万木秋霖后，孤山夕照余。","田园无岁计，寒近忆樵渔。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"山水":["西湖"],"生活":["田野"]},"theme_conf":1.0},{"uid":"ed927451-c3fd-4566-97a2-c86f8c2fa756","title":"行官张望补稻畦水归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东屯大江北，百顷平若案。","六月青稻多，千畦碧泉乱。","插秧适云已，引溜加溉灌。","更仆往方塘，决渠当断岸。","公私各地著，浸润无天旱。","主守问家臣，分明见溪伴。","芊芊炯翠羽，剡剡生银汉。","欧鸟镜里来，关山云边看。","秋菰成黑米，精凿传白粲。","玉粒足晨炊，红鲜任霞散。","终然添旅食，作苦期壮观。","遗穗及众多，我仓戒滋蔓。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","七夕"],"cats":{"抒情":["思乡"],"四季":["秋天"],"山水":["长江"],"生活":["田野"],"节日":["七夕节"]},"theme_conf":0.531},{"uid":"b07e39b5-eafc-4493-a320-454e7a81149a","title":"玄都观","author":"蜀太后徐氏","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["千寻绿嶂夹流溪，登眺因知海岳低。","瀑布迸舂青石碎，轮茵横翦翠峰齐。","步黏苔藓龙桥滑，日闭烟罗鸟径迷。","莫道穹天无路到，此山便是碧云梯。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"6281fbf0-c461-4efe-ac5d-26e86d33fc49","title":"横吹曲辞 入塞曲 一","author":"沈彬","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["欲为皇王服远戎，万人金甲鼓鼙中。","阵云暗塞三边黑，兵血愁天一片红。","半夜飜营旗搅月，深秋防戍劒磨风。","谤书未及明君𦶟，卧骨将军已殁功。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.894},{"uid":"48b4fa8e-6535-4b54-a31d-853c3cc55431","title":"村居即事","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["休看小字大书名，向日持经眼却明。","时过无心求富贵，身闲不梦见公卿。","因寻寺里薰辛断，自别城中礼数生。","斜月照房新睡觉，西峰半夜鹤来声。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月","夜","山"],"cats":{"生活":["乡村"]},"theme_conf":0.473},{"uid":"bfbe3236-35b2-48c1-b9e2-8785bfbc2e09","title":"游长宁公主流杯池二十五首 二十三","author":"上官昭容","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["沁水田园先自多，齐城楼观更无过。","倩语张骞莫辛苦，人今从此识天河。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","酒"],"cats":{"生活":["田野"],"食物":["写酒"]},"theme_conf":0.65},{"uid":"4ece9f6a-9b24-427a-9ef7-dce93f2f388e","title":"横吹曲辞 出塞曲","author":"刘济","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["将军在重围，音信绝不通。","羽书如流星，飞人甘泉宫。","倚是幷州儿，少年心胆雄。","一朝随召募，百战争王公。","去年桑干北，今年桑干东。","死是征人死，功是将军功。","汗马牧秋月，疲兵卧霜风。","仍闻左贤王，更欲图云中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["塞外","秋"],"cats":{"四季":["秋天"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.827},{"uid":"da88e355-99df-4d78-9680-2f61b0bf8336","title":"秦州杂诗二十首 十","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["云气接昆仑，涔涔塞雨繁。","羌童看渭水，使客向河源。","烟火军中幕，牛羊岭上村。","所居秋草净，正闭小蓬门。"],"theme":"边塞征战","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","秋","雨"],"cats":{"四季":["秋天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":0.481},{"uid":"56c66dee-7bd0-403b-81a4-6b5d552e776d","title":"相和歌辞 燕歌行","author":"贾至","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["国之重镇惟幽都，东威九夷制北胡。","五军精卒三十万，百战百胜擒单于。","前临滹沲后沮水，崇山沃野亘千里。","昔时燕王重贤士，黄金筑台从隗始。","倏忽兴王定蓟丘，汉家又以封王侯。","萧条魏晋为横流，鲜卑窃据朝五州。","我唐区夏余十纪，军容武备赫万祀。","彤弓黄钺授元帅，垦耕大漠为内地。","季秋胶折边草腓，治兵羽猎因出师。","千营万队连旌旗，望之如火忽雷驰。","匈奴慑窜穷发北，大荒万里无尘飞。","隋家昔为天下宰，穷兵黩武征辽海。","南风不竞多死声，鼓卧旗折黄云横。","六军将士皆死尽，战马空鞍归故营。","时迁道革天下平，白环入贡沧海清。","自有农夫已高枕，无劳校尉重横行。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["豪放","雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","夏"],"cats":{"四季":["夏天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.626},{"uid":"a44cd68d-3b13-4e10-bbf4-035abc5948a4","title":"登楚州城望驿路十余里山村竹林相次交映","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["十里山村道，千峰栎树林。","霜浓竹枝亚，岁晚荻花深。","草市多樵客，渔家足水禽。","幽居虽可羡，无那子牟心。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"生活":["乡村"],"植物":["竹子"]},"theme_conf":0.562},{"uid":"9202aa26-8e4f-4828-9fdc-237729e175f7","title":"塞下曲五首 三","author":"张仲素","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朔雪飘飘开鴈门，平沙历乱卷蓬根。","功名耻计擒生数，直斩楼兰报国恩。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"抒情":["爱国"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"98ce6f68-fa8f-42b6-a5d6-5447079d3a04","title":"相和歌辞 公无渡河","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["渡头恶天两岸远，波涛塞川如叠坂。","幸无白刃驱向前，何用将身自弃捐。","蛟龙啮尸鱼食血，黄泥直下无青天。","男儿纵轻妇人语，惜君性命还须取。","妇人无力挽断衣，舟沈身死悔难追，公无渡河公自为。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["塞外","舟"],"cats":{"抒情":["怀古"],"山水":["江河"],"生活":["边塞"]},"theme_conf":0.55},{"uid":"cp8aaa92b7ad5aae","title":"夜飞鹊・夜飞鹊慢","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["河桥送人处，凉夜何其。","斜月远堕馀辉。","铜盘烛泪已流尽，霏霏凉露沾衣。","相将散离会，探风前津鼓，树杪参旗。","华骢会意，纵扬鞭、亦自行迟。","迢递路回清野，人语渐无闻，空带愁归。","何意重红满地，遗钿不见，斜径都迷。","兔葵燕麦，向残阳、欲与人齐。","但徘徊班草，欷酹酒，极望天西。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["夜","鸟"],"cats":{"抒情":["伤感"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"08dc6c3a-07bc-479a-9bbe-4225ff0352e6","title":"忆幼子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骥子春犹隔，莺歌暖正繁。","别离惊节换，聪慧与谁论。","涧水空山道，柴门老树村。","忆渠愁只睡，炙背俯晴轩。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["离别","思念"],"四季":["春天"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.638},{"uid":"23b288e3-01d9-4688-8f00-8572431a2819","title":"同乐天和微之深春二十首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["何处深春好，春深阿母家。","瑶池长不夜，珠树正开花。","桥峻通星渚，楼暄近日车。","层城十二阙，相对日西斜。"],"theme":"亲情","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"b6210ab6-af10-41ce-b847-ad41e94aaf8a","title":"送钱拾遗归兼寄刘校书","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["墟落岁阴暮，桑榆烟景昏。","蝉声静空馆，雨色隔秋原。","归客不可望，悠然林外村。","终当报芸阁，携手醉柴门。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","雨","楼","酒"],"cats":{"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.496},{"uid":"0f5d3f4a-dbf2-4831-b658-e75bd4a0ca38","title":"羌村 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晚岁迫偷生，还家少欢趣。","娇儿不离膝，畏我复却去。","忆昔好追凉，故绕池边树。","萧萧北风劲，抚事煎百虑。","赖知禾黍收，已觉糟床注。","如今足斟酌，且用慰迟暮。"],"theme":"山水田园","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["酒"],"cats":{"抒情":["思念"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.405},{"uid":"f5b4927a-9a37-4e40-87ee-e75fff02d48a","title":"横吹曲辞 陇头水","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["陇坂高无极，征人一望乡。","关河别去水，沙塞断归肠。","马系千年树，旌悬九月霜。","从来共呜咽，皆是为勤王。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["塞外","月"],"cats":{"抒情":["思乡"],"生活":["边塞"]},"theme_conf":0.356},{"uid":"7066e611-faa5-427c-8fce-e0bf10c55416","title":"杂曲歌辞 盖罗缝 一","author":"不详","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["秦时明月汉时关，万里征人尚未还。","但愿龙庭神将在，不教胡马渡阴山。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["悲慨","豪放"],"mood":"慷慨","mood2":[],"scene":["山","月"],"cats":{"天气":["月亮"],"生活":["边塞"]},"theme_conf":0.573},{"uid":"995a9440-f8e3-4a9b-843d-27a34ea8b671","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["伐竹为桥结构同，褰裳不涉往来通。","天寒白鹤归华表，日落青龙见水中。","顾我老非题柱客，知君才是济川功。","合欢却笑千年事，驱石何时到海东。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["冬","江"],"cats":{"四季":["冬天"],"天气":["太阳"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.52},{"uid":"81c77b01-47cd-4aba-a980-5bc74b5b9711","title":"狂夫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万里桥西一，草堂，百花潭水即沧浪。","风含翠筿娟娟静，雨裛红蕖冉冉香。","厚禄故人书断绝，恒饥稚子色凄凉。","欲填沟壑唯疎放，自笑狂夫老更狂。"],"theme":"民生疾苦","theme2":["亲情"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["愁怨","欢愉"],"scene":["花","雨","山"],"cats":{"抒情":["伤感"],"人物":["儿童"],"生活":["写桥"]},"theme_conf":0.49},{"uid":"8e1e7b7e-1824-402a-8ef1-ada1b0490f58","title":"秋野五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋野日疏芜，寒江动碧虚。","系舟蛮井络，卜宅楚村墟。","枣熟从人打，葵荒欲自锄。","盘餐老夫食，分减及溪鱼。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"生活":["田野"]},"theme_conf":0.508},{"uid":"f54ce551-a776-477b-b9a7-0a5896fa2325","title":"屏迹三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["用拙存吾道，幽居近物情。","桑麻深雨露，燕雀半生成。","村鼓时时急，渔舟个个轻。","杖藜从白首，心迹喜双清。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["舟","雨"],"cats":{"生活":["乡村","田野"]},"theme_conf":0.508},{"uid":"64d3f88f-ce69-4ea3-8646-5635a7ed9139","title":"江村即事","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["钓罢归来不系船，江村月落正堪眠。","纵然一夜风吹去，只在芦花浅水边。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"e74b2d34-c0a4-4049-a02d-b2d9aa00fd80","title":"横吹曲辞 幽州胡马客歌","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽州胡马客，绿眼虎皮冠。","笑拂两只箭，万人不可干。","弯弓若转月，白雁落云端。","双双掉鞭行，游猎向楼兰。","出门不顾后，报国死何难。","天骄五单于，狼戾好凶残。","牛马散北海，割鲜若虎餐。","虽居燕支山，不道朔雪寒。","妇女马上笑，颜如赪玉盘。","飜入射鸟兽，花月醉雕鞍。","旄头四光芒，争战若蜂攒。","白刃洒赤血，流沙为之丹。","名将古谁是，疲兵良可叹。","何时天狼灭？父子得闲安。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁","绮丽"],"mood":"恬淡","mood2":["孤寂","慷慨"],"scene":["鸟"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.574},{"uid":"1ba275a5-93d8-4d90-9367-7192e01dae10","title":"塞下曲","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见芳树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟守空闺。","独宿自然堪下泪，况复时闻鸟夜啼。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["塞外","鸟"],"cats":{"抒情":["伤感","孤独"],"人生":["战争"],"生活":["边塞"],"节日":["中秋节"]},"theme_conf":0.824},{"uid":"7e26f9c9-ef6f-4b26-bf34-c683d1e41786","title":"杂曲歌辞 长相思","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["九月西风兴，月冷霜华凝。","思君秋夜长，一夜魂九升。","二月东风来，草坼花心开。","思君春日迟，一日肠九回。","妾住洛桥北，君住洛桥南。","十五即相识，今年二十三。","有如女萝草，生在松之侧。","蔓短枝苦高，萦回上不得。","人言人有愿，愿至天必成。","愿作远方兽，步步比肩行。","愿作深山木，枝枝连理生。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋","春"],"cats":{"抒情":["爱情","思念"],"四季":["春天","秋天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"cpc38bcb93c5acea","title":"谢金莲诗酒红梨花・隔尾","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["我为甚商抄过绿径慌忙迸，我则怕迟到蓝桥淹了尾生。","则这窃玉偷香的急心性。","冷落了那画屏，香消了宝鼎，这其间倚定鸳鸯枕头儿等。","(梅香云)姐姐，可早来到也。","俺和你过去。","(赵汝州慌迎科，云)小娘子来了也。","(正旦云)秀才，妾身无甚么礼物，则这一樽酒一瓶花儿，朵与你回礼。","(赵汝州云)小娘子，小生久等多时了也。","(正旦云)梅香，你先回去。","则怕夫人问着，你可支吾咱。","(梅香云)理会得，我先回去也。","(下)(正旦云)秀才，你认的这瓶花么？(赵汝州云)小娘子，这瓶花是甚么花？(正旦云)你试猜咱。","(赵汝州云)敢是海棠花么？(正旦唱)。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["酒","花"],"cats":{"抒情":["闺怨","感恩"],"生活":["写桥"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.566},{"uid":"84b9a130-8145-4902-aac7-5779c17e3fef","title":"饮马长城窟行","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["塞外悲风切，交河冰已结。","瀚海百重波，阴山千里雪。","迥戍危烽火，层峦引高节。","悠悠卷斾旌，饮马出长城。","寒沙连骑迹，朔吹断边声。","胡尘清玉塞，羌笛韵金钲。","绝漠干戈戢，车徒振原隰。","都尉反龙堆，将军旋马邑。","扬麾氛雾静，纪石功名立。","荒裔一戎衣，灵台凯歌入。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["绮丽"],"mood":"恬淡","mood2":["悲怆"],"scene":["冬","塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":1.0},{"uid":"4fa92777-9bd6-45ca-9272-bac30459cf5e","title":"金陵五题 乌衣巷","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朱雀桥边野草花，乌衣巷口夕阳斜。","旧时王谢堂前燕，飞入寻常百姓家。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["怀古"],"生活":["写桥"]},"theme_conf":0.738},{"uid":"7715e2f7-4e7e-4794-942e-bfbad57f953d","title":"燕歌行","author":"屈同仙","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见渔阳八月塞草腓，征人相对并思归。","云和朔气连天黑，蓬杂惊沙散野飞。","是时天地阴埃遍，瀚海龙城皆习战。","两军鼓角暗相闻，四面旌旗看不见。","昭君远嫁已年多，戎狄无厌不复和。","汉兵候月秋防塞，胡骑乘冰夜渡河。","河塞东西万余里，地与京华不相似。","燕支山下少春晖，黄沙碛里无流水。","金戈玉剑十年征，红粉青楼多怨情。","厌向殊乡久离别，秋来愁听捣衣声。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["鸟","塞外","秋"],"cats":{"抒情":["离别","思念","伤感","感恩"],"四季":["秋天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.592},{"uid":"d531f315-bcc5-45b6-af4d-8752eef92780","title":"横吹曲辞 陇头水 一","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["陇头心欲绝，陇水不堪闻。","碎影摇枪垒，寒声咽帐军。","素从盐海积，绿带柳城分。","日落天边望，逶迤入塞云。"],"theme":"边塞征战","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"]},"theme_conf":0.597},{"uid":"1e3e6d44-452e-4d2a-a4ef-1432ea95da22","title":"舞曲歌辞 白纻辞三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["扬清歌，发皓齿，北方佳人东邻子。","且吟白纻停渌水，长袖拂面为君起。","寒云夜卷霜海空，胡风吹天飘塞鸿。","玉颜满堂乐未终，馆娃日落歌吹蒙。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","夜"],"cats":{"人物":["女子"],"生活":["边塞"]},"theme_conf":1.0}];
